/* 平成13年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h13.committeeSessions.push(...[{"id":"h13-20010702-8","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"建設委員会","time":"午前１０時１１分～午後１時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"つまんない質問なんですけれども、駅の駐車場のコアというんですか、その上に乗っていますね。構造的に言うと、基礎杭というのはどうなんですか、ただ乗っかっているだけというわけじゃなくて、やっぱり下に当然基礎杭が入ると思うんだけれども、この下の断面図から見ると、真上にするーと伸びてきているだけで、コアの上に乗っかっているのかどうなのか、わかったら教えてください。","respondent":"岩田管理工事課長","answer":"したがいまして、その空洞を利用しまして、そこに鉄筋コンクリート造の駐輪施設を地下につくるということで、まだ現場自体は鉄建公団の工事中の現場の中ということでございまして、当然現在の土どめ杭や、それから地上を車が走っておりますので、覆工板と言いますけれども。","voiceIndex":7,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"それを聞いたのは、契約上の問題で、７億円からの契約金額ですから、普通は競争入札にするんだけれども、随意契約にする場合の条件みたいなものがあるので、この場合は一体化で現在工事中だというのはわかるんだけれども、具体的にはどういう文言になっているのかなというのがわかったら教えてほしいというふうに考えたんですが、これはどっちかと言うと総務のほうかもしれないから結構です。","respondent":"伊佐都市計画課長","answer":"平成１４年１２月の開業に向けて、工事が最盛期を迎えておりますし、特に遅れていることがないように聞いております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"りんかい線に係る区役所から大崎に行く間の夜間の通行止めというのは、相当長期間にわたっているんですけれども、あれはいつごろ終わるんですか。","respondent":"岩田管理工事課長","answer":"手元に資料がございませんので、現在あそこの夜間通行止めについては、公共下水道の戸越幹線の切り回し工事と、りんかい線そのものの工事と輻湊しながら交通規制をかけておりますので、この辺の細かいことにつきましては、後ほど資料を取り寄せまして。","voiceIndex":11,"id":"exchange-003"},{"speaker":"辻委員","kind":"意見","question":"駐輪場の料金についてはどういう──これは多分鉄建公団に委託しているという形になろうかと思うんですけれども、駐輪場自身の管理というのは区の問題として考えるのか、それとも鉄道事業者と考えるのか、自転車の料金とか。やっぱり、これからバイクも当然増えていきますので、この辺も配慮されているのか。","respondent":"岩田管理工事課長","answer":"料金につきましては、まだ検討中ですが、先般駐輪場の条例を改正させていただきまして、１台当たり月極め２,５００円を上限というふうにお認めいただいておりますので、２,５００円を超えない範囲内で料金設定はしてまいりたいということです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、それなりに保管にもお金をかけてきちんとした方法でやっていったほうが、有利であると思う。時間はまだありますのでね。ですから、やはりバイクの需要というものをきちっとつかんでやっていただきたいと思います。北品川のほうから天王洲へ行くとなったら、やっぱり自転車よりも若い人だったらバイクというのも、当然大きな流れかなと思いますけれども、その辺についてはいかがでしょうか。","respondent":"岩田管理工事課長","answer":"後ほど他の駐輪場施設の有料化の状況につきましても、ご説明をしますけれども、現在無料の駐輪施設につきましても、非常に利用勝手が悪いというようなご批判も多々いただいておりますので、きちっと気持ちよく使っていただいて。","voiceIndex":15,"id":"exchange-005"},{"speaker":"辻委員","kind":"意見","question":"バイクですけれども、若い人がバイクに乗っているんですけれども、最近大型が非常に増えてくるんですね。最初、原付が結構並んでいると思っても、そのうち１台大きいのが入ると、次にはどおーとなる。スタートの段階でこういう部分の使い方と、需要予測というのをきちんとやっていかないといけないなと思いますので、その辺は調査してお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"築舘委員","kind":"意見","question":"自転車の駐輪場ということで、今度有料化するということで３００台ということですけれども、今まで無料の駐車場が何台ぐらい入れる駐車場があって、どういった形で現状があるのかと。それから、今後２万人の乗降客が見込まれるということで、３００台で間に合うというふうに見ていらっしゃるのか、どういうふうな形で、今後の２万人のうち自転車を使って駅まで来る人の見込みをしていらっしゃるのか。","respondent":"岩田管理工事課長","answer":"今回、駐輪場がきちっと整備されますので、放置自転車禁止区域の設定をしまして、きちっとした撤去活動もあわせて行っていくです。それから、全線開業後の見込みですが、現在はこの資料のとおり、当面は３００台をきちっと収容できるような施設として見込んです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"今、放置自転車は撤去されていないというとこで、今後はそういうふうにされていくということでありますと、やはり重要な駅の周辺ということですから、私も近くなものですからたまに通ったりしますけれども、自動車があそこはすごく頻繁に通っていますし、よく工事もしているのでいろいろあれなんですけれども、有料にするということになったら、ある程度自転車に対する整備というんですか。","respondent":"岩田管理工事課長","answer":"天王洲周辺の道路につきましては、全部都市計画道路に囲まれている地区でございまして、基本的には３ｍ以上の歩道が整備されておりますし、アイル地区につきましては壁面線後退の建物に義務づけておりますので、道路自体の歩道プラスセットバックした歩道状空地等で。","voiceIndex":20,"id":"exchange-008"},{"speaker":"横山副委員長","kind":"意見","question":"朝はほとんど下りる人ばかりだと思うんです。帰りはまばらになるんだけれども、地方へ行くとそれに対してエレベーターを設置してあったり、両脇にラックをかけて楽に上がれるようになっていて、その上、対面しないでけががあってはいけないということで、一方通行的な回り方を配慮してつくられている部分を見てきたんだけれども、ここの場合はどういう想像をしたらいいのかなと。","respondent":"岩田管理工事課長","answer":"これは消防法の関係で、二方向避難ができなければいけませんので、非常口という形で設置をする予定なんですが、ただ特に朝、時間的に集中してご利用客がいらっしゃるときのことを想定していまして、一応Ｂ階段も午前中ぐらいは使えるような形で現在考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"横山副委員長","kind":"質問","question":"そうすると、Ａ階段だけですか。要するに、危険というか、勢いよく下りてくる人と、ゆっくりそういう形で上がってくる人との対面が考えられるんだけれども、その辺は危険がないのかなという心配から質問させていただいているんです。要するに、下りる人はそのまま自転車に乗ったまま下りるかという、その辺のところも想像だけさせてください。","respondent":"岩田管理工事課長","answer":"したがって、エスカレーターを利用されるのは上り専用ですので、下りる方は当然自転車を降りて、下りる方向に向かって右側のスロープをブレーキをかけながら階段で下りていただくという形になります。幅員ですけれども、階段部分の有効幅員が約２ｍで考えてあります。","voiceIndex":24,"id":"exchange-010"},{"speaker":"横山副委員長","kind":"質問","question":"けがとかないように、下りる人は自転車から降りて下りられるようですから、その心配はないと思うんですけれども、要するにほかの施設でもそうなんだけれども、車を持ち上げていくモーターのほうは、左右に欲しいという部分がある。さっきも言うように、地方だとそういった面だと思うんだけれども、そういった配慮をされて設備されているところはあちこちで見てきましたので、参考までにということで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"上山委員","kind":"質問","question":"これはいつ頃池の活用をするんですか。どのぐらいになるような予定なんですか。これで言うと、掘削工事をやったり、工程表を見ますと、平成１４年に公園工事が１４年４月ぐらいから始まるようになっていますけれども、実際に活用と言いましょうか、その辺がどれぐらいになるのかということを伺えますか。","respondent":"北村下水道河川課長","answer":"こちらの工事の中で、その１、その２、その３という三つの工事が調整池の工事と、それに導きます下水道管の工事です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"上山委員","kind":"質問・要望","question":"実際、かなり大きな工事になるかと思いますので、あの辺の住民は皆さん「早くつくってくれ」と、私も幾つか声を聞きますし、ある意味では期待されている工事ですので、早く完成されることは私も非常にうれしいんですけれども、いろいろな工事があるかと思いますので、住民の要望がいろいろありましたら聞いていただいて、対応していただければなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"５０ミリ降雨を想定して、ある程度呑み込めるというふうになっているのか、そういうことをもう少し教えてほしいと思います。それから、もう一つ、これを全部ピークカットして、ここに水を呑み込んだ後は、ポンプで排水しますね。これを見るとポンプ場みたいなのが──わからないんですけれども、どうなるのかというのを教えてもらえますか。","respondent":"北村下水道河川課長","answer":"降雨との関係ですけれども、一般的に５０ミリ対応ということがいろいろ言われるわけですが、貯留の場合には若干違った概念になってまいります。","voiceIndex":34,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"１時間ばっとなったらなかなかないから、もう少し余裕があるのかなという気がするんですけれども、平成１１年１１月２７日の３２ミリですか、これは大丈夫なのかなという気が率直にするんですけれども、時間がピークの本当に短いところをカットしてやれば大丈夫だというので、余裕があるのかどうなのか、もう少しその辺の考えを教えてほしいのが一つ。","respondent":"北村下水道河川課長","answer":"そういったような雨につきましては、大規模な幹線もつくる、それができれば一番ベターなんですけれども、非常に時間もお金もかかりますので、そういう短時間の雨であれば、それほど大きな容量でなくても一時的に貯留池があれば。","voiceIndex":36,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"限られた容量しかなくて、満杯になったら効力がなくなっちゃうようで、どこの時点で取り入れていくか。例えば、こういうピークが二つある雨に対して、最初のところで入れたら、あとは全然──その辺の判断はどこがどうやってやるんでしょうか。何か自動的に呑み込むをやっちゃうのかどうなのか、ちょっと教えてもらえますか。","respondent":"北村下水道河川課長","answer":"これは当然無人で区にある施設ですので、人為的に操作をして水を入れるとか入れないとかということはできません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"この水域権利者という方と、港湾管理者というのは、具体的にはどういった方々なんですか。","respondent":"北村下水道河川課長","answer":"水域占用者の方々ですが、公的な機関としましては海上保安庁、それから一部護岸を所有しています東京都港湾局、それからそのほかに屋形船等の営業をされている方々ということで、占用許可を取ってあの地域に係留している方々等が約４名ほどいらっしゃいます。","voiceIndex":45,"id":"exchange-017"},{"speaker":"築舘委員","kind":"質問","question":"移転が大体整ったということで、どこに移転されていくようなことなんですか。","respondent":"北村下水道河川課長","answer":"説明資料の裏をご覧いただきたいと思いますが、赤で囲っております領域が今回の工事範囲です。黒のハッチがかかっている部分が、既に埋立を完了している部分ですが、鮫洲入江の中に従前いろいろな権利者がいらっしゃったという格好です。","voiceIndex":47,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"私、忘れちゃんたんですけれども、埋め立てしたところにさっきの貯留池をつくって、鮫洲幹線だか何かの、そういう計画がありましたよね。その辺をもうちょっと説明していただきたいのと工期が８カ月ぐらい遅れたことについて、その計画全体に及ぼす影響はどのぐらいあると予想されているわけですか。","respondent":"北村下水道河川課長","answer":"８カ月程度確かに埋立工事は遅れてありますが、まだ全体の建設工事がかなりの年数がありますので、具体的な稼働時期がこれで遅れるとか、そういう状況にはまだ至っていないと理解しております。","voiceIndex":49,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"９月１日から受付開始というふうに聞いたんですが、共用開始というのはいつでしたか、９月１日からですか、ちょっと聞き落としたので。ここに書いてあるのか、１０月１日だ。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-020"},{"speaker":"菅家委員","kind":"意見","question":"従前の中で、確かに地方へ行って改めて、これは地方だからできるんだなと言いつつも参考になる部分が大変多かったこともありますし、今、私どもが考えるには、やっぱり何と言っても既にプランができている中央公園が中心だろうと思うんですけれども、２３区の場合はこれだけの大きなスペースの新しい公園用地を取得して造成するのは品川区以外にないと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-021"},{"speaker":"辻委員","kind":"意見","question":"時期がいつになるか、というのは大体三定が終わった後ぐらいですよね。今日、暦を持ってないので一概に言えない。今、言ったように、自転車の駐輪場というのは地下方式か、地方でものすごく──滋賀県でしたか、非常にユニークにやっていたみたいに……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-022"},{"speaker":"辻委員","kind":"意見","question":"仙台も大きいのがあったんです。ただ、するっとしか通っていないから、中がどういうのか細かいことは聞いていないんですけれども……。いろいろなテーマをそれぞれ出し合って選んでいけばいいので、今日いきなりとなると、あれって思う。時期的に三定の終わった後ぐらいか、もう少し時間的に余裕があるので、もう少しそれぞれが情報を入手してやればという感じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-023"},{"speaker":"横山副委員長","kind":"質問","question":"参考までに、去年は地下駐車場は大阪の岸和田市ですばらしいそういうもの見てきているんです。今、公園も去年の話題になったんです。ですから、公園もかなり見て来ましたし、今の駐輪場の問題も見てきましたけれども、委員会構成が変わって、また新しい見方というのもあるでしょうから、それは構わないと思うんですけれども、去年はそんな形で委員会の行政視察を決定した覚えがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"沢田委員","kind":"意見","question":"この委員会の発足のときにちょっと私が言ったところなんですけれども、行政視察の視察場所と、１年間建設委員会で力を入れて調査研究するテーマというのは、一緒のほうがいいと思うんです。そういう点からすると、後先になるかもしれないけれども、テーマをどうするのかというのを見ながら視察テーマを決める。これはテーマだけですけれども、場所は何とも言えないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-025"},{"speaker":"築舘委員","kind":"意見","question":"まだ先の話なので、これからテーマが固まれば、それに則した形で私たちはいろんな分野で興味を持っておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-026"},{"speaker":"上山委員","kind":"意見","question":"今日のに直接あれでないんですけれども、明日の請願とかに出されているように、毎回のようにマンション建設とかそういうことで出されたり、品川区内でも建築紛争を出されたりしていますし、ある意味ではどういうまちというか住宅問題で言えば、ある意味で言えば皆さんの納得できるようなまちづくりとか計画を含めてなんですけれども、そういうことをやっているところがあれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-027"},{"speaker":"菅家委員","kind":"質問・要望","question":"だから、その辺をよく協議しながら、大体日程の関連については２泊３日ぐらいでしょうから、そんなにとんでもないコースは考えられないわけですよ。だから、そういう意味では、まずテーマを何と何に取り上げるか、その辺の何か資料を取り寄せて、さらに目を通して視察場所を決めるというような手順だけは決めておいていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"横山副委員長","kind":"質問・要望","question":"やっぱり、委員は忙しいから、大体日にちがどこの範囲でやらなくちゃいけないという、自ずから決まってきちゃうんだろうと思うんだけれども、やっぱり日程調整をしておかないと、これだけ大勢の委員ですから、やはりすべての人に出ていただきたいということが前提で進めなくちゃいけないので、あんまり詰まってきちゃうと、もう入っちゃったなんていうような形だと困るので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-029"},{"speaker":"沢田委員","kind":"意見","question":"ずっと出たから、それを勘案しながら、正副委員長でこんなものでどうかというもの出してもらえれば、そうみんながみんな全部やったらぐちゃぐちゃになっちゃうものね。どこかに絞ってやるしかないし、ある程度方向性は同じ方向にしないと、ある程度限定されることはしようがないですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3692#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":24576,"voices":84}},{"id":"h13-20010702-9","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"文教委員会","time":"午前１０時１０分～午後０時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)平成１３年度「通学区域の弾力化」に関するアンケート調査結果につきまして","agenda":"の(1)平成１３年度「通学区域の弾力化」に関するアンケート調査結果につきまして","exchanges":[{"speaker":"高星委員","kind":"質問","question":"中学校のほうは初めての中身だけれども、小学校は２回目、弾力化の適用という意味合いで、一つは獲得目標、学校の全体状況が安定化の方向に向かうというのは、大きなねらいだったというふうに思うけれども、その辺のところはどういうふうに、１年経過して総括をされているのかということだけは一番気になるところですので、お聞きしたいと思います。","respondent":"久保田学務課長","answer":"いずれにしましても、今後私どもとしては、こうした学校のそれぞれの取り組みなり、あるいは地域の取り組みにも最大の支援をしていって、もっと充実したものにしていきたいというふうに考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"一つの大きな、画期的な、先駆的な事業だったわけで、それだけ見てみますと、先ほど評価というように言われたけれども、中身は別にして、プラン２１フォーラムについては、取ってくっつけたような日程的な問題という大きな問題があったわけだけれども、あれは教育委員会も相当焦っているなという感じをしたわけだけれども、それはそれで中身がよかったから、良しとするけれども、現場における校長を初め。","respondent":"青木指導課長","answer":"それぞれの学校のプラン２１の取り組みにつきましては、校長先生方から私ども、それぞれの学校の取り組みについてはその都度お伺いをしております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ伺わせていただきます。それで、教育委員会の考え方、このデータの中で、１点だけ伺いますけれども、２ページのＱ４の２番の「中学校のように区内全域から選択したい」と、これは小学校はまだ登録制ですから、そのことを指して言っているんだと思います。半分わかっていて聞くんですけれども、小学校を区内全域にしない現況の考え方を教えていただきたいと思います。","respondent":"久保田学務課長","answer":"２年目を経過しまして、かなりこの制度が区民の間に浸透して、中学校は全域だというような、そういうような実績もでき上がってまいりましたので、率直な区民の皆さんのお考えはということで、お聞きしたわけですけれども、現状のままでいいというのが約半分ですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"９９％保護者です。１％ぐらいは、あの子と一緒に学校に行きたいというのがありますから、それなんですけれども、情報関係というより、むしろ学校公開の情報ではなく、知人、友人からの情報ということでの、人気投票みたいなものでしようがないんだというふうに思うんですけれども、それでも学校は特色ある学校づくりのためには、学校間としても行き来できるのかどうかという面はどうでしょうか。","respondent":"久保田学務課長","answer":"冒頭若干ご説明をさせていただきましたけれども、昨年のアンケートで一番学校の情報を得たということで高かったのは、トップは友人からの情報です。今年は３位に下がったということも、私どもこれは大きな意味合いがあるだろうというふうに思っております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"もう一つは、例えば今回の中学校を入れて、中学校によっては大きく影響というんでしょうか、選択制によって、これまで少しずつ減少ぎみの学校が多く出る。このことについて親には問うてないんですけれども、この結果によって、例えば学校への指導というんでしょうか、選択制のもたらした結果によっての多く変化を受けた学校への指導というのはどういうふうにされていますか。そのあたりをお願いします。","respondent":"久保田学務課長","answer":"そのための指導というか、私どもの支援というのも、今後ますます努力していきたい、こんなふうに今考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"それと、増えたも、減ったもあまり関係ないという、そこがよくわからないんですけれども、実際にこの数字を、増えた、減ったということによって、教育委員会としては選択制が広がったと理解されたと見ているわけでしょう。学校側にとって減った、増えたということが、どういうふうな影響を持っているかというのを、もうちょっと分析されていくのが必要だと思うんですけれども、いかがですか。","respondent":"久保田学務課長","answer":"つまりそれぞれの学校が自分の学校の取り組みというのをやってきているわけですから、それは最大限評価して、そういうものに対する支援を続けていくというような立場だということです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"それが顕在化したという、そういう点は非常に分かるんですけれども、私むしろ問題にしていくのは、第２ステップとして、今特色ある学校づくりという、ここのところは本当に勝負どころだというふうに思っているわけです。私はそういう視点を持っているわけですけれども、それについてのコメントをいただきたいと思います。","respondent":"青木指導課長","answer":"大規模校、小規模校それぞれの魅力の中から選択する必要があるんですねというような認識をお持ちの親御さんたちが増えてまいりました。そういう意味で、単なる大規模校がいいんだというような形から、それぞれの規模に魅力があるんだ、持ち味があるんだと。","voiceIndex":17,"id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"そういう点で、今後どういうふうに考えればいいのか。もう１点は、３枚目の、中学校１年生の生徒の質問の中で、１５番目になります。もう１点は、参考のために、「あなたは、どのような方法で学校の情報を得ましたか」という質問の中で、その他とあります。小学校と中学校で多少違うみたいですけれども、どういうものがあるか教えていただけますか。","respondent":"久保田学務課長、青木指導課長","answer":"そういう点では、今プラン２１推進委員会の中でも、新たな課題として、三つほど作業部会を設けてまた検討をしていくというふうになってありますので、詳しくは指導課長のほうからお話ししますけれども。現在、プラン２１推進委員会の中に、ある課題について改めて作業部会を設置して、その課題について検討をするというような形で、５月からスタートをさせた作業部会があります。三つあります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"３点の作業部会の話が出ましたけれども、この作業部会の内容は、全体に一律にこれから現場でやっていくということですか。その辺に対しての将来の見込みといいますか、考え方をしているものと、２番目の期待感が薄くなってきた、確かにそれは感じるんですけれども、もっと教育で言う角度から捉えた場合に、人間対人間ということの深みのふれあいというんですか、その辺に対してはどういう指導をされているか。","respondent":"青木指導課長、久保田学務課長","answer":"見込みですが、この作業部会は来年度のプラン２１の推進に当たってのベースをつくっていくものですので、その予定で今進めているところです。生徒の５番目の質問のところの、その他ですけれども、私は答弁を漏らしているところがありました。","voiceIndex":22,"id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"１番目と３番目は分かりました。２番目の、部活なり、あるいは学校の勉強を目指す、数学が得意だとか、英語が得意だとか、そういう人もいると思います。選択ができるような、先生方といいますか、人の情報提供がより一環教育にもつながっていきますけれども、そういう指導といいますか、そういうことに対する今後の考えはいかがでしょうか。","respondent":"青木指導課長","answer":"学校公開とそれを抱き合わせて、そういう体験入学とか、体験入部とかというような、そういう経験を通して子どもたちは中学校の選択というものを実際に体で感じながら行っていけるというふうに考えております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"山路委員","kind":"意見","question":"体験入学で、いい先生だ、私はこれを目指そうという子どもは出てくると思うんです。それで結構なんですけれども、子どもの能力を引き出すということで、情報量をもっと豊かにということを、最後にお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"実際に一番近いのはブロックを超えて学校が近いという方がいるので、そこら辺どの程度の説明がされているのか、それが１点。そっちに受験を振り向けちゃって、中学校はそこまで考えていないよという意味でとっちゃっているんでしょうか。そこら辺がちょっと気になるんですけれども、その２点お伺いいたします。","respondent":"久保田学務課長、青木指導課長","answer":"去年の指定校変更の数は９６件あったんですけれども、今年は９２件ということで、大体同じような数になってあります。ただ、中学校は１８校ありますけれども、その１８校が大きく差があるということではございませんので、あえてそういう意味でのこういうような数字が出てきているのではないかなというふうに思っています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"小学校は別にして、中学校から高校へ入るときというのは、あまり中学校は期待されていないんじゃないかなという意識が見えるし、ある程度我々の仲間の中でも話が出てくるので、少なかったのが意外だったので、ちょっとお聞きしたんですけれども、全体的にそれだけレベルが上がってきて、どこの中学校に行ってもいいという、それが主であれば、全く問題はないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"それは学校に求めるもの、そのときの状態で違うと思うんですけれども、２３％の子どもたちが部活動の状況を見て学校を選んでいる。いろんな質問にも出ていると思うんですけれども、特にこれだけ期待感を持って入った子どもたちが、１年足らずのうちに部活がなくなって、学校に入ってきた目標を失ってしまう。もっとここに人を集めたり、教師を集めればいいと思うけれども、その辺どうですか。","respondent":"青木指導課長","answer":"それから，私たちの教員の人事の中でも、そういうものも配慮して、今までももちろんですけれども、これからも十分にその配慮をしていきたいというふうに考えているところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"今のお答えを伺って、現実的にプラン２１の中で、いろんなことを先生たちが追いまくられるという言い方はおかしいんですけれども、そっちのほうに関心がいってしまって、部活に行っていないんじゃないかという声もすごく多いんです。もっとそれを地域の人たちを取り入れるとか、先生ができないんだったら、地域の人々をどんどん入れるとか、そのような考えはどうなんでしょうか。","respondent":"青木指導課長","answer":"そのシステムを今後これからはさらに充実していかなければいけないと思いますけれども、今、いわゆる教育課程内で行っている教員の指導と、また部活動というのは少し外されてきたところがございまして、そういう意味で指導に非常に難しいところがあるんですけれども。","voiceIndex":34,"id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"ちょっと立ち入るかもしれないんですけれども、ここにありますように、学校へのどういう注意事項を教育委員会から出したのかというのが幾つかありますね。これらは文教委員会には参考資料としていただけないのでしょうか。もう一つは、警察署への各施設からの緊急通報装置の設置を開始したということですけれども、どんなものか。","respondent":"青木指導課長、鷹倉庶務課長","answer":"１点目の資料ですが、非常に細かい点なんですけれども、委員会として必要であるということであれば、ご準備します。全体予算的には都の教育委員会の部分を含めまして、全体的には１５億円という予算が示されておりまして。ですから、これを見ていただければ、基本的にはこういう内容を学校に通知したというふうにお考えいただければと思います。","voiceIndex":41,"id":"exchange-016"},{"speaker":"川西委員","kind":"質問・要望","question":"最初に質問をした部分の件については、資料の見方を知らなかったので、分かりました。２番目の通報システムについては、２９日、金曜日ですね、だから、段取りができていないのと、それから、詳細の説明ができないという段階というのはよく分かるんですが、緊急対策として、そういう予算の措置をしてやろうということになれば、文教委員会にも係るので。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"門扉を一つにする、そのことは、今まで学校公開というのは、だれでも、どこからでも学校に入れるという、我々も勘違いしていたのではないかという認識があるものですから、門を一つにするということは、私は結構だと思うんです。その辺どのように数値的に捉えているのかお聞きしたいと思います。","respondent":"青木指導課長","answer":"ですから、私どもはそれぞれの学校の条件というものがあるかと思いますので、それぞれの条件、実態に応じて対策委員会を通してそのローテーションとか、その具体的な対応とかを考えていただいておるところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"地域の方を踏まえてというのは、私はこれからだと思っているんです。今話されたように、こういうことをやっているので、地域の方も協力してくれませんかという話はこれからだと思うんですけれども、教職員、ＰＴＡとかでやっていると思うので、その数字はどうですかというのは分かっていなくちゃおかしいです。","respondent":"青木指導課長","answer":"既にそれぞれの学校からの学校安全対策委員会の構成メンバーと、実際の活動内容、検討内容ということについては取りまとめてあります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"その資料を見せていただいたんですけれども、６校あるうちの４校がＰＴＡがパトロールをして、２校が教職員がやっているんです。それだったら、何でＰＴＡの方に相談をしないのかと、まず１点あるべきだと思うし、まず教職員が暇がないですね。ＰＴＡはうるさいからと、言ったかどうかわかりませんよ。ＰＴＡに任していたらどうですか。結構気にして聞いているので、その辺の考え方をお聞きしたいと思います。","respondent":"指田教育次長","answer":"当然のことながら、地域の力を借りなければ、学校にそんなに余裕があるわけでありませんから、その中で考え、中には、メールでもって、なぜそんなＰＴＡばかりに任すんだという反対のご意見というのもあります。","voiceIndex":50,"id":"exchange-020"},{"speaker":"桜井委員","kind":"質問","question":"これまでのケースというのは、品川区内でも侵入のケースというのがあったんじゃないかと思うんですけれども、こういう事態に至らないまでも、学校で危険まで至らなくても、侵入のケースというのはなかったんでしょうか。それが一つ。私も調べたんです。その間、昭和５８年から平成１２年までに３１０人減っているんです。それで、まず教育委員会としては、こういう姿勢を示します、人的配置も一緒ですからね。","respondent":"鷹倉庶務課長","answer":"これは確かに非常に大きな事件の関係で、国、都道府県、あるいは我々区市町村も大きな注目を集めて、これから非常に注目して、我々の開かれた学校をどのようにやっていくかという形で見守らなければいけないことではありますけれども。","voiceIndex":52,"id":"exchange-021"},{"speaker":"桜井委員","kind":"質問","question":"今回の事件というのは、今課長が言うように、緊急突発的な事件で見るのか、それとも今の社会の不安な一定の側面が、いろんな形での、学校だけでなくて、児童へのそうした命を奪うみたいな事件というのは結構ここのところ頻繁にあるじゃないですか。品川区はそういう安全性の中にいるというふうには思いにくいんです。そこのところはどうなんですか。","respondent":"指田教育次長","answer":"１点目の侵入の事件があったかないかというところですけれども、どこのところで尺度を持つかというのは非常に難しい。例えば委員が言われたような、どこを指して侵入事件という見方をするのかどうか。","voiceIndex":54,"id":"exchange-022"},{"speaker":"桜井委員","kind":"質問・要望","question":"用務員がトイレの掃除は我慢していて、受付でという、実際にはなかなかそうはいかないですよ。トイレだってきれいに掃除することは、当然子どもたちにとって一緒ですからね。そういう、これまでの方針にしたって見直すべきだと私は思っているんです。大事なことを、今までの方針上はあるけれども、そういうことを横に置いてでも、この期間大事な体制をとるということを強く求めて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然警備の問題が一番重要だという点は分かりますけれども、逆に、児童・生徒の意識がどうなっているか。一番心配なのは、池田小学校でも生徒が後から大変な思いをしている。校長先生に聞いたところ、「動揺はないですよ」という話も伺っているんですけれども、直接中に入って見ていない状況もあるので、本当に大丈夫なのかなというのが一つあると思います。それについてちょっとお聞きしたいと思います。","respondent":"青木指導課長","answer":"今委員のおっしゃるように、学校でいろいろな取り組みをしておりますけれども、子どもたちが動揺しているとか、不安に陥ったとかというような報告は教育委員会のほうにはございません。","voiceIndex":57,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点は、今緊急性のある時期で、皆さんの意識も高まっているけれども、ＰＴＡとの協力関係をどこまで続けてやっていくのか、意識が薄まってきたときに逆に困るんじゃないかなという面と、ある程度薄めなければいけないのかなというところと、そこら辺はどういうふうに判断なさっているか。","respondent":"指田教育次長","answer":"したがって、我々のほうとしては、最低こういうところの安全はあるよというところで、例えば先ほど言ったたすきや何かを付けよう、あるいは防犯ブザー的なものを各教員には配布しよう、あるいは巡回に来てくれるところもあれば。","voiceIndex":59,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今までの話の中で十分分かりますけれども、あくまで児童・生徒の安全性と同時に、精神的な面に影響のないような形に進めていただきたいなと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-026"},{"speaker":"高星委員","kind":"質問・要望","question":"それが今現実的にどういうふうになっているのか。それから、巡回担当者の位置づけがどういうふうになっているのか。その辺のところで施設開放の係の人はどういうふうな位置づけになっているのかということをお聞かせいただきたいと思います。それが学校の安全委員会のことなのかどうなのか。最初の質問は細かいところですが、後の質問は大きなところで、しっかりとした決意をお聞きしたいと思います。","respondent":"指田教育次長","answer":"こういうふうな願いの中でもって一応私どものほうではご説明をしていますけれども、直ちに、今私どもの意図しているところが１００％入っていけばいいでしょうけれども、じわじわきいている部分もあるかと思います。","voiceIndex":62,"id":"exchange-027"},{"speaker":"高星委員","kind":"質問","question":"最初に聞いた細かいところも、後の大きい話も一緒に答えていただきました。今、次長がおっしゃられたことで私はいいと思っているんです。そこのところで、僕も一般質問の中で言わせてもらったんですけれども、あまり過剰反応をしちゃって、子どもたちが完全に萎縮しちゃって、もともと品川区が考えているプラン２１、そういったものに大きなマイナスになってしまうのが怖い。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-028"},{"speaker":"山路委員","kind":"確認","question":"意見が出ると思うんですが、そこを最大のフォローをしていくという、その確認をしたいと思います。例えばお金が要る場合もあるでしょうし、人的な必要がある場合もあるでしょうし、指導的な自分たちの学校は自分たちで守るという、こういう点はすべて協力してフォローしていくというものは当然あると思うんですけれども、それについてのお考えをお聞かせください。","respondent":"指田教育次長","answer":"そういったものを見ながら全体的、総体として、子どもたちの安全確保をどういうふうに図っていかなければいけないかということについて、ケース・バイ・ケースに応じながら対応していきたい、このように考えております。","voiceIndex":65,"id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"今までの答弁で何回も出ましたよね。それは大体分かっているつもりですけれども、現場での学校安全委員会、スピーディに、緊急に判断して対応をしなければいけない場面がどんどんこれから出てきますので、現場での学校安全委員会を最大にフォローしていっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"かつては学校の守り神だった。日常的に学校を見守れる人が絶対必要だというようなことを述べていらっしゃるんですけれども、この点で、果たして本当に、いろいろなところで努力をされていても、人的なもので足りているのかどうかというところで、私は、この２人の方の見解に対して、どういうご意見をお持ちかということを伺ってみたいと思います。","respondent":"指田教育次長","answer":"それでもって、その学校が根本的に変わるのか。やはりそこにあるのは、地域の中の学校だということを再認識してほしい。人を付けて、「じゃお願いします」、「私どもは知らんぷりです」、これじゃ未来永劫、学校というのは一つも発展がない、このように考えています。","voiceIndex":68,"id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"質問","question":"もちろんそうです。地域との親御さんたちも十分学校に関心を持って、一緒にやっていこう、そこは十分高めていく必要があるけれども、それでも果たして足りるのかというところが疑問なんです。基本的なところで。そういった意味で、やっぱり人的なものもタブー視しないで、視野に入れて、総合的に考えていく必要があるのではないかなと思うんですけれども、その点、再度お伺いいたします。","respondent":"指田教育次長","answer":"そのぐらいの気持ちを持って今回の安全管理というものを考えるべきなんです。それでなかったら、自分たちの学校なんて大きなことは言わないでほしいというぐらいです、私のほうは。そのぐらいの気構えを持っています。","voiceIndex":70,"id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは突発的な問題じゃないですよね。これからずっと求めていかなくちゃいけないといった意味では、長期的に安全が確保できる部分が必要だと思うんです。だから、私は、とにかく人為的なものもタブー視しないで、視野に入れて総合的に検討をしていただきたいなということを要望して、終わります。","respondent":"指田教育次長","answer":"でも、私のほうは、自分たちの学校を地域と一体となって守っていきたいというふうなことで、いろんなご意見をいただきましたので、今後国、都から出てくる意見等も参考にしながら、今日の委員会のお話というものを十分承ってまいりたいと、このように思ってあります。","voiceIndex":72,"id":"exchange-033"},{"speaker":"桜井委員","kind":"質問","question":"鈴木ひろ子議員が教科書問題の採択の点で。質問するのは明日ですよね。今日は通告だけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-034"},{"speaker":"高星委員","kind":"質問","question":"今、フォローの申し出があって、明日かかるわけですね。そこのところでフォローされる方は資料も何も要らないという話があったわけです。だから、申し訳ないけれども、もしその部分で、中身はわからないんだけれども、我々が蚊帳の外に置いておかれないような資料はきちっと出してもらわないとというふうに思うんだけれども、いかがなものでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-035"},{"speaker":"川西委員","kind":"質問","question":"先ほどご答弁の中で出たので質問をしたいと思っていたんですが、施設開放で、シルバー人材センターに頼んでおりますけれども、体育館等の一般開放をしまして、その清掃はどこが担当しているのか。","respondent":"南生涯学習課長","answer":"校庭、体育館等の使用後の清掃ですが、基本的には使った方たちがマナーの範囲で片づけていただくということになっております。","voiceIndex":89,"id":"exchange-036"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、昼間児童・生徒が使った部分が学校の用務員、夜使った部分は自主的。それを点検するのは、学校のどなたか聞きたい。教頭なのか、校長なのか。施設管理という教員がいらっしゃるのかどうか。","respondent":"南生涯学習課長","answer":"ですから、あまり汚れるということではなくて、器具の片づけ等ということになろうかと思いますが、よほど何かがちらかれば、それはきちんと片づけていただくですが、それは、明けて出てきた学校の教頭が、マナーの悪い団体等があれば、私どものほうに連絡をいただき。","voiceIndex":91,"id":"exchange-037"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ要望いたします。文教委員会の中で解決が図れれば、予算・決算特別委員会で申し上げることになるかと思いますけれども、私は、管理状態、来れば、運動ですから、ほこりが脇のほうへ踊る。それから、学校側の用務員にとっては、夜使った人たちのマナーが悪過ぎるからというので、反発意識があるというようなこともあり得るので、今後少し検討を、大事なことだと思うんです。","respondent":"南生涯学習課長","answer":"現在、学校の開放はスポーツ、レクリエーション推進委員会ということで、地域の体育指導員の方等を中心にした利用調整会議を設けておりますので、その利用調整会議の場でマナーの徹底ということを図ってまいりたいと思います。","voiceIndex":93,"id":"exchange-038"}]},{"id":"topic-02","title":"３番目の行政視察につきまして、これから皆さんで協議をしていきたいと思いますので、関係者の方、次長は協力いただいて","agenda":"３番目の行政視察につきまして、これから皆さんで協議をしていきたいと思いますので、関係者の方、次長は協力いただいて","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"２点提案したいと思います。一つは、この間委員会の中でも議論になっている、少人数学級の具体的なそれを実践して、効果を出しているところを知りたい。もう一つ、学校設備、施設改善というよりも、未来ある２１世紀、そういう設備のところで、従来の学校というよりも、もう少し夢があるというか、そういうものを、内容面と、ハード面。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-039"},{"speaker":"川西委員","kind":"意見","question":"少人数学級は賛成します。もう一つ、総合青少年、そこで個人なりグループなりで文化活動のできるような、課外活動ですね、できるような、そういう施設を、将来、第二日野小学校がつぶれたら、たとえばですよ。だって、交通アクセスがとてもよいから。あのぐらいの大きさのところ。文化活動ができるような施設をと思っているので、行きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"私も文教委員会に所属させていただいたときに、箱ものをちょっと見せていただいたような感じのするのもあったので、生涯学習部分で考えたときに、ものを見るというよりも、具体的に、ではどういう実体があるのかと、そっちの実態的なもの、そういう先進的な事例があれば、生涯学習という点でも、何か勉強してみたいという、３点を自分は考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-041"},{"speaker":"松澤委員","kind":"意見","question":"鈴木委員も川西委員のも賛成です。ただ、少人数学級に行こうというのは、私はそれについて賛成論ではありませんので、それについてコメントを出していただいて、もしそうでしたら、もっと多人数学級と両方見ないといけないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-042"},{"speaker":"山路委員","kind":"意見","question":"私のほうは、前にも行ったかもわかりませんけれども、小・中一環教育をやっているところがありますが、内容が充実している、特色の面でも、いいところがあったら、そこを。もう一つは、ＩＴ関連の学校の先進自治体を見てみたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-043"},{"speaker":"高星委員","kind":"意見","question":"それぞれ各委員の言われたのはみんなごもっともだなと思います。ただ、桜井委員に歯向かうわけではないですけれども、少人数学級の関係について、プラン２１品川も先駆的にやっているところは尊重すべきだと思う。地域との差が随分違って出てくるんじゃないかなと思うんだけれども、地域ぐるみの教育をどういうふうにやっているのか見ていきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-044"},{"speaker":"山路委員","kind":"意見","question":"もう一つ。自然体験学習というのが今各地域ではやっていますね。バリアフリーの施設がありますね。子どもも、大人も、障害者も、健康人も、みんなが動物とともにふれあうセンターがありますし、自然を生かした教育もあります。今出ませんでしたので、それを一つつけ加えておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-045"},{"speaker":"川西委員","kind":"意見","question":"つけ加えると、高星委員のおっしゃった、地区委員との係わり、これは大変いいと思うんですが、主任児童委員というのがいるんですよね。いろんな問題を、その人たちが地域でどう学校と係わっているのか。調査項目にお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":38242,"voices":105}},{"id":"h13-20010702-5","meetingId":"h13-cm07","date":"2001年7月2日","dateIso":"2001-07-02","committee":"総務委員会","time":"午前１０時０４分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第６５号議案、総合庁舎受変電設備改修工事請負契約","agenda":"の第６５号議案、総合庁舎受変電設備改修工事請負契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"設備を更新することによるメリットというのを何点か教えてほしいんですが、一つは、大分古いものですから、メンテナンスも確かに圧迫されたと思うんですけれども、それが相当額減るのかということ。それから、中でも管理の人の部分で減る部分があるのか。２点をお願いいたします。","respondent":"西島経理課長","answer":"それ以外にいろいろなものが出てくるかと思いますが、それは今後の中でまた考えていきたいというふうに思ってあります。","voiceIndex":9,"id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういうものですから、機械の耐用年数、あるいは信頼性に限度がきたら変えるということでしょうけれども、機械というのは、ある一定以上古くなると、非常にメンテナンスにお金がかかり始めるわけです。それはいいんですけれども、人の部分はもう少し考えたほうがいいんじゃないですか。人の部分だけもう一回聞かせてください。","respondent":"西島経理課長","answer":"ただ、新しい機器になりますので、その辺のなれの部分というんですか、その辺も若干考慮しないといけないと思いますけれども、委員ご指摘のとおり、人手がかからなくなってくるということは確かだと思いますので。","voiceIndex":11,"id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"行政評価システムを取り入れているわけですから、今この保守管理にどれだけの人手がかかっているかという面からも、ちゃんと気をつけていかないと、２億9,０００万円のお金をかけるわけですから、この部分は確かに行政コストの削減につながるよという話を、今の答弁以上にいただきたかったなということを指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"私も内容のところはよくわからないので、外側のところで伺いたいんですけれども、一般的に、これの耐用年数が２５年から３０年と言われているんですけれども、一般のものは例えば耐用年数になる前にでも傷んでくれば変えなければいけないということになるんだろうと思うんですけれども、逆に、もっと使えそうだということになれば、耐用年数が過ぎていても使うなどという場合もあろうかと思うんです。","respondent":"岡田施設課長","answer":"これがが昼間の執務時間中にバタンときたときに、恐らく１日ぐらいではとても回復できないという状態が起きる可能性があります。そういう意味では、３３年経っておりますので、一気に取り替えるためには適切な時期じゃないかと。","voiceIndex":14,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"ちなみに、今度新しく入れる機械は耐用年数はどのぐらいなんでしょうか。","respondent":"岡田施設課長","answer":"やはり２５年から３０年というのが一つの目安かなと思います。ただし、新しい機械はコンピュータを使っておりまして、これについては、はっきり言いまして、そう長い使用には耐えられない部分がある。ですから、部分的の更新は必要かと思います。","voiceIndex":16,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"今回は受変電設備ですけれども、全体の総合庁舎の躯体だとか、今回は電気設備のほうですけれども、躯体、あるいは電気、水道、ガス、いろいろあろうかと思うんですが、長期的にいつ、どういうものをやるか、修理する必要があるのかとか、そういう総合計画といいますか、そういうものというのは何かあるんでしょうか。あったら、教えていただければなと思うんです。","respondent":"西島経理課長","answer":"庁舎の躯体そのものは３３年過ぎているわけですが、減価償却のリスクにすると６０年、あるいは鉄筋は５０年というふうに言われておりますけれども、今のところ本庁舎の躯体そのものは大分痛んできておりますけれども、うまく使っていけばまだ大丈夫だろうということで。","voiceIndex":18,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"あれと同じ機種なんてないんだし、新しものができているんだから新しいものになるのは当然だけれども、それを入れることによって、これだけのメリット、それから，社会的に理由がつく，そういうことを考えていくべきだと思うんだけど、今の説明は非常に旧態依然とした品川区の改修工事であるというふうに位置づけざるを得ないんだけど、なぜそんなことを執行部が許すのか。","respondent":"本間総務部長、岡田施設課長","answer":"そういう点につきましては、今ご指摘を受けました点を十分配慮しながら、今後もきちんとした対応をさせていただきたいと考えておりますので、ご了承のほどお願いいたします。防災センターとの比較ですが、申し訳ありませんが、防災センターとはしなかったんですが、直近の南大井の複合施設とは比較しておりまして、ここが５億5,０００万円ぐらいが電気工事の契約金額ですが、このうちの大体１８％。","voiceIndex":20,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"部長が答えられた、何か皮肉のようだけれども、総務部だけ事業部という名称を付けなかった。それは、よそとの競争というよりも、内部的なもの。一つだけ確認をしておきますけれども、各家庭でもそうなんだけれども、これがそういうものに当たるのかどうかわからないけれども、今電気を使うものがたくさん増えてきた、例えばガスを使うのでも電気が必要だとか、電話をかけるのも電気が必要だ。","respondent":"岡田施設課長","answer":"向こう３０年ですけれども、恐らくこの古いのも、３０年経った今でもまあまあ持ちこたえているわけです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の工事と関連して、直接関係ないことかもしれないんですが、先ほどのお話の中にも、今後のＯＡ化対応ということで、キャパシテイとか、容量的な部分は対応を考えていらっしゃるということを伺ったんですが、例えば日常的に磁気データ、物すごく貴重なデータを今後ますますたくさん扱うようになってくると、瞬間的な停電が起きてもデータが消えてしまうようなことがあるわけですが。","respondent":"岡田施設課長","answer":"したがいまして，監視のところは３分の２ぐらいの大きさになろうかと思います。それから、ＯＡ化の容量関係ですけれども、確かに容量的には非常に余裕があるものになります。","voiceIndex":25,"id":"exchange-009"},{"speaker":"北野委員","kind":"質問","question":"発電機室がディーゼル式交流というのが、制御盤、非常用としてなると思うんですけれども、全然わからないんですけれども、今は重油じゃないという動きがあるんでしょうか。それから、４０００ｌというのは、既に溝があるところに新たにつくるんですか。","respondent":"岡田施設課長","answer":"この４０００ｌを使って２５時間ぐらい、丸１日ぐらいは動く。防災センターのほうは３日間動くというものを用いてありますけれども、ここについては、当時は、４０００ｌで、丸１日間ぐらい動くと、このようになっております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"土井副委員長","kind":"意見","question":"そういうシステムになっているのかどうか。さらに、もう一つ言えば、なぜ３カ所なのと。これでいくと、またどこかにつくると、また４カ所目ができて、またこっちをつくるとまたできてというスタイルになっていって、どこかのホテルの何とかみたいになっちゃって、渡り廊下ばかりがつながっているということになりかねないんですけれども、その辺のところはどう検討をされてきたのか。","respondent":"岡田施設課長","answer":"これをやった最初の時点でもいろいろ検討して、１カ所で送るよりも、そのほうがメリットがあると。現在も検討をしましたけれども、やはりそのほうがメリットがあると。こういう形で計画をしております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"土井副委員長","kind":"質問","question":"だから、後から設備をしたり、新たにするときに、統合的にうまく考えていっていただかないと危ない部分があるなと思ったものですから、ちょっと聞いてみたので、そこら辺大丈夫だとは思いますけれども、この設備に限らず、これからのさまざまな設備等でも新しいものを横につくると、そこにまた同じようなものができてしまうというふうに、何カ所にも分かれるという場合が、メンテナンスも含めて起こるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"}]},{"id":"topic-02","title":"の第６６号議案、臨海副都心線天王洲アイル駅自転車駐車場設置工事委託契約","agenda":"の第６６号議案、臨海副都心線天王洲アイル駅自転車駐車場設置工事委託契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"詳細のことがほとんどない。どの部分にどれだけのお金がかかるということが、もう決まっているのかどうか、そこをまず教えてほしいということ。協定が８月で、この部分はどれだけぐらいのお金がかかるけれども、品川区の負担ですよというふうに最初からなっているということで理解していいわけですか。その二つ。","respondent":"岩田管理工事課長","answer":"区の費用ですけれども、これは都市計画の駐輪場として今回建設をいたしますので、工事費の２分の１が国からの国庫補助金でございまして、残りの２分の１のうち、約４分の１程度が都市計画交付金として都からくる予定になっております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"今のお話で、７億5,０７５万円が躯体工事だということになりますけれども、この部分は品川区の負担ですから、後ほど自転車駐車場として設備の部分は後ほどまたお金がかかってくるのかということを聞かせてください。","respondent":"岩田管理工事課長","answer":"７億5,０００万円の中には、駐輪場の管理施設等の電気設備、これはごくわずかですけれども、それと、駐輪施設用のラック等の機械設備もこの中に入っておるわけです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"それで、契約の仕方ですけれども、日本鉄道建設公団がこの部分について積算をして、見積もりを幾つとっているかわかりませんけれども、割高の工事になるかわかりませんけれども、それについてしっかりと品川区は、結局お金を払うわけですから、これ以上高いこの見積もりはいかがなものかというやりとりは実質しているのかどうかということをお聞きします。","respondent":"岩田管理工事課長","answer":"先ほどもちょっと申し上げましたけれども、これは国庫補助金を導入する事業ですので、私どもが将来、会計検査院の検査を受けるという立場になりますので、その他の事業がいい加減ということはございませんけれども、当然のことながら。","voiceIndex":41,"id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"３００台というのは、大体全部収容可能なのかどうかなのかという、そこら辺の見通しはどうかなと思うんです。そこら辺のところ、つくっても、利用できない方も相当、西大井の場合などでもいるんですけれども、いい駐輪場をつくっても、全部使えるかどうかとなると、そこら辺の見通しというのはどんな感じでしょうか。","respondent":"岩田管理工事課長","answer":"私どもの現在の測定では、目に入る範囲内で２００台から２５０台の放置ではないんですが、自転車があのあたりに存在している。通常、こういった場所で有料駐輪場を設置いたしますと、約７割から８掛けになります。","voiceIndex":43,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"今も説明の中に出てきた、りんかい線の天王洲アイル駅というのか、りんかい線の駅と、モノレールの駅の関連事業だろうと思うんだけど、モノレール線というのか、どういうあれだかわからないんですけれども、モノレール駅と、総合的に、三者でというのはなかったですか。","respondent":"岩田管理工事課長","answer":"駐輪場に関しましては法律はありますが、この法律の中で鉄道事業者につきましては、駐輪場建設に対する努力義務しか明示されてございませんで、これが全国の自治体と旧運輸省と旧建設省とのいろいろ摩擦を生んでいる要因でございまして、実際のところ。","voiceIndex":45,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"りんかい線もいろいろな困難があって、トンネルを掘っていったら、ちょっと待て、お金を出してほしい、また、ここを直すからと言われて、はい、そうしますと、３００億円からの金を出した経緯がありますよね。ちなみに、３００台の自転車駐輪場をつくるとしているが、今品川区で有料駐輪場で一番台数の多いところの費用は幾らぐらいかかっているんですか。","respondent":"岩田管理工事課長","answer":"品川区営の駐輪場で有料駐輪場はまだございませんで、大井町駅前、阪急側出口のところの通称、猫公園といわれるところの前のところが、あれは土地は品川区ですが、建物そのものが駐車場整備センターというところがつくって。","voiceIndex":47,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区で比べられなければ、民間と比べるという、今はそういう時代なんですよ。大井町の駅前で、民間では、どれぐらいの建物数で、何台入っているんですか。","respondent":"岩田管理工事課長","answer":"今手元に資料がございませんので、調べまして、後ほどお答え申し上げます。","voiceIndex":49,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"３００台で７億円というと、１台幾らになるんですか。計算もしたくないような数字だし、もちろん駐輪しやすい利用料はそういう値段を設定していくんでしょうから、７億円というのは、おそらく永久にペイはできないというふうに考える金額ですよね。これだけのお金を品川区だけが注ぎ込んで、必要性ということで注ぎ込むわけだけど、その前にやっておくべきだったのかな。","respondent":"岩田管理工事課長","answer":"それとまた、臨海高速につきましては、本来であれば、自分のところの工事はもう埋め戻して、あと復旧をして終わるわけですけれども、品川区の要望に協力をして、復旧を約１年以上待って、その間に品川区は乗り込んで工事ができるような状態で。","voiceIndex":51,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"確認","question":"さっきの建設費というか、それと合わせて、ちなみにどのぐらいの収入が上がるのか、見込みだけでも結構ですから、それを。もう一つ、今聞きながら、思いついたんですが、東急の大井町線の新駅ができますよね。ちなみに、そこは駐輪場はどういうふうになっていますか。新しい駅はできないと思ったけど、灯台もと暗しで、一番近いところに新しい駅ができるので、確認しておきます。","respondent":"岩田管理工事課長","answer":"先ほどの数値がまだ出ておりませんで、１０月１日から区が有料化をしていこうという大井町と大崎につきましては、現在施行規則の改定作業を進めておりまして、現在検討中です。","voiceIndex":53,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"さっきいろんな形で協力はもらっているんだというところですけれども、こっちから、品川区としてつくるんじゃないけど、ここにつくったらどうですかという要望もしていくぐらい、鉄道会社は、こういうふうに言うといけないかもわからないけれども、ぜひつくりたくないという姿勢なんだから、ぜひつくってくださいよという姿勢で、これからも言っていくべきだと思いますので、相手のあることで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"土井副委員長","kind":"質問","question":"ちょっとお伺いしたいんですけれども、自転車を置くときは平場に置くのが一番簡単で、上でも下でも、動くと置きにくいんですよね。上に行くのに斜めのところを上がって下りる。ここは何でこんなに深いんですか。7.２ｍも下に下りていかなければ、１1.５ｍ下りていかなければいけない。","respondent":"岩田管理工事課長","answer":"したがいまして、道路下空間をある一定区間構造物の設置はできませんので、それで下がっております。駐輪場の一番下までが８ｍちょっとのところが駐輪場の床になります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"土井副委員長","kind":"質問","question":"確かに埋設物はあるんだけれども、埋設物をそのままにするという発想は、これからのいろんなときにみんなそういうふうになるのかな。右も左も動かないよということですが、もし技術的な問題なら、さることながら、行政的な制約で、ここは何とかの管理だから、動くのはいやだよというようなことであるならば、また改めなければいけない部分もあるのかなと思いますので、そんな問題ではないんですか。","respondent":"岩田管理工事課長","answer":"これは、この道路はほとんど車道部分全面を使いまして、長さが４５ｍにわたって構造物ができるわけですので、一応道路管理者としましては、それなりの構造物、これは道路施設といえども、将来いろんな道路下には埋設物、これはライフラインですので。","voiceIndex":58,"id":"exchange-024"},{"speaker":"土井副委員長","kind":"質問","question":"今のお話も含めまして、ここは自転車置き場をつくったわけです。でも、上のところに構造物がいっぱい今ぶら下がっているわけですね。空洞になっているところ。共同溝的な発想というのは、そういうときには起こらないものなんですか。話はちょっと違いますけど。","respondent":"岩田管理工事課長","answer":"といいますのは、この横の海岸通りのほうが国道が設置します共同溝の計画、八潮に抜ける線ですけれども、こういった計画で今工事が始まっておりますので、巨大幹線部分についてはすべてそちらの共同溝に将来動くような計画になっておりますので、旧海岸通りにつきましては。","voiceIndex":60,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"昨年の建設委員会で尼崎市に視察に行ったときに、市営の駐輪場、これよりもっと大規模の駐輪場を見てきたわけですけれども、それと併せて、建設委員会でも、この件について説明を受けたことがあったんですが、そのときも話題になったのは、階段の部分、Ａ階段、Ｂ階段とあるんですけれども、自転車の昇降するときのベルトコンベア、要するに、自転車を乗せて。","respondent":"岩田管理工事課長","answer":"地図が小さくて申し訳ないんですが、基本的にはメインの出入り口はＡ階段のほうをご利用いただく予定です。","voiceIndex":62,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"確かにそういうお話があったなということが、今お話を伺っていて、そういうようになったということで安心しました。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"}]},{"id":"topic-03","title":"の第６７号議案、中継作業用コンテナの買入れ","agenda":"の第６７号議案、中継作業用コンテナの買入れ","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"この書き方だけ聞きたいんだけど、本会議場で説明された、縦書きの第６７号議案、中継作業用コンテナの買入れについて、今経理課長が説明されたようなことがずっと書いてあって、２に、種類および数量とあって、新明和工業株式会社製コンテナ５０台、金額は２億9,１９０万円と書いてあるんだけど、こっちの９ページのほうの表の中の見積もり価格は２２億7,８００万円と書いてあるが。","respondent":"西島経理課長","answer":"１０ページに購入価格とございまして、５５６万円掛ける５０台掛けるというふうに記載しています。","voiceIndex":71,"id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"単価はここに書いてある。１台５５６万円もするんですか。言葉がないんだけど、こんなに高いものなんですか。","respondent":"西島経理課長","answer":"私も聞いてびっくりしたんですけれども、定価が６９０万円。平成６年度、平成７年度に買入れをしたときに、消費税は別ですけれども、東京都は５７０万円ぐらいの金額で購入をしたということがあります。","voiceIndex":73,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうことなんだろうけど、何でこんなに高いのかという、独占企業なんですか、それとも特殊なものというか、特殊性の高い品物で、じゃ、特殊性の高いという部分を強調するだけで、ただパッキンが入っていて、密封されて臭いが出ないというだけだったら、そんなに特殊性があるとは思えませんけれども、その辺をちょっと説明していただけますか。","respondent":"中山清掃リサイクル課長","answer":"こういった意味で附属のパッキングであるとか、ゲートの部分の金具についても、相当の強度を求められる。こういったものが価格に反映されているのではないかというふうに認識しています。","voiceIndex":75,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"意見","question":"分かりました。特殊な部分なので、どう判断すればいいかわからないけれども、高いなという印象だけは伝えておきます。そうすれば、フェリーみたいな、車が船に乗れるような埠頭というか、桟橋をつけておけば足りることで、品川区にある施設の存在からすれば、完全に違うんだろうけれども、平成１８年にはこういうものは廃止して、車で運送をするんだという考え方ができるかどうかだけ聞かせてほしい。","respondent":"中山清掃リサイクル課長","answer":"それと、委員が今おっしゃられた、ああいう大型なクレーン等じゃなくて、直接車を乗せて運ぶ方法もですけれども、まず、清掃車両自体がほぼ６００万円から７００万円ぐらいで、ＬＰＤ車単価ですけれども、コンテナよりも現状ではさらに高いような値段になっているですし。","voiceIndex":77,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"意見","question":"ベストと判断できるかどうかは疑問なんで、僕らも検討していきます。あの船は１日２回、多くて３回しか往復していない。１０回はできるんだから、１０倍は車で行ったり来たりできるという計算だから、これらの計算で単純にいくと、１２７台分だけ収集パッカー車が多くいるということになるわけだから、それが要らなくなる。船は１０往復増やせばいいというふうになれば、果たして効率はどうかな。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-032"},{"speaker":"三上委員","kind":"質問","question":"ちょっと教えてもらいたいんですが、先ほどのコンテナの特許という部分で、コンパクターで圧縮する設備そのものも特許の部分が入っているんですか。要するに、コンテナをガッチリと密着させなければいかんですよね。ほかのメーカーがこれに似たような形のコンテナをつくったとしても、それは取り付けられないという現状であるのかどうか。そこのところを教えてくれますか。","respondent":"中山清掃リサイクル課長","answer":"そういったいろいろ技術的な難しい部分、まだ緒についた部分もありますけれども、そういったものを十分見極めながら、区としてはより合理的な維持管理の方法というのを探っていきたいというふうに認識しております。","voiceIndex":80,"id":"exchange-033"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう点での今後の課題というのはあると思いますので、そこのところについてはしっかり考えていっていただきたいなと思います。もう一つは、入れ替えに当たって、古くなったコンテナそのものは引き取ってくれるんですか。逆にこちら側がまたこれを処分しなければならないということになるのか、そこらあたりはどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"老朽化したコンテナの処分ですけれども、予算編成時に、１台当たり約３万円の処分料がかかるという見積もりがございましたので、そのように予算計上したものですけれども、本年度になって幾つか処分業者を当たる中で、基本的には処理経費がかからない形で、逆に若干ですけれども。","voiceIndex":82,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"２点お伺いしますけれども、東品川作業所のところは、品川区だけでなくて、幾つかくるわけですよね。こういう費用というのは、そもそもどういうふうに負担し合うのかというのがよくわからないので、そこのところを。品川区で大分負担して、利用するところはどういうふうな負担になっているのか。そこのところをまずお願いしたいと思います。","respondent":"市岡企画財政課長","answer":"最初は、利用する他区が品川区に使用料を払うという方法も考えられて、検討をしてみたんですが、実は使用料でいただくと、ごみ量の変化に対して非常に精密な調整作業が必要である。","voiceIndex":84,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"１２９台のうち１００台ということで、私も値段を見たときに、高いなというのが第一印象なんです。高い買い物をするんだということですけれども、１２９台のうち、説明では、老朽化し、腐食している。そこら辺のところはどうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"現在１２９台のコンテナですけれども、先ほど経理課長からの説明もありましたように、平成６年度および平成７年度に東京都清掃局において購入したコンテナです。その後の不燃ごみの量が約２割強減ってあります。","voiceIndex":86,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"例えば今回は５０台、来年度が５０台という考え方ですけれども、そうすると、修理が可能かどうかとか、そういうところで精査していくと、今年度は買うにしても、来年度はまた変化する可能性はあるということですか。","respondent":"市岡企画財政課長","answer":"まだ形状のいいものについては、予備とか、ごみ量の変化に対応する分としてとっておく。このパターンが実は一番安く上がるという計算をいたしまして、それで当面こういう２年間という案をしたわけです。","voiceIndex":88,"id":"exchange-037"},{"speaker":"土井副委員長","kind":"質問","question":"その中には、２つ問題点として、腐食等が起こっている。船で、海の塩気のところを渡るから腐っちゃったという部分が大部分なのかどうかわかりませんけれども、ほかに装置的な意味でのガタがきちゃったよという部分があるのかどうかそれはわかりませんが、いわゆる腐食の面のことを考えると、例えばあの箱を何年ごとに塗り替えているんですかという問題が起こるわけですね。船は毎年のように塗っているんです。","respondent":"中山清掃リサイクル課長","answer":"やはりこの辺が不燃ごみを積み替えていくコンテナの強度というのがどこまであるのかというのが、必ずしも通常のごみ以外のものを運ぶ物と一律に考えられない部分もありますので、今のご提案というのは、今後の認識していく中で、より長持ちさせる工夫がどうあるべきかというのは。","voiceIndex":90,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"車の走行時間なり、可能性もありますし、それが人件費にはね返ってくるし、あれは迷惑対策だけでつくったのか、あるいは別な合理性があったのかどうか。その合理性については検証されているのかどうかということを教えてほしいと思います。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません、明確なコスト比較の資料をつくり上げたということはございませんが、いずれにしても、約三百数十台の車が船に上がるということで、この船舶中継所自体は、運ぶ不燃ごみの量によって単価契約になってございまして、この単価と。","voiceIndex":92,"id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"先ほど同趣旨で聞きましたけれども、やはりそういうことが根底にある程度計算されていないと、契約の交渉を結ぶときの力にならないという時代にきていると思います。物を買うばかりでなくて、新明和工業のほとんど独占状態だと思いますけれども、いずれにしろ、そういうもとのある種の計算が必要だということを指摘したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"関連してですが、大分飛躍してしまう質問かもしれないんですが、東品川清掃作業所としての将来的な位置づけというか、必要性というところについてですが、逆に言うと、あれだけの一等地を、都から移管されて何年間かはそのままの設備にしなければいけないという制約もあろうかと思うんですけれども、それ以降の話として。","respondent":"中山清掃リサイクル課長","answer":"したがって、その移管のときの都区の約束ごとが基本にはなるわけですけれども、今後のごみの量、あるいは技術的な面、あるいはごみのつながりを、こういったものを幅広く考えながら。","voiceIndex":95,"id":"exchange-041"},{"speaker":"田中委員","kind":"意見","question":"作業効率の面も追求していかなければいけないと思います。２０年間という制約もありつつも、複合施設であれば可能なのかどうかも含めまして、ぜひご検討といいますか、より効果的な利用がされるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問","question":"会計処理上というか、内容的には前に説明されているんですけれども、この表の、今言われた、未収入特定財源で都の支出金が入ってくれば、都の支出金として受け入れると。一般財源のほうなんですけれども、繰り越しをされたときは、実際にはお金は出ていない。そうすると、この呼び方ですると、未支出一般財源という呼び方をしなければおかしくないですか。","respondent":"市岡企画財政課長","answer":"趣旨は、今委員のおっしゃられるとおりでして、ここも言い訳をするわけではありませんが、施行令では総務省令の定める様式で報告をしなさいというふうに、この様式が決まっております。","voiceIndex":103,"id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問","question":"もうちょっと話を広げてしまって申し訳ないんだけれども、そうすると、今言われている単年度会計というのから脱却する方法というのはなきにしもあらずというふうに考えていいですか。","respondent":"市岡企画財政課長","answer":"こういうのは本来単年度主義というものを、それはそれで重要な意義があるんですが、つまり当該年度の入ってきた歳入で当該年度の支出をして、歳入と歳出の関係をきちんと対応するようにすることが財政の主義だと、こういう意義がありますので、それは重要なことなんですが。","voiceIndex":105,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問","question":"私も法律的なことで、会計検査のことでお伺いしたいんですが、区側としてはケーブルテレビの敷設のものとして平成１２年度に出して、それが平成１３年度分がまだ実行なされていないので、今回のような措置なんですが、区としては未収入特定財源なんですけれども、都としては未支出の財源といいますか、そのような扱いになろうかと思うんですが、平成１３年度はやや都財政が持ち直ししたとは言え。","respondent":"市岡企画財政課長","answer":"今の委員のお話を、都と区に置き替えてご説明しますと、国のほうは平成１２年度にぜひこの補助事業をやりたいということで、補正予算という形で予算化をしたものです。","voiceIndex":107,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"意見","question":"９月６日に議長の会議が持たれる予定なので、できれば９月６日は避けていただければありがたいなと思います。皆さんの議論は議論として進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-046"},{"speaker":"三上委員","kind":"質問","question":"議長の言われたことを考えてみますと、９月１０日が質問通告日ということになるので、直前だったら難しいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-047"},{"speaker":"土井副委員長","kind":"質問","question":"ちょっとざっくばらんな話になるかもしれませんけれども、前年はたまたま行政評価ということで、できるだけ早くやろうという意思が働いてやったということだと思うんです。同じ時期に各委員会がごそっとみんな行ってしまうわけですから。それから、私自身は、せっかく課題が絞られてきているわけですから、わざわざゆっくり後のほうまでとっておく必要もないんじゃないか。１０日の週ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-048"},{"speaker":"土井副委員長","kind":"質問","question":"３日に議運が入っているようですから、そこを避けなければいけないですね。","respondent":"本多委員長","answer":"やはり通告期限の前としますと、７日には議案説明会が入っておりますので、４日、５日、６日というのが一つの案です。議長からも先ほどお話ししていただきましたが、９月でしたらば、このあたりしか。","voiceIndex":123,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私も、通告の前後というのは、うちのほうも議員団として質問をみんなで検討したりするので、ちょっとそこのところを避けていただきたいというのが一つ。そうすると、やっぱり１０月の第３回定例会が終わったあたりになるかななどというふうに、私個人としてはそんなところで予定を立てていたんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問","question":"去年は８月２２日、２３日、２４日あたりだったんじゃないですか。月曜日が２８日で、その前の週の水、木、金に行けたんです。今年は前の週はまだお盆にかかるでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"今のところ、１０月２２日の週ということでいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":36921,"voices":136}},{"id":"h13-20010703-6","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"区民委員会","time":"午前１０時０５分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田副委員長","kind":"質問・要望","question":"すみません。啓発をするというんであれば、よく考えれば、人が多いほうが啓発活動にはつながると思うんだけれども、何でこれをわざわざ月曜日まで延ばす必要があるのか教えてほしい。","respondent":"長田地域活動課長","answer":"ただ、道路使用の関係ですとか、パルムの入口という条件を考えてみますと、ある程度の人が集まるというようなこともございまして、地域の中の希望もございまして、そのようにさせていただいたということと、それからあと、実施をする側の対応といいますか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田副委員長","kind":"質問・要望","question":"この前も、安全条例でちょっと話題にも出た話なんですが、条例はつくったけれども、啓発活動がどれだけ効果があるかという、今度、行政評価も始まるわけですから、その中の啓発活動において、どれだけこのポイ捨て禁止条例というものを皆さんが理解をされて、区民の方が協力をしてくれるかというところまで踏み込んでいかないと、精神条例だけで何も、それで終わってしまうということのないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"今、ちょっと石田委員からもお話があったんですが、まず、協力のあれで、何で荏原警察署が入っているのか、これは交通安全の面で入っているんでしょうか。","respondent":"長田地域活動課長","answer":"これは一つは、セレモニー等を行いますので、道路使用の関係があるというようなことと、当日の交通の安全、それと、できるだけ広範な人々にこの趣旨をご理解いただくというようなことから、荏原警察署にも協力を要請したところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"この禁止条例の中に、罰則規定というのがありますよね。〔「ない」と呼ぶ者あり〕ないですか。ないんだったら、警察が来てつかまっちゃうよという意味ではないわけですね。わかりました、すみません。そうすると、次の質問につながらないんで、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"啓発活動５回ということで、どのぐらい効果が上がっているのかなというふうに推察するんですけれども。あれがポイ捨て禁止で、いたるところに張ってある、飾ってあるというか、つけてあるというか、なんですけれども、あまり美観的にもいい感じではないんで、効果的に配るような指導とか、つけるような指導とか、そういう条件をつけて各町会に配られたんでしょうかね、どうなんでしょうね。","respondent":"長田地域活動課長","answer":"町会関係の日常の対応ですけれども、これにつきましては、１３地区、先ほど申し上げましたとおり、さまざまな地域の実情に合った事業を展開しています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"原委員","kind":"質問・要望","question":"徐々にでしょうけど、効果が出てきているのかなと私も思っています。それから、表示板もどこへでもつければいいというものでもないので、その辺もやっぱりちょっと考えて、美化になるような形でつけていっていただきたいなと、のぼりなんか汚くなってしまうと、美化どころではなくなるということもありますので、その辺だけ、ちょっと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"ポイ捨て条例をつくっておきながら、何だと。そういう点で、課題というか、もっと解決しなければならない問題点があろうかと思うんですけれども、その辺をどのようにここに記されているのか、今回、施行の記念行事ですから、一定の評価をしながらさらにこれを普及していこうという決意だと思うんですけれども、問題として、解決しなければならない問題というのは、どういうふうに認識されているんですか。","respondent":"長田地域活動課長","answer":"それからあと、問題はというようなことですけれども、先ほども罰則があれば、もっと効果がというようなお話もあったように思いますけれども、ポイ捨てに関するものというのは、罰則をつくるかつくらないかの議論の中で説明をさせていただいたと思いますけれども。","voiceIndex":15,"id":"exchange-007"},{"speaker":"本田委員","kind":"確認","question":"ＪＲは人手がないから、そこまでできないんだと言っているんですけれども、それなら地域の方にも協力をいただいて、安全確認ぐらいはＪＲで出して、一緒になってやればいいものを、やらないというようなことで依然として放置されているというようなこともあるんですけれども、そういうことは課長自身が来て、あるいは見て、おわかりなんだけれども、こういうのはどうやって解決するんですか。","respondent":"長田地域活動課長","answer":"それで、私どもが進んで対応はしますけれども、やはり、今までみたいな形で、月に１回とか２回とか、そういうような頻度ではとても対応できない、その辺はご理解をいただきたいというようなことでした。","voiceIndex":17,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"この条例が施行されて、いろんな問題も起こっているように私は思っているんですけれども、なお一層、そういう問題を切に解決するように、関係団体、地域の皆さんにお願いするだけではなくて、一生懸命やっているわけですから、そういうことを協力し合って、この条例が生かされていきますように要望しておきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認を含めて教えていただきたいんですが、今課長からお話しございましたように、先般の委員会でも指摘したような職員の人ですね。それから、日本たばこ産業株式会社大田営業所と、たばこのことは、僕ちょっとよくわからないんですが、品川にはこういう組織はないんですか。時間の制約の中で、こういうふうに絞られてきたのかどうかわかりませんけれども、その辺の考え方はどうなんでしょうか。","respondent":"長田地域活動課長、松崎税務課長","answer":"そういった意味で、たばこを多く区内で買っていただきまして、あとはたばこを吸うマナーの向上をというようなことで、今回たばこ組合のほうからもご協力をいただきまして、先ほどちょっと話題に出ていました携帯用の灰皿。品川という名称はないんですが、全エリアを協同組合がカバーしているという、ただ名称が東京中央たばこと大田というふうに分かれておりますが、エリア的には、すべての品川区をカバーしているというふうに。","voiceIndex":20,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問","question":"そのときには、そういうところからの協力、大井町でやるときは、東京中央のほうがエリアになるのか、エリアがどこなのかわからないんだけど、あるいはさっき第２回目の大崎と五反田をおやりになっているんですけれども、そういうところでどこか、東京中央ですか、品川地区のエリアというんですか、そういうところが教育はしていただいたのかどうか、それはどうなんですか。","respondent":"小栗区民生活事業部長","answer":"第１回目のときは、大田も、それから東京中央も参加していただきました。それで、そのとき、私、区民部長でたばこの所管をしておりましたので、地域振興部と区民部のほうも、大井町で街頭キャンペーンのときには両方が第１回目でしたので、参加して合同でやった。","voiceIndex":23,"id":"exchange-011"},{"speaker":"金高委員","kind":"質問","question":"２日間でも同じ費用なのか、１日でも同じ費用なのかという件が１点。それから、余った場合にはどうするか。というのは、いわゆる皆さん各ボランティアでもって、町会の方はそういう役員、あるいは手伝いということでもって、街のお祭りですから、１日のお祭りであっても、前後２日間、ですから、３日間は、そういう面でボランティアにとられてしまうと。","respondent":"長田地域活動課長","answer":"大崎第一地区みたいに、２日間にわたりまして大崎第一地区の中をさらに四つに分けまして実施をしているところもあります。ですから、合計８日間の実施というところもあります。それで、費用につきましては、基本的には、１地区平均で１００万円が出てあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"金高委員","kind":"質問","question":"それぞれ１３地区、今年は特に１３地区全部でやるということですから、私もできる限りいろんなところを見させていただいて、ほんとうに私も町会の役員をやっているので、町会の方が今回何人出るかということで、町会の中でよくそういう論議をするんですけども、確かに区民の皆さんは、楽しみのために皆さんそれぞれボランティアでやっているものですので、そういう面では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"原委員","kind":"意見","question":"各地区、地域センターが中心になってやってらっしゃるんだけれども、地域センターの職員さんが、毎年、結局一生懸命やってらっしゃるんですよね。例えば、大崎第一地区みたいに、毎週土・日、土・日、土・日、土・日という形で大変じゃないかなと思う。ほかの地域センターの職員さんも総出なんじゃないかなと思うんだけど、その辺のところ、何か反応というか、どう……聞いていらっしゃいますか。","respondent":"長田地域活動課長","answer":"それであと、土・日の問題ですけれども、基本的には健康管理上の問題もございまして、土・日を出勤した場合については、必ず振り替え休暇をとって、その週のうちに消化をしていただくということが原則になってありますので、基本的には、振り替え休暇で対応しています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"地域センターになって、地域との触れ合い、出会いという意味では、職員も相当努力されていて大変なんじゃないかなと思うんですけれども、地域の職員だけじゃなくて、応援に行く部分があるんですか。こちらの本庁のほうから、何人か手を出しますよと、貸しますよというようなことは、ここに書かないんだけど、やっていますか。","respondent":"長田地域活動課長","answer":"そういったところにつきましては、私ども応援体制を組んで実施をしていますし、実際には準備の段階から荷物を運んだり、やぐらを組んだり、こういったことも本課の中から応援を出しています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"原委員","kind":"提案","question":"ですから、今回もこれに沿って同じような形をとられてほしいということ。最後に、報告のほう、どういう報告にするかというのも、また委員長、副委員長のほうからご提案があるんじゃないかと思うんだけれども、それはまたちょっと後にして、去年はそういう意味では、震災絡み、商店街づくりの事例という形で行かれていますよね。ほかの方の意見を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-016"},{"speaker":"金高委員","kind":"質問","question":"沖縄というと、やはり基地という中において、産業の実態、あるいは商業の実態がどうも観光化というのが全面的に出てしまって、実際のそれ以外の産業が出ていないということですから、やはり我々も品川区と比較して云々ということと同時に、私たちもどういうふうにそれが違うか、どのように映ってくるかというのをちょっと見てみたいなという、特に個々に視察に行くというよりも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"私のほうは、区民委員会、いろんな事柄で調査していかなくちゃならないんでしょうけれども、今の不況の中で、産業振興マスタープランを、遅れていますけれども、品川区が中小企業支援をしていこうという立場に立っているんですけれども、不況の中でも、改めてやっぱり中小企業をどうやって支援していくのかという中身、今日出されたものづくり自慢ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"東大阪市はちょっと人口が品川区より多くて、５１万人ぐらいの都市になっちゃいますけれども。工業関係がちょっと多いという、ご承知の方もいるかもしれませんけれども、革新自治体になっていますので、中身としてはいろんな本で読みますと、非常にいい支援をやっているというふうに思いますので、東大阪市、希望で言えば、東大阪市へ行ってみたいというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"参加できるかどうか……。かつて、品川区の工場アパート建設が大きなテーマにあったときに、今の相川収入役が商工課長だったんですかね、一生懸命やったんですけど、全国で神戸がたしか工場アパート第１号だったみたいですけれども、神戸に行った経緯があると思うんですけれども、関西地区というのは、そういう意味では、商業・工業のかなり進んでいるところで、日本の発電所の第１号も京都ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"最終的に、ここで今これをと考えが行かないと思うから、正副の中で、〔「煮詰めていただいて」と呼ぶ者あり〕それで、それは我々も何も言いませんので、決めていただけばいいなと。場所も、結局どこというのはなかなか指示できないですから、ちょっと二つか三つか挙げてみていただいて、その中で、じゃあ、そうしようという話になると思います、逆に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"日程としては、今までの慣例としては、２泊３日で実施しておりましたけれども、２泊３日でいいかどうかについても、ちょっと日程的なものもご意見として伺いたいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"堺委員","kind":"提案","question":"それを含めて、ご提案いただければ、単純に今いろいろご意見が出た中に、沖縄はちょっと申しわけありませんが、除いて考えた場合、今の宿駅で京都ですか、それから東大阪市、環境で京都、例えばの話ですが、京都と東大阪と、こうなった場合、その辺で日程がおのずから割り出していけるから、それと沖縄となると、ちょっと無理があるから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-023"},{"speaker":"石田副委員長","kind":"意見","question":"東海道ベルトラインを通れば、静岡なり、岡崎なり、愛知、環境行政もありますし、大阪をとるなら、人材と組織とスポンサーということを考えれば、そういうところを見ていくんであれば、例えば大阪のオリンピック招致委員会が、負けるとわかっているのに、今どういう形まで突っ込んで市民が、区民が参加をしているのかというところもおもしろいところだろうと思うし。","respondent":"南委員長","answer":"ちょっとそこのところもいつの時期かも含めて検討させていただいて、次回に提示させていただけるようにいたしますので。では、今日のところは、こういうご意見でよろしいですか。","voiceIndex":60,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":20951,"voices":63}},{"id":"h13-20010703-7","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"厚生委員会","time":"午前１０時１１分～午後 １時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"嶋委員","kind":"質問","question":"一つお聞きをいたします。中軽度の利用される方の距離といいましょうか、場所、ここで言いますと、公的機関、医療機関ですから、まず東京都内という感じだと思いますが、２番目の、レジャーという広い意味の余暇活動にも、社会参加ということになりますので、場所的な指定というか、制限があるのかどうか。回数がどれぐらい利用できるのか、お尋ねいたします。","respondent":"日下部障害者福祉課長","answer":"具体的なお尋ねですけれども、まず場所の制限ですけれども、これは基本的にはございません。ただ、時間的な制約としまして、あくまでも、その日のうちにすべて終了するものです。ですから、例えばディズニーランドのほうに行きたいという場合、これも当然対象になってまいります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これを一つ教えてください。それと、この制度そのものが、前に予算特別委員会のときに、飯沼委員がお聞きしているんですけれども、このときに国の補助事業の活用ということでお答えをいただいているようですけれども、国の補助事業の活用で、１００％補助が出るのかどうなのか、そこら辺のところの補助率というのと、それから、国の補助事業の中身については具体的な規定があるのか。","respondent":"日下部障害者福祉課長","answer":"研修の内容でありますけれども、実はすでに７月からスタートということで、先週研修を実施いたしました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"費用の負担ですけれども、２６６万5,０００円以下の方は負担なしということですが、大体負担なしの方が何％ぐらいというのが分かったら教えてください。それから、研修で登録をされるということですけれども、登録は、何人ぐらい登録をするようになるのか、このことについて教えてください。介助人に対しては１時間当たり幾らというふうなことで出るのかどうなのか。そこら辺のことも教えてください。","respondent":"日下部障害者福祉課長","answer":"１点目の、ご本人の負担の見込みといいますか、これは率直に申し上げて、ご負担いただくようなケースというのは、現実問題としては、なかなかないかなと。","voiceIndex":9,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いろいろなリクエストがあると思うんです。男性であったり、女性であったり、年齢も当然何歳の方とか、そういうようないろいろな要望があると思うんですけれども、それの条件に合う介助人を調整すると書いてありますけれども、どれだけ調整できるのでしょうか。じゃ、これからどういうふうにしてそれを増やしていくんですかということをまとめてお答えください。","respondent":"日下部障害者福祉課長","answer":"１点目の事故の場合の補償の問題はどうなのかということでありますけれども、これはやはり私ども事業を開始するに当たって、大変重要な課題であると、このように認識をしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"人と人との関係より以上に、今課長がおっしゃったように、いろんな条件が違ってきますから、ですから、上のところで、いろいろ情報を持っているのは品川区ですから、こういう事業を派遣して、立ち上げて、いつも思いますのは、品川区が情報を一番持っているわけですから、それを十二分に生かしていただいて、介助人が集まらないことには話が進んでいかないわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"例えば朝起きたところが、急に午後に医者に行きたいとか、その日のうちに何か必要が生じたときに、朝、区に連絡をすれば、すぐ区はいろいろ連絡をとって、午後の必要に間に合うように、介助人を見つけるような連絡をとることができるのか、あるいは介助人として登録されている方々は、役所の勤務時間内に連絡がとれるような方々なのか。","respondent":"日下部障害者福祉課長","answer":"そういうことになりますと、できるだけ準備時間は欲しいところは山々なんですが、ただ、今具体的な例として挙げられましたように、例えばどうしても今すぐにというようなことがあれば、それはそれとしてしっかりと、できる限り対応できるようにしてまいりたいと考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"ヘルパー制度につきましては、知的障害者団体の方も、かねてよりご要望もなさってきた点は承知しておりますが、今回、７月１日からスタートすることによって、この派遣事業が実現したことについてどういうふうに受け止めていらっしゃるのかということ。","respondent":"日下部障害者福祉課長","answer":"知的障害者の方はそれぞれ一人ひとり全く障害の程度が３度、４度とか、いろいろありますけれども、千差万別なんですね。ですから、それぞれの方の障害特性をしっかりと理解して、どう対応できるか。そのためにはご家族の方からの情報提供をしっかりこちらがいただく。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"個人情報の提供を受けるわけですね。その介助人については、介助人のいろんな役目というものがあると思いますけれども、守秘義務の点につきましては、どういう内容になっているんでしょうか。研修に当たっても、そのことは言及されるかもしれませんが、文章的にもどういうふうになっているのか教えてください。","respondent":"日下部障害者福祉課長","answer":"守秘義務の問題については、事前の研修の中でしっかりこれを徹底するようにということで盛り込んでいる。そのようなことで守秘義務については徹底を期すということで進めてまいりたいと考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"１８歳以上の在宅の中軽度の知的障害者という、「中軽度」の知的障害者という意味合いというのか、何級とか、いろいろあるというのと、１８歳以上ということになると、高齢者の場合に痴呆性みたいなそういうものが知的障害者みたいな状況になってきちゃう。一般のボランティア活動で今までやっていたこと自体との係わりがどうなってくるのかというようなことをお聞かせ願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"１８歳以上ということで、高齢者はどうなるんだですけれども、私どもそこまで具体的な調整というところまでやっておりませんけれども、少なくとも知的障害者の「愛の手帳」をお持ちの方につきましては、１８歳以上であれば、年齢がかなり高齢の方であっても。","voiceIndex":20,"id":"exchange-009"},{"speaker":"須藤委員","kind":"意見","question":"制度開始が７月１日からということで、すでにきているんですけれども、これ自体が、今の説明が実際にあって、ここの動き方というのは今どうなっているのかなというのが、さっき言った、登録者についてもいろいろ研修していくとかという話だけれども、制度開始が７月１日ということなので、その辺の動き方がどうなっているのか。","respondent":"日下部障害者福祉課長","answer":"この辺は、先日の事務事業概要の説明の中でも若干触れさせていただきましたけれども、そういう準備段階を経まして、７月から実際にご活用いただける、このようなことになったという経過です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"須藤委員","kind":"意見","question":"経過はそれでいいんですけれども、７月１日に実際になってきているんだから、実際の動き方はどういうふうに、例えば来週からこういうので申し込みがあったよとか、登録者はここへ行きますよとかというのが、１日から始まるので、その辺の動きがどうなっているか。","respondent":"日下部障害者福祉課長","answer":"ですから、介助人、それから利用の希望者それぞれ、団体への働きかけはしておりますけれども、団体のほうとしても非常に期待感が強い割にはまだ手続きのところまでたどりついていないという状況ですので、せっかくスタートしたんですから、どんどんご利用くださいということで。","voiceIndex":24,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"せっかくいい制度ができて、準備も４月からしているんですから、本当にニーズがあれば、それなりの形が展開してきちゃうだろうと思うんだけど、その辺のところが、逆にニーズがない状況なのか、今言ったＰＲがしっかり行き届いていないのかという点になろうかと思うので、それを承知しながら、ＰＲの点などは、社会参加ということがこれから必要なことなので。","respondent":"日下部障害者福祉課長","answer":"実際には、これから夏場に入りますので、ちょうどお盆の帰省どきとか、そういうときも含めて、これから逆に夏場に入って利用が大分出てくるのではないかと、このように見込んでおります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"嶋委員","kind":"質問","question":"介助人が複数になって行くという場合も、レジャーに関してですけれども、１人でも多く楽しんで行きたいという部分があって、申込者の人が２人で来てもらいたいということが可能かどうか、お聞きいたします。","respondent":"日下部障害者福祉課長","answer":"ただ、例えば複数という場合、知的障害者の方が２人とか３人連れ立って外出をする、そういう場合はやはり１対１の関係じゃないとなかなか、どこか別のところへ行ってしまうとか、そういう心配もありますから、そういう場合は、例えば複数の方を配置するとか。","voiceIndex":28,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほど国の補助事業の具体的な規定があるのかということをお聞きしたんですけれども、２番の利用対象者というところが、補助事業で規定されているのか、それとも、例えば１８歳以下まで広げるということで区が決めれば、それはそれでさらに拡大することができるかどうかについて教えてください。","respondent":"日下部障害者福祉課長","answer":"ですから、国の要綱があります。要綱に則ってやっているわけですが、要綱の中ではあまり細かい決めまではしておりませんが、それに即して今度は東京都が実際の実施要綱を持っておりまして、東京都の要綱がかなり具体的な内容まで規定しております。","voiceIndex":30,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"３０ページに、平成１２年度までの実績で、今後の課題ということで、介護保険制度が入るまでも保健・医療・福祉の連携が必要だよということで、調整チームをつくってもらっていたんですけれども、介護保険制度が入ってきて、このサービス調整チームというのと、ケアマネージメント、その辺の関係がどうなっていくのか。あれば教えていただきたいと思います。","respondent":"中川原介護保険担当課長","answer":"代表者レベルの品川区全体ケア会議、それから責任者レベルの品川区統括ケア会議、実務者レベルの地区ケア会議というような形で、会議の内容に応じましてメンバー構成をいたしまして、それぞれ総合的な課題について検討をして。","voiceIndex":37,"id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"そのために福祉カレッジをつくるとかというような話になってこようかと思うんだけれども、その辺はどうでしょうか。","respondent":"中川原介護保険担当課長","answer":"特に例に出していきますと、痴呆の高齢者の問題とかが今はとてもケアマネージャーの悩みになっているんですが、そういったことがケース会議で出てきますと、情報提供とか、研修が必要な場合が出てきますので、それを統括で受け止めて、研修メニューにして、それを。","voiceIndex":39,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほど説明の中では割愛させていただきたいと言われたんですけれども、今まで品川区がこれまでやってきた施策の取り組みで何が大きな問題であったかというところは、たまたま割愛されたんですけれども、ページで言うと、１８ページぐらいからでしょうか、そういう説明を受けたんですが、何も問題がなかったから割愛されたのか、逆に、こういうようなことがあったから、だから。","respondent":"中川原介護保険担当課長","answer":"それからは、そこで情報がストップしておりますので、長期基本計画との整合性とか、この原稿のまとめに当たりましては、私ども品川区が関連課と調整をとりつつ自分でまとめたものです。２点目ですが、今までの取り組みで何が課題であったかということですが、第二章のことですか。","voiceIndex":41,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"それに当てはまる仕事を探しましょうという仕組みをつくっていきたいということなんでしょうか。その確認が一つ。お客さんの取り合いになってくる。だから、そういうようなこともいろいろ考えていきますと、本当にいい情報が集まってくるんでしょうかという危惧もするんですよ。そういうふうなことをどういうふうに調整をとっていくのかということを、併せてお答えください。","respondent":"野田口高齢事業課長","answer":"いわゆるハローワーク、それから民間職業紹介所、あるいは派遣事業との関連ですけれども、４３ページの図にあるように、例えばハローワークですと、どういう人が対象かというと、例えばフルタイムで一定の収入を得てというような形の方、それから例えば民間職業紹介でも。","voiceIndex":46,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"結果的には年齢で、これこれこうだから、ハローワークに行ってくださいよとか、そう言わざるを得ないかもしれませんけれども、もしそういうふうなことを考えていらっしゃるんでしたらば、むしろ区民の方がシルバー人材センターに行ったらば、どこそこも紹介してあげますよ、どこそこも紹介できますよという仕組みを逆につくっていったほうが、本来の目的が達成される可能性が高いと思うんですが。","respondent":"新美保健高齢事業部長","answer":"ただ、ハローワークとの連携がスムーズにいくかどうか、あるいは民間職業紹介とか派遣とかというところと、民業を圧迫にならないような形で、かつ公的な仕組みとしてどこまで可能なのかというような、今まであまり検討をしていない事項について今検討を始めたところですので。","voiceIndex":48,"id":"exchange-019"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、この計画を同時進行させていくということはとても難しいことなんですけれども、八つの推進プロジェクトに書かれた施策を展開していこうというふうにされているわけですけれども、今後の実施計画といいましょうか、実際上のそれについて、八つの重点推進プロジェクトの中でも、そこへ優先順位を付けて、この部分はいつまでにやろう、この部分はいつまでにやろうというような。","respondent":"中川原介護保険担当課長","answer":"具体的には、予算をつくります時期に１年、１年どこまでやるというのを財政のほうと相談してやりますが、これは主に仕組みづくりが、基盤整備は別としまして、お金のかからないいろんな工夫が盛り込まれておりますので、それはできる限り、今までもそうでしたが、高齢福祉課。","voiceIndex":50,"id":"exchange-020"},{"speaker":"鶴副委員長","kind":"意見","question":"品川区の福祉計画というのがとてもすばらしい点は、普通何かを事業を展開すると、すぐ予算を付けろだとか、人を貼り付けろだとかという論議が出てきますね。何でもただにしろだとか、そういう論議というのはもう時代遅れだということを、私たちは認識する必要があるんじゃないかというふうに思うんですけれども、どちらの部長でもいいですが、所見を聞いておきたいと思います。","respondent":"新美保健高齢事業部長","answer":"その場合は、今ある資源をどれだけ有効に効率的に使って、より質の高い、質をどう求めていくかということに課題が変わっていると思いますので、特に地域の行政としては、地域の中で使いやすい仕組みづくり。","voiceIndex":52,"id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"あるいはここからＡという病院が、ＣとかＤというところの紹介状は書くけれども、どこに行っていいかわからない。どこが受け入れてくれるんだろうという悩みが家族にも当事者にもつきまとっているこの現実ですね。この点はどういうふうな知恵で対処していきたいというふうにお考えでしょうか。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"お話の、病院を一定期間後退院が必要になるという方の扱いは、お話のとおり、大変難しい問題です。端的に申し上げますと、特効薬的なものはほとんど難しいのではないかというような感触を私どもも持ってあります。そうは言いましても、私どももそういう高齢者の方、あるいは介護をされている方のお声等はできるだけ把握しつつ、問題が奈辺にあるかということは認識は十分していきたいと思いますけれども。","voiceIndex":54,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次の２ページでは、施設の平成１３年３月の数値が1,９５７人となっていますけれども、これは一番最後のほうに施設、特養、老健療養型というふうなことで数値が出ているんですけれども、それ以外のところはどういうところからの数字なのかということを教えていただきたいと思います。それと、５６４人の、三つに分かれておりますけれども、それぞれの数を教えていただきたいと思います。","respondent":"中川原介護保険担当課長、新美保健高齢事業部長","answer":"滞納者についてのペナルティにつきましては、平成１３年１０月から満額になるに当たりまして、今いろいろ対応を考えているところです。払える方と、払えない方は分けて、ご相談に乗りたいというのは、今までもご説明してきたところです。ご質問のうちの訪問看護と訪問リハビリが、確かに他のサービスに比べますと、平成１１年度実績対比で減少しているわけですが、その理由等々についてのお尋ねですが、これはまさに事実でございまして。","voiceIndex":62,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの訪問看護とか、訪問リハビリというのは、かなり料金が今までの負担分に比べて３倍以上の負担になっているというふうなことも使いにくいというふうな状況になっているんじゃないかなと思うんですけれども、この点では、目黒区などでは、そういうところで医学的な部分から見ても、これが本当に必要だというところで。","respondent":"新美保健高齢事業部長、中川原介護保険担当課長","answer":"利用料の軽減については、一般質問等でもお答えいたしましたけれども、私ども現時点では特に考えておりません。当初予算ですが、保険給付費全体で１０３億円、在宅が３６億円、施設が６７億円という、大ざっぱですが、そういった数字になってあります。","voiceIndex":65,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"在宅計が３６億円で、その下の在宅というところについても教えていただけますでしょうか。","respondent":"中川原介護保険担当課長","answer":"在宅計の下の在宅は２６億円です。","voiceIndex":68,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、在宅のところでは補正で増えているというところでしょうか。","respondent":"中川原介護保険担当課長","answer":"増えております。ホームヘルプとか、デイサービス等は増えてございましたので。","voiceIndex":70,"id":"exchange-026"},{"speaker":"須藤委員","kind":"質問・要望","question":"１ページの普通徴収８9.９３％という数字が、これが他の自治体と比べてどういう状況なのかということ。３ページ、ケアプランを作成しているということで、在宅介護支援センター、その他支援センター以外でつくられておりますけれども、そのときのケアプランの差異というのが何か特徴的に出てきていれば、教えていただきたいと思います。その場合に、区の負担というのが、どういう対象になってきているか。","respondent":"中川原介護保険担当課長","answer":"苦情の対応ですが、これも１０ページの、対応状況というところがございまして、そこを見ていただきたいんですが、(1)の相談件数と対応状況ですが、申立件数の右に対応状況とあります。","voiceIndex":72,"id":"exchange-027"},{"speaker":"須藤委員","kind":"意見","question":"最初のほうは、ほかの自治体はまだ出てきませんというので、しようがない。それから、３ページのケアプランの差云々というのは、支払いのときなどでトータルで区でやるんじゃなくて、どういう形で支払いを。それから、ちょっと抜けたのが、２ページの、二次判定における一次判定の変更数が、他の自治体と比べてとうなのか、３２％というのがどうなのかなというのをもう一度お願いします。","respondent":"中川原介護保険担当課長","answer":"要介護認定の２ページの変更数ですが、３２％というのは、区の情報交換の段階では大体このような数値で動いておりましたが、１年経って今の数字を突き合わせたことはまだやっておりませんので、今後検討したいと考えています。","voiceIndex":74,"id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"ケアプランの差が云々というのは、それぞれこっちでサービスの利用割合という形が出てきているので、その辺からつかんでいくと、在宅介護支援センターではどういう人たちがというのは数字がつかめてくるんじゃないかなと思うんだけど、そういうことではいかがですか。","respondent":"中川原介護保険担当課長","answer":"介護報酬からどのくらいのデータが読み込めるかというのは、現在精査中ですので、そういった点もちょっと視野に入れて検討をしてみたいと考えています。","voiceIndex":76,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"利用率のことがここに書かれていないんですが、支給限度額に対して、要介護度別の利用率が分かったら教えていただきたいんです。","respondent":"中川原介護保険担当課長","answer":"それがこの頃、上限額に対して何％使っているとか、どの数字を用いて計算した数字かというのが明らかになっておりませんので、当初予定した在宅サービス利用率の意味と随分変わって数値が使われてはいないかどうか、ちょっとそこら辺も検証しなければいけませんので。","voiceIndex":78,"id":"exchange-030"},{"speaker":"須藤委員","kind":"質問","question":"この場合、さっきの１万7,９２３人の第２段階の方がいらっしゃるんですけれども、そのうちどのくらいが該当してくるというふうにお考えになっているでしょうか。","respondent":"中川原介護保険担当課長","answer":"これは申請という手続きを経て出てきますので、あくまで見込みなんですが、今までこういった低所得者の対策をやっている自治体に確認しましたところ、大体５％ぐらいの出現率が見込まれるということでしたので、参考にさせていただきました。ということで、約1,０００人程度。","voiceIndex":85,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"申請とかがあるので、５％ということですが、全員が申請をしたとすれば、その対象となる人数はどれくらいなのかということ。預貯金の金額の３００万円ですが、入院とお葬式代を合わせて３００万円ということだと、ちょっと少ないのではないかなという気がするんですけれども、これはどういう金額で、葬式代も平均でどの程度で検討したかを教えてください。","respondent":"中川原介護保険担当課長","answer":"どのくらいの方がこの対象になるか、扶養を受けているか、いないか。仕送りがあるか、ないか等は、そういったものはわかりませんので、あくまで申請をして、この対象となる方が約1,０００人ぐらいということで見込んでおります。","voiceIndex":87,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"預貯金の額なんですけれども、葬式代でも今平均で３００万円というふうに聞いたんです。いつ入院するかわからないという状況になって、そういう年齢の方ですので、そういうことを考えると、ちょっとここの金額も、もうちょっと上げていただくということでご検討いただけないかなというふうに思うんです。","respondent":"新美保健高齢事業部長","answer":"この辺の数字につきましては、第１回の定例会の会期中の厚生委員会でご説明をいたしまして、委員の皆様からも特に異論なく、私どもの中も、先ほど申し上げたような形で３００万円未満ぐらいだと。","voiceIndex":89,"id":"exchange-033"},{"speaker":"鶴副委員長","kind":"質問","question":"軽減措置と、どこかの政党がおっしゃっている減免制度というのはどう違うんですか。","respondent":"中川原介護保険担当課長","answer":"その中で本当に生活が苦しいという高齢者の層が保険料の所得５段階だけでは見極められない、ただし、第２段階に属する方には生活保護と同じくらい苦しい方がいらっしゃるという中で、この基準を設定したものです。","voiceIndex":91,"id":"exchange-034"},{"speaker":"鶴副委員長","kind":"質問","question":"これは現実対応型の軽減措置だというふうに思うんです。本当の餌を食べたかったと思うに違いない。厚生労働省の基本方針も保険料をゼロにするような減免制度とかそういうことはやらないというふうに言っているわけですから、そういう軽減措置、その中で何ができるかということで、品川区の選択しているこの措置というのは、現実対応型としての適切な措置じゃないか、私はそういうふうに思うんです。","respondent":"新美保健高齢事業部長","answer":"介護保険の場合、国が全体の大枠を固めて、あとは地域の実態の中で一番区民と接する自治体のところである範囲内でやるですので、私どもも基本的には国の考え方が適当だと考えていますし、それに沿った形でこういう形のものを考えまして、他の自治体等のあれもありますが。","voiceIndex":93,"id":"exchange-035"},{"speaker":"鶴副委員長","kind":"質問","question":"これについてのお知らせというのは、広報しながわ等なのか、あるいは別の手だてでやるのか。あくまでもこれは被保険者からの申請に基づいて個別に審査をして決めるということですから、「あなたは該当するんじゃないですか」というようなことで、個別通知はしませんよね。この軽減措置の趣旨徹底については、どういう方法で行われるんでしょうか。","respondent":"中川原介護保険担当課長","answer":"三つ目は、７月に納入通知を皆さんに発送するんですが、その中で第２段階の方に、区ではこういった制度をご用意しましたので、保険料について大変な方はご相談くださいという、そういったご案内をするということで対応をしております。","voiceIndex":95,"id":"exchange-036"},{"speaker":"船波委員","kind":"質問","question":"それはもちろん障害のある人が仕事としてやることですから、その他の普通の経済活動のように売れたりとか、収入があったりするというのは難しい。だけれども、今までのような非常に低い賃金ではなくて、多少なりとも高い賃金が得られるようなスタイルでやっているという、パン屋さんと共同して出店するということになっているというのがあるので、具体的にはそこはどうかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-037"},{"speaker":"嶋委員","kind":"質問・要望","question":"そのほかに、障害者の方が、これからバリアフリーになってきてどんどんまちの中に出てきていただきたいという思いがあるので、まち全体が障害者のまちというか、マップとか、ガイドブックとかができていて、明確にここには全部設備がそろっているというようなところがあったら、ぜひ見てみたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"障害者のことももちろんですけれども、私が思うには、介護保険が始まって約１年以上経って、幾つかの自治体で、品川区と同じように満足度調査を実施している資料が出てきています。私の手元には、静岡県の藤枝市ですから、近過ぎるものですから、ただ、藤枝市でも、実際にサービスを利用している事業者の５段階評価とか、全体の傾向など、いろいろ詳細に調査しているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は、住民が福祉をどういうふうにつくっていくかというふうなところに住民がどう関わっていくかというふうなところで、鷹巣町の記録映画、「住民が選択した町の福祉」というので見たんですけれども、これは介護保険だけでなくて、いろいろなワーキンググループができていまして、住宅の問題から、ボランティアの問題、福祉行政、在宅介護、補助器具、子育てエンゼルプラン、介護保険もそうですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"介護については、伊藤委員が話したので、この制度が入ってきて、いろいろな自治体かいろいろな特色を出しているので、日本の新美部長といわれる人なので、トップをいっているだろうと思うんだけれども、秋田から近くだと、宮古の市長がドクターで、介護保険制度をつくるときに携わったのが宮古の市長も入っていて、この方は自分自身が医者で、ただ、人口的に６万人ぐらいの小さな市なので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":48141,"voices":118}},{"id":"h13-20010703-8","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"建設委員会","time":"午前１０時１１分～午後３時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"３の請願審査","agenda":"３の請願審査","exchanges":[{"speaker":"横山副委員長","kind":"質問","question":"経過について聞きたいんですけれども、この物件は１万m2を超えるということで、都の許認可物件ということで、今日まで６回でしょうか地元と説明会の中で積み上げてきて変更案が示されて今日あって、６月２５日に東京都が主催する公聴会へそれぞれ赴いて、双方の立場から会合が持たれたという報告なんですけれども、最終的には都が判断する。","respondent":"浜脇住環境整備課長","answer":"その辺の対策といいますか、変更案といいますか、そういったものを都のほうでも判断の材料にすると思います。これに基づいて、建築審査会にかけるということで、私どものほうでいつかけるかということは、まだ聞いてございません。","voiceIndex":11,"id":"exchange-001"},{"speaker":"横山副委員長","kind":"質問・要望","question":"今、経過の説明があったわけですけれども、公聴会という第三者的な立場というか、そこに委ねる部分が多いんだと思うし、これからもう１本マンション建設に係わる部分の審査があるわけですけれども、これまで建設委員会にかかってきた部分で、高層部分の削減を求める、これが第一項目と言っていいか、もうすべてがそこに係わるわけだけれども、こういった場所で建築法上認められているという建物に対して。","respondent":"田平建築課長","answer":"その許可基準に合致しているから説明会が始まったと言えばそれまでなんですけれども、実は許可基準の中にはいろんな事細かな市街地の環境に寄与する整備、公開空地のあり方から風の問題、それから落下物対策、そういったことがきめ細かに網羅されておりまして。","voiceIndex":13,"id":"exchange-002"},{"speaker":"横山副委員長","kind":"質問・要望","question":"高さについては、今言われるものだと思うんですけれども、今日まで説明会等を開いて、形状的に取るところは取ったり、丸みを帯びたり、住民の要望に応えてきているんだろうと思います。大体、当委員会に出される請願も、住民の要望というのは高さに対する要望は当然のこととしてあるわけだけれども、階数を減らしたという事実はほとんどないというか、そういった形で来ているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-003"},{"speaker":"沢田委員","kind":"確認","question":"この土地はバブル経済の崩壊前にも、何年か前に確認申請を取って大分話し合いがされた土地だと思うんですけれども、そのときの規模等があって現在に至ったわけですけれども、規模で言うとどれぐらいの変化があるのか、その二つをお願いしたいと思います。","respondent":"浜脇住環境整備課長、田平建築課長","answer":"これは建築主から聞いた話なんですけれども、容積率のアップにつきましては、今委員お話しのとおり、公開空地の関係が決め手になるようでございまして、今のところ現行容積に対しまして２８４％をプラスして。当時、やはり紛争になった経過がございまして、裏のほうに１４階建ての賃貸マンションが建っていますけれども、手前の土地の部分にも同じく１４階建ての事務所計画がございました。","voiceIndex":16,"id":"exchange-004"},{"speaker":"沢田委員","kind":"確認","question":"東京都のあれですから、区がそのことについて詳細がわからないのかもしれないんですけれども、容積が２８４％プラスになるとすごいですね。それから、少なくとも前回別の事業者が近隣住民と一定の合意に達して、確認もおりた。なぜ、こんなことになったのか、前回の確認がおりた中身がどうなのか説明してほしいと──出ないんですけれども、これは後ほどでもいいんですけれども、出してほしいなと。","respondent":"山室住宅指導担当部長、田平建築課長","answer":"今の委員のお話で、一部なんですけれども答えさせていただきたいと思います。平成３年当時の確認申請の経緯ですが、平成３年７月に申請されておりまして、９月に処分が行われております。しかし、その後４年経った平成７年７月１７日に工事の取り止め届けが出ております。","voiceIndex":19,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"割増が２２２％ということなんですけれども、それで容積に幾つまで膨らんだのかですね。ここにも日影図で見ると、公園はちょうど１２時という一番冬至の熱量の多い時間帯に陰るようになっているんですけれども、その辺について区民のある意味で公有財産ですから、日影が影響を及ぼすことに対しては何か──所管はここではないんだけれども、答えられたら答えていただきたい、この問題に対する対応を。","respondent":"田平建築課長","answer":"通常、グランドラインレベルで冬至で１日のうち２時間日影になるというのは、公園の所管ではないですけれども、これはある意味では常識の範囲かなというふうに考えております。個人的な見解ですけれども。","voiceIndex":22,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"前回の建物が２万８,９４５m2であるのに対して、３万２,０００m2ですか。前回は１４階でボーナスをつけたのと、今度は３０階というようなけた違いの高さになっているのはどういうわけなのかというのが私はわからないんですね。ところが今の説明ですと、単体に２時間ぐらい常識の範囲だと言うけれども、複合になっていくわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"菅家委員","kind":"質問","question":"おそらく説明会の中での関係者のご意見等を伺いながら、施主側が設計変更をされたものというふうに理解しているんだけれども、この時点での双方の見解はどういう理解になっているのか。は風害や落下物の問題と、地域住民主体の条例の制定ですが、条例関連については後ほど時間をかけてこのことについて十分審議していかなきゃいけないけれども、とりあえず今の問題をお尋ねしたいと思います。","respondent":"浜脇住環境整備課長","answer":"２点目の妥協点あるいは打開策といったような話ですが、先ほども申しましたけれども、５回の説明会あるいは公聴会を通して、やはりこういうご意見を伺いながら、建築主側ができることはやっていこうということは姿勢的にあるというふうに推測しています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"菅家委員","kind":"意見","question":"今度建築計画がまた新しく出てきたんだけれども、今１４階の建物が建っていますけれども、あれを建てるときも１４階というのは高すぎるという意見はたくさんあったわけです。特定街区の場合は確かに高さも容積も、総合設計よりも特定街区のほうがおまけが大きいと認識しているんだけれども、高さは制限がないというのはおかしいけれども、違いはどういうことなのか。","respondent":"田平建築課長","answer":"高さの問題に関しましても、特定街区は都市計画ですから、新宿の超高層街はまさにいい例ですけれども、１,０００％を超えるような、しかも高さもある建物ということで、都市計画でできました。","voiceIndex":27,"id":"exchange-009"},{"speaker":"菅家委員","kind":"質問・要望","question":"いろんな立場でこういうことを取り扱っていかなきゃいけないんだと思うんだけれども、日影だとか用途だとかという問題については、非常に難しいことだと思うので、ましてや先ほども意見が出たように、公聴会等の経過もありますし、私どもが直ちにこのことについて是であるとか、否であるとかという結論を出せるような性格のものではないと思うので、やはり建築審査会等の意見や何かを待ちながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-010"},{"speaker":"上山委員","kind":"質問・要望","question":"例えば、今回で言えば、庇をつける、北側部分はカットするとか、住民側の皆さんから見れば要望も聞かれているようなんですけれども、３０階のところだけはその限りではないので、何か情報でもあれば伺いたいと思うんですが、どうでしょうか。","respondent":"浜脇住環境整備課長","answer":"経過の中で説明したように、１回目から始まって５回目、あるいは公聴会を含めて争点と言いますか、話題と言いますか、それについては絞られてきているのかなということで、できるものは努力していると申しましたけれども。","voiceIndex":30,"id":"exchange-011"},{"speaker":"上山委員","kind":"質問・要望","question":"しかし、今現在で言えば、例えば都営も１４階建てですし、住民サイドから見れば倍以上の高さになるというのは、先ほどの請願を出されている都市開発型制限の変更を求める、求めるといっても求めたいというのはわかります。。ただ、今現在すぐこれでどうとなかなか私どもは言えないところがあると思います。取り扱いについては、また後で出るかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"辻委員","kind":"確認","question":"この物件自身の所管というのは、東京都の建築確認とか。住民説明会を５回行ってきて、公聴会は東京都ですけれども、この辺の経過とか業者の説明会の報告とか、あるいは住民に対しては、こういうことについてこうだったという、これは都の建築確認物件と品川区で行う物件と同じように来るんですか。報告は聞いているんだけれども、どういう性質のものですか。","respondent":"浜脇住環境整備課長","answer":"実は建築紛争予防と調停ということで条例がありまして、説明会を行った場合には速やかに議事録を提出するということが決まってあります。そのために、都物件ではありますけれども、私どものほうに説明会のあらましですけれどもいただいている。","voiceIndex":33,"id":"exchange-013"},{"speaker":"辻委員","kind":"質問","question":"ある部分は評価をしなきゃいけないんじゃないかと思うところと、風害のこととか、実際にそれがどういう影響になってきてどうなって改善されたとか、まだまだ不十分じゃないかとか、この辺の話し合いが、実際に現場で説明会をやりなさいだけではちょっと足りない、これは東京都の物件だとしても、区のほうへこういう報告が来るんだったらそういうふうにして、もう少し突っ込んだ話を聞いて。","respondent":"浜脇住環境整備課長","answer":"先ほど説明会の報告書というときに、建築紛争予防条例の中でいただけると言いましたが、これは１万m2を超していますので、必ずしも品川区のこれに当てはまらなくて、やはり東京都のほうに出すというのが基本です。","voiceIndex":35,"id":"exchange-014"},{"speaker":"辻委員","kind":"質問","question":"だから、住民の方の声というのはどこかで聞く、ないし報告があるかどうかしらないですけれども、そういう説明があって、住民の方もぜひこういう説明会があってこうなんですよという、この辺の説明をしている側の方が、例えばこういうものについて意向を受けたとしても、その点についてまだ十分理解できませんでしたとか、不十分でしたとか。","respondent":"浜脇住環境整備課長","answer":"その辺で建築主がただ開きましたという感じではしようがないから、ある程度住民が納得しない、あるいは理解が深まらない、あるいは説明が不十分というようなことであれば、やはりこういうところについて説明をするなり。","voiceIndex":37,"id":"exchange-015"},{"speaker":"築舘委員","kind":"質問","question":"大崎は、そういった意味では超高層になってきているということだと思うんです。ですから、今後は副都心ということで超高層になれば、ここの土地の価値が高くもなってくるということもあるし、ますます便利になってくるということも含めて、今は３０階建てというのはここが初めてですけれども、周辺もどんどんなってくると思うんですが、この点の見通しをお聞かせください。","respondent":"浜脇住環境整備課長","answer":"ですから、今、区のほうでも大崎や東五反田のほうに副都心としての整備を進めているわけですから、そういった意味では都心の一部というふうにとらえることになってきて。","voiceIndex":40,"id":"exchange-016"},{"speaker":"築舘委員","kind":"質問","question":"という意味では、環境というのは、昔は１階建ての平屋が多かったわけですけれども、だんだん変わってきているということもあるので、そういう未来を買うということもあるわけですから、その点の理解というのは必ずしも住民の方が固執して持っているということはどうなのかなということ。それから、日影とか風害とか落下物ということに関しては、５回ぐらいの説明会なり何なりで変更をかなりしていると。","respondent":"浜脇住環境整備課長","answer":"ですから、５回の説明会の中でできることはやっていきたいというふうに、できるもの、できないものあると思うんですが、やはり建った以降のそういったものを含めて、この施設がただ反対、反対だけで建ったということではなくて。","voiceIndex":42,"id":"exchange-017"},{"speaker":"沢田委員","kind":"提案","question":"現実に話し合いがされていると、それから改善提案も出されていますので、議会のほうとしてはそこを大事にして、継続とするということについて賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-02","title":"平成１３年請願第６号 ビル建築計画に関する請願","agenda":"平成１３年請願第６号 ビル建築計画に関する請願","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"事実経過のところで確認させていただきたいんですけれども、この請願書は多項目を出しているんですが、請願理由の９番目あたりに、「住民側は劣悪な立地条件の当地において問題点の多い建築計画は容認することができないので抗議したが、施工業者は工事妨害禁止の仮処分を申し立て云々」とありますけれども、今現在というか、出されたときと時間の経過があるかと思いますけれども。","respondent":"浜脇住環境整備課長","answer":"先ほども申しましたけれども、説明会の中で質疑がありましたけれども、その辺を述べているんじゃないかと推測しております。","voiceIndex":52,"id":"exchange-019"},{"speaker":"上山委員","kind":"質問・要望","question":"あまり詳しくなくて恐縮なんですが、こういうような事例というのは、他にあるかどうか知らないですけれども、具体的な内容を何て書いてあるか、現場の看板を見てもよくわかりませんけれども、こういうような事例というのはあるんでしょうか、もしわかれば紹介していただきたいということ。こういうような事例がほかにあったのかどうか、品川区でなくても構わないんですが。","respondent":"田平建築課長","answer":"これも裁判例としてあります。それと、住民の方が工事トラックの車両を阻止して、実質的工事ができなくなるということで、これも工事妨害禁止の仮処分があります。これは人が邪魔しているという例は、一昨年ぐらいに確か滝王子通りのほうのマンションであったかと思います。","voiceIndex":54,"id":"exchange-020"},{"speaker":"上山委員","kind":"質問","question":"何かいろいろあると思うんですけれども、また後で伺いますけれども、今回この請願書の最終的に持つのは別なんですけれども、印象で本文のほうに、この文書からあるいは請願理由なり、理事者からの説明からしても、平行線になっているという話で、歩み寄りそうもないということで、私が聞いていても残念には思うんですけれども、その辺の一番の問題は、もとが平行線になっている。","respondent":"浜脇住環境整備課長","answer":"工事車両の搬出入、駐車について、工事工程表について、ごみ置き場とごみの出し方について、４階建ての３階建てに変更する要望について、ワンルームマンションの管理マニュアルについて、建築主の出席と説明について、管理人室の設置について、建築主がお住まいになるんですが。","voiceIndex":56,"id":"exchange-021"},{"speaker":"上山委員","kind":"質問・要望","question":"もちろん建築基準法に違反していないわけだから、その限りで建築確認を出されているわけですから、いろいろあるかと思うんですけれども、その辺での区側から、住民から言われたことあるいは要望もあると思うんですけれども、そういうことに対して一般的住民の皆さんからこういうところをぜひ業者に伝えていただきたいとか、あるいは話してもらいたいということがあったかと思うんですが。","respondent":"浜脇住環境整備課長","answer":"しつこくなりますけれども、やはり第３回の説明会でなかなか歩み寄りがないというのは、報告書の中でわかるわけです。","voiceIndex":58,"id":"exchange-022"},{"speaker":"辻委員","kind":"質問","question":"この後ろ側の住戸は建主さんが住むんですか。ここは工場ですよね、工場については前から工場があったんですか、経営者はどなたですか。従前から工場があったのか。自転車置き場も取ってつけたような感じで、どうなっているんですか。住民の方も管理人を置けと言っても、大家さんがいるんだったら管理がいなくたって、それ以上の管理人はいないはずなんだけれども、この辺を説明するとちょっと……。","respondent":"浜脇住環境整備課長、田平建築課長","answer":"自転車置き場が変更案ではできたということですけれども、荷物の出し入れに邪魔になるような気もしますけれども、やはりワンルームマンションというのは若い方が入って、バイク・自転車等を路上に置くのではないかというご心配があって。建主は、お父さんの代から３０年ぐらいにわたって工場を営んでおります。","voiceIndex":60,"id":"exchange-023"},{"speaker":"辻委員","kind":"質問・要望","question":"ところが、今回の場合、一緒に住むということですから、ある面ではぜひ話し合いをきっちりやっていただきたい。昨日行って、もう１回行けと言われても、ちょっと地域的に不案内なものですから、地図を探しながら行かなきゃいけないですけれども、昨日関係者の方がいる中での視察です。確認ですけれども、標識が出た後の一回目の説明会はいつでしたか。聞き漏らしたので、日にちだけお願いします。","respondent":"浜脇住環境整備課長","answer":"３月１５日です。２回目が４月２６日、３回目が５月１５日。","voiceIndex":63,"id":"exchange-024"},{"speaker":"辻委員","kind":"質問・要望","question":"率直な感想として、確認申請を出すときに、もうちょっとじっくりやってというのはあるんですけれども、３月６日に標識設置、３月１５日に説明会をしてすぐに３月２７日に申請を出すとかと、もうちょっとじっくりやってもらいたいなというのが正直な話なので、そういう中で話し合いを進めていっていただきたい。","respondent":"浜脇住環境整備課長","answer":"先ほどと同様になりますけれども、個々について私どもは判断をするというようなことはできませんので、話し合いの場をつくる努力をしていきたいというふうに思っております。","voiceIndex":65,"id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"５月１１日、これはあっせん案の出た日ですか、最初にあっせんをかけた日ですね。施主側も住民側も感情的になっているんじゃないかと思うんですけれども、あっせんを通じてどういうあれだったのか、雰囲気を聞かせてもらいたいというふうに思うんです。","respondent":"浜脇住環境整備課長","answer":"同様のことばかり言って申し訳ないんですが、結局は第１回の説明会のときの質疑、第２回目の質疑がありました。それをほとんど住民のほうは主張なさっていたという状況です。","voiceIndex":67,"id":"exchange-026"},{"speaker":"沢田委員","kind":"確認","question":"これは土地柄があるから、あれだけ住宅が密集しているところに建つので問題になっているのは十分わかるんですけれども、４階程度であれだけの紛争というのは普通ないですよね、昨日行ってびっくりしちゃったんだけれども。建築主のほうは、確認がおりた建物を建てるのを一体何を妨害するんだという思いが非常に強い。","respondent":"浜脇住環境整備課長","answer":"今、委員の言ったとおりで、状況は委員にお話ししたところでありますけれども、私どもは当事者に判断を申し上げるというのは非常に難しいわけですから、また繰り返しになりますけれども、やはり調整しかないということで、やはり施主が帰ってきて工場をやって。","voiceIndex":69,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"住民の皆さんは、そういう姿勢だからワンルームに入っても、例えば近隣とトラブルが起きたときにも、辻委員が言うように、管理人以上の人が常駐しているんだけれどもやっぱり不安だという、不安が不安を呼んでいるような関係が難しくしているんじゃないかなというふうに思うので、間に入って区が何らかの調整に乗り出すということ以外にはないんじゃないかなというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-028"},{"speaker":"菅家委員","kind":"質問・要望","question":"ましてや、たかだか４階建てですよ。近隣には３階までの建物が建っているんだから、そんなに大騒ぎするほどの建物の構造ではないはずなんです。決して違反建築に入居するわけじゃないんですから、できたものに対しては温かく地域に迎えてあげられるような、そういう環境をつくることが、むしろ住民の役割だと思うので、まず話し合う土俵を双方に呼びかけてお骨折りいただきたいと、私から要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-029"},{"speaker":"横山副委員長","kind":"意見","question":"継続で結構なんですけれども、今、菅家委員が言われた道筋で、やはり双方いろいろとわだかまりがある部分を、それぞれの代表者の圧力にならないような形で、施主また業者、地元の方々、そういった中での話し合いというのは、明日からでも進めてほしい、それが基本だと思います。そういった意味の継続で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-030"},{"speaker":"辻委員","kind":"質問・要望","question":"思い切って出てくるなら、話し合いになるかもしれませんし、双方にこの委員会の考え方を伝えてもらって、話し合いの場をつくるようにしていただきたい。今回請願が出て審査しましたが、本日は継続をお願いしたい。それから、これが継続になったという、その辺の事情をよく双方に伝えていって、何らかの進展があれば、７月中旬には裁判の方も進むということですし、その辺も聞いていきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問・要望","question":"趣旨は同じで継続なんですけれども、こうしたときに施工業者が専門の仕事をしている者として、施主をいさめたり何かする立場に本来立つべきだと思うんです。だけど、そうでもないみたいで、だからまとめ役というか、人がいないから非常に先鋭的になっちゃうんだと思うんです。とりあえず継続で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":31519,"voices":86}},{"id":"h13-20010703-9","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"文教委員会","time":"午前１０時０９分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"大きく分けて二つ質問いたします。一つは採択の関係なんですけれども、きょうも各紙記事で新しい教科書をつくる会の歴史教科書についての韓国要求が５箇所訂正になったと。このことについてどうなのかという、採択の考え方です。そういう点は、意見反映はどういうふうになっているのかという、その大きく２点教えてください。","respondent":"青木指導課長","answer":"１点目ですが、教科書の自主編成ですけれども、この検定というのは、それぞれの教科書会社が民間にゆだねるということで、それぞれの著作者の創意工夫を期待しているわけですから、そういうそれぞれの会社が自主的に編成したものを検定にかけて。","voiceIndex":3,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"多分、５,０００人前後ぐらいかなと思うんですけれども、そういう点からすれば、そうした考え方を、やっぱりアジアとその日本の平和、そして世界の平和というその平和協調、国際協調という、そういう点というのはふさわしい基準になるのかどうかというのをもう一つ聞きたいのと、それから先ほど申し上げた品川区の核兵器廃絶というのは、即廃絶をということで、理想論ではなくて。","respondent":"青木指導課長","answer":"２点目の意見聴取ですけれども、この調査研究会と検討委員会から出されましたその資料は、当然客観的な事実を定量的に分析しているというのがベースになっておりますけれども、採択するに当たりまして、教育委員がその資料を読みこなすというんですかね。","voiceIndex":5,"id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"４回にわたって、それぞれ官房長官、河野、宮沢、それから村山首相、小渕首相も答弁しているし、植民地支配に対する多大な被害を与えたと、そのことについても反省をすると、具体的なそれぞれの反省を述べているわけですから、それはもう態度ははっきりしているわけですよ。特に品川区での基準のところでどうなのかと言っているわけですから、明確なご答弁をいただきたいというふうに思います。","respondent":"青木指導課長","answer":"それ以上、それ以外の意見を聴取するということは一切考えておりません。","voiceIndex":7,"id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望にとどめます。意識的にご答弁を返した点かわからないのですけれども、ふさわしい基準のところで見てあげて、それについて見解を最初から求めているんだけれども、どうもそこは答えたくないという感じなんでしょうか。二つの点で、先ほど言ったように、今大きな問題になっている歴史教科書の事例を挙げて、こういう点について、ふさわしい基準なのかどうかと。そのことだけ申し述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":5439,"voices":14}},{"id":"h13-20010703-5","meetingId":"h13-cm07","date":"2001年7月3日","dateIso":"2001-07-03","committee":"総務委員会","time":"午前１０時０４分～午前１１時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の(1)の報告事項","agenda":"１の(1)の報告事項","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"上の部分、道路橋梁費のほうなんですけど、これによって、区は何か損害を受けるとか、工事が遅れて工事、請負契約の相手方に何か補償するとか、区として何かそういうことは。何も一切ないままなのですか。","respondent":"市岡企画財政課長","answer":"工事全体が遅れたことによって、確かに事業費を含めて経費は余計にかかるわけですが、その埋立事業は、もともと東京都からの１００％の受託事業ですので、それらの経費も含めて、１３年度にすべて受託費として東京都から財源を補てんしていただきますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"具体的に、工事がこれから始まるというので、どのくらいにその額がなるのかとか、そういうことはこれから出てくる問題なんでしょうけれども、やむを得ない相手というか、漁師というか、船宿というか、そこの人との話し合いに関して、当初の予算を組むなり、事業を始めたりするときには、つくというふうに考えて、話が甘かったとか、そういうような反省も含めて。","respondent":"市岡企画財政課長","answer":"かかった追加の補償費があれば、これはまだ確定しておりませんので、それも含めて１３年度に受託収入として新たな収入をする、こういう関係です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"三上委員","kind":"質問","question":"今、この計画を伺って、この建物に出入りする１日の、要するに勤めていらっしゃる方を含めて、一般のテナントにたくさんの人やお客さんと申し上げているような方も、出入りとかあると思うんですけれども、そこらあたりの人やお客さんとの出入りについてはどういうふうに計算されているのでしょうか。","respondent":"太川総務課長","answer":"計画の段階で伺っていますのは、自治会館に出たり入ったりしている部分を約１,０００人、それからあと、地域住民が出たり入ったりする部分で２,０００人ということで、３,０００人ぐらいの人間が出たり入ったりするのではないかという想定です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"三上委員","kind":"質問","question":"ということは、あまり広範囲な形で人を集めるというふうな商業施設にはならないというふうに見ていいのでしょうか。通常で言う、この周辺地域のちょっと大きめのストアみたいなのが集まったような雰囲気で、１億円ぐらいの店になるかならないかぐらいのものが入るという雰囲気でしょうか。","respondent":"太川総務課長","answer":"それと、やはり今委員がおっしゃいましたように、周辺の部分からのいろいろ事務所等、わりと小さなところがまだたくさんありますので、そういうところの方たちが昼食、買い物等に来ていただけるものにしたいというのが考え方です。","voiceIndex":15,"id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"しかし、経費はどうやって浮かそうかということで、非常に苦労した数字が今１,０００万円強の経費が節減できるなんていう、こういう単純計算されているんでしょうけれども、もうちょっとそこらあたり、特色的に地域の集客というところを言っていかなきゃいけなかったと、もっとすべきではなかったのかなと、そういう論議というのはされなかったんでしょうか。","respondent":"太川総務課長","answer":"ですから、そういう意味からいいますと、やはり回遊性というのまで行くかどうかですけれども、そこまでは一応頭としては考えていると思います。","voiceIndex":17,"id":"exchange-005"},{"speaker":"三上委員","kind":"意見","question":"どちらかというと、人の出入りのしやすい雰囲気づくりみたいなものは、それがどういうつくり方をするかによって、ものすごく変わってくるんですね、人の出入り。それはもう計画段階でそこまで煮詰まっているのかわかりませんけれども、できればそういうふうな雰囲気づくりというのは、最初からやるならやるということで、そういう方向でやってもらいたいと思います。","respondent":"太川総務課長","answer":"それともう一つは、先ほどちょっと申し上げましたけれども、このスタッキング案のところでもありますように、３階、４階にはいわゆる展示ホールということと、それからいろいろな周りの方たちが集まっていろいろ見ていただけるようなものも工夫していくということで、それを今。","voiceIndex":19,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"テナントの件ですけれども、レンタル方式といいますか、誘致による使用と、お金の得るときの割合、それで自家使用というんですか、それと、お金を人様に貸して賃料が取れる、これを見ていると、純然たるお客といいますか、準身内みたいな人も入っているものですから、その辺はどう意識しているのか、そのことをちょっと教えていただけますか。","respondent":"太川総務課長","answer":"いわゆる税金の部分ですけれども、向こうのほうからいただいている資料によりますと、まず特別区協議会の場合は、その辺はちょっと具体的に特定法人というのは、ちょっと私も調べ切れてないので申しわけないんですが、法人税につきましては課税されない見込みだけれども。","voiceIndex":21,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"後で、また聞いていただきたいと思います。それから、不動産の仕分けに関しても、税がどういうふうになっているのか。今わかりますか。それも後で教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"以前の説明の中に、この自治会館ビルの特徴の一つとして、インテリジェントビルとなるというお話があったんですが、ちょっとその部分でどういうふうになりそうなのかという話を教えていただけますか。","respondent":"太川総務課長","answer":"それで、現在入居予定のところにしましても、ＩＴ計画がどういうようになっているかということを全部聞きながら、そこの話を聞いている。今後それにつきまして、また実施設計の中に生かしていくということで、その辺につきましては十分考慮して進めていくという形です。","voiceIndex":24,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"ですから、逆に言うと、この簡単にそれぞれどこまでの需要があるのかわからないのですが、インテリジェント化しなくても、こういう団体は入ってくださったんじゃないかなという見方もある意味では、それぞれの団体がどこまでインテリジェント化を必要としているのかどうか、それぞれの団体である程度インテリジェンスをやられているだろうとは思うんですが、ハードといいますか。","respondent":"太川総務課長","answer":"そのように進んでいくものと考えています。そういう意味で、先ほど申しましたように、各団体にＩＴ計画を具体的にどういうふうに進めるのかを今ヒアリングしていて、それを実施計画に落としていくということで報告を受けておりますので、ご理解をいただければと思います。","voiceIndex":26,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"引き続きお聞きしますが、今、インテリジェント化といいますか、ＩＴ化というのは、どの分野でも必要になってくるんですが、インテリジェントビルとしてうたうところの、といいますか、うたっているだけの効果といいますか、より多くの対応できるような、通常のビルではなく、さらに付加価値のあるビルになっているだろうと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"今の区政会館も含めて、それから新しくこれについての、そのあたりの数字がつかめるかどうか。ですから、フロアで言うと、３フロア、正確には３.５フロアの部分は貸していくべきだというふうに今でも僕は思うんです。ただ、国保がこんなに要るのかなという思いもあるので、だから、５階から８階の半分までは、僕の意見では全て貸し出しができると。〔「要望ですか」と呼ぶ者あり〕返事だけでいいですよ。","respondent":"太川総務課長","answer":"それと、あと、お話がございました部分につきましては、現在準備室のほうでいろいろ検討している部分もありますので、今日お話しいただきました部分につきましては、準備室のほうに必ず私が伝えてまいりたいと考えていますので、よろしくお願いいたします。","voiceIndex":29,"id":"exchange-012"},{"speaker":"土井副委員長","kind":"質問","question":"要するに、これからの事務のさまざまな意味での合理化と言ってもいいのかどうか知りませんけれども、仕事の見直し等も含めて、ほんとうにそれだけのエリアが必要なのかということも積み上げないと、ただただ大きな空間を確保することによって、若干たりとも収益が上げられるような部分が減っていくということであってはならないと思いますので、その２３区の一部事務組合。","respondent":"太川総務課長","answer":"今お話しいただきました部分につきましても、私のほうで整理いたしまして、やはり準備室のほうにきちんと持ち帰って、検討に上げていただけるようにしてまいりたいと考えていますので、よろしくお願いいたします。","voiceIndex":31,"id":"exchange-013"},{"speaker":"土井副委員長","kind":"質問","question":"まさにそういうお願いをしたいと思いますが、その中でも、特に一等最初の２３区一部事務組合の課題、問題はどうなんでしょう。どのようにお考えでしょうか。","respondent":"本間総務部長","answer":"それから後段の、職員１人当たりの平米、これも当然こういうご時世で、この会館が大きくなったから、ここの勤務する職員だけ平米を余裕をもってという考えは全然持ってございません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"土井副委員長","kind":"質問","question":"私はそんなことを言っているつもりはないんですよ。１人当たりはそれでいいんですよ。問題は、何十人いるのか、２００人いるのか、３００人いるのかというのが、例えば一番最初に２３区の一部事務組合の、２００人も来るんだからこれだけ必要だと言って大ぶろしき広げたのが始まりなんですよ、大もとのこの自治会館の話を言っておけば。そこのところはどうなんですか。","respondent":"本間総務部長","answer":"まさにおっしゃるとおりでございまして、ご案内のとおり２団体の見直し等も行った上で、それの定数等も落として、その部分でこの新しいほうに人数も入るということで、もちろん冒頭遠大なことを述べていた点も当初はございましたけれども、その点につきましては。","voiceIndex":35,"id":"exchange-015"},{"speaker":"土井副委員長","kind":"質問","question":"今後ともその意味で、どうも区長や何かが入れかわり立ちかわりなものですから、なかなかチェック機能が働きにくくなる要素が非常に強いので、やっぱり我々は、特に品川区は、そういう中でも今までもチェックの役割を演じてきたはずですから、これからもそういう役割を我々も含めてやっていかなきゃいけないんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問・要望","question":"泊まるところが、こちら側が決められないという話になっちゃうと、今までの自分たちのつながりで、例年ここに行けるのにと、ところがそこへ泊まるわけにいかないのかという要望が出てきちゃうときはどうするのかということがあります。やってみた結果、もうとんでもなかったなんていう話にはしてもらいたくないんですよね。どうでしょうか。","respondent":"太川総務課長","answer":"その辺につきましては、私どもも対応方を要請してまいりたいと思います。","voiceIndex":42,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと細かいことなんですけれども、これは伊豆諸島、伊豆七島全部ですよね。今、噴煙が上がっているところも含めて、そのことだと思うんですけれども、私もよくわからないのですけれども、例えば八丈島なんかは一番端になるわけですね、実質上。要するに一番遠いですから。そこら辺のところはどうなのかなと、そこのところはわかりますか。","respondent":"太川総務課長","answer":"今委員のご質問の件につきまして、具体的に島の全体の観光客が落ち込んでいる状況というのはつかんではおりますけれども、ただ、そこの、特にどこを厚くという形よりも、今は先ほど申しましたように、伊豆諸島全体の支援をしていきたいという形でやってありますので。","voiceIndex":44,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"おそらく何回か水が出たということを、この東京都のいわゆるクイックプランですよね。それでやろうという。見通しとして、今まで何回か水が出た量というのは、大体これで吸収できそうという感じなんでしょうか。","respondent":"北村下水道河川課長","answer":"この事業の浸水対策の計画的な見通しにつきまして、ご説明申し上げます。この事業は、平成１１年、何回か水害があったわけですけれども、それらを対象にいたしまして浸水対策として緊急的に実施していくものです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"いずれにしても、５０ミリ対応というのは、もう東京都はその方向で、ここは終わっているということなんですけれども、５０ミリがいいか悪いかというのは、いろいろ普段からもうちょっと高い方がいいんだと言っているんですけれども、当面これでやってみて、要望ですけれども、これで集中豪雨的な傾向がかなり強くなっていますから、とにかくまた状況を見て、とにかくこれでやってみて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-020"},{"speaker":"北野委員","kind":"質問・要望","question":"６月１９日でしたかしら、近隣説明会がたしかあったと思うんですけれども、そのときの本音というんですか、地域の方々の反応を今わかったら教えていただきたいのですけれども。","respondent":"北村下水道河川課長","answer":"地元の方々２７名のご参加をいただきまして、全般的には工事実施上の騒音対策ですとか、細かな要望はございましたけれども、全体として、とにかく早く調整池をつくって、安全な状況をつくってほしいというような意見が多数を占めてございました。","voiceIndex":53,"id":"exchange-021"},{"speaker":"北野委員","kind":"質問・要望","question":"ほんとうにここの地域というのは、すり鉢状という形になっていて、高いところから水がおりてくるというので、期間は決まっていますけれども、ぜひ安全な工事を進めていただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"土井副委員長","kind":"質問","question":"工事のお話ではないんですけれども、前にももう既にどこかで説明されていると思いますが、あそこはゲートボールの方々がいつもお使いになっていたところなものですから、それがどうなって、どういう状況になっているのかというところは、お伝えいただければありがたいなと思います。","respondent":"北村下水道河川課長","answer":"１年間、公園全面閉鎖という形で工事をしますので、現在、下神明の駅前のところで、東京都建設局で道路確保予定地としてとっていた土地があります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"この契約といいますか、この工事全体の特徴の中で、今回がその１ということなんですが、次に調整池をつくる工事、それから配管する工事、そして復旧、また公園を元に戻す行為という四つに分かれるんですが、３番目の配管は、これはちょっと異質といいますか、違う内容になろうと思うんですけれども、その１、その２と、あと復旧工事、復旧工事の部分がどういう契約なのかちょっとわからないですが。","respondent":"西島経理課長","answer":"委員ご指摘のとおり、工事としては、その１、その２を一体というようなことも十分考えられますが、一つは、これは下水道局からの受託行為でございまして、まだその２の設計書ができ上がっていないというようなことがあります。","voiceIndex":58,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"まさにその部分をちょっと心配をしまして、分けることで経費が余分にかかるようなことのないように、ぜひそのような工法でご努力いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問・要望","question":"選管局長にお伺いいたします。都議選のときの不在者投票については、投票券は１枚です。そこらあたり、中央選管のほうの見解というのは出ているのかどうか、品川区として今どういうふうに考えていらっしゃるのか、不公平のないような形というものを極力取り入れた形にしていただきたいんですけれども、そこらあたりをちょっとお伺いしたい。","respondent":"木下選挙管理委員会事務局長","answer":"投票所におきましても、候補者名、または政党名をお書きくださいという形でご案内をする予定ですけれども、いわゆる氏名等掲示につきましては、法律上のものはかなり大きいものになりまして、それこそ１ｍ以上の大きいものを張るわけですが。","voiceIndex":67,"id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"今の続きなんですけれども、今回、選挙区と比例区と、当然投票用紙が色が違うと思うんですね。よく言われることは、自分では最初に思って行っても、あそこの現場に行くと、どっちの色が先だったかと、これさえわからなくなってしまうという声があるんです。例えば黄色が１だとか、ブルーが２だとかというふうに数字をやって、その順番で来た人が書くという、そういう程度の案内というのはできないんですか。","respondent":"木下選挙管理委員会事務局長","answer":"やはり事前にお渡しをするときの説明ですね、この部分についても、やはり年配の方が多うありますから、その点については、丁寧にご説明するように、担当する職員とあと業務委託もしておりますので、その部分については徹底をさせて。","voiceIndex":69,"id":"exchange-027"},{"speaker":"中島委員","kind":"意見","question":"説明は多分丁寧にしていただけると思うんですが、何分にも年配の方というのは、説明を聞いた、私もそういうことはあるんですけれども、３歩歩くと忘れてしまって、そういう傾向があるので、その色が、黄色が１番なんだ、白が２番なんだと、その程度の掲示なら、してあげるほうが親切ではないかなと思うんですけれども。","respondent":"木下選挙管理委員会事務局長","answer":"投票用紙についても、そういう形で色を分けて、氏名掲示も同じ色で分けますから、その色の中で確認をしていただくということと、あとはやはり従事者のほうのご説明やご案内を適切に行っていくということが重要かというふうに思っております。","voiceIndex":71,"id":"exchange-028"},{"speaker":"中島委員","kind":"質問","question":"ですから、黄色が１と書いてあったら、ああ、私の選んだあの人は黄色に書けばいいんだなと、こういうふうに最初に書けばいいんだなとか、こういうふうに１番、２番と、色で覚えるというのは、とても高齢者には難しいとおっしゃるんですね。でも、最初だとか後だとかというのは覚えやすいと、こういうふうに、こういう声も聞いているんですけれども、いかがでしょうか。","respondent":"木下選挙管理委員会事務局長","answer":"ちょっと検討はさせていただきたいと思いますけれども、いずれにしても、やはり基本的にはご案内と、それから色の部分で適切に対応していくということを基本にしながら、さらに間違いがない方法がほかに考えられないかどうか、それは検討させていただきたいと思います。","voiceIndex":73,"id":"exchange-029"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。それで、１人、２人じゃなくて、多くの高齢者の方に接するたびに、そのことを言われるものですから、ぜひ親切な対応、人手が少ない中で大変だと思うんですが、お願いしたいということを要望させていただいて終わります。","respondent":"本多委員長","answer":"ほかになければ、その他を終了いたします。以上で本日の予定はすべて終了いたしました。これをもちまして、総務委員会を終了いたします。ご苦労さまでした。","voiceIndex":75,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1552#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":30173,"voices":76}},{"id":"h13-20010704-13","meetingId":"h13-cm07","date":"2001年7月4日","dateIso":"2001-07-04","committee":"清掃・リサイクル特別委員会","time":"午前１０時１５分～午後２時１５分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"管理執行業務ということで、1)のごみの処理業許可と書いてありますけど、東京二十三区清掃協議会は２３区の収集・運搬・処理に関することだけだと認識していたんですけど、処理業許可だから、例えば八潮に(株)高和というのができましたよね、ああいう民間の処理施設については、全然ここの分掌とは関係ないものだということで、ちょっとその辺の確認と、ああいう部分の処理業の許可というのは、改めて。","respondent":"中山清掃リサイクル課長","answer":"ちょっと余談ですが、一部事務組合というのは、いわゆる清掃工場であるとか、きょうの視察の中でご説明した、区が運営している中継所から持って行く京浜島の不燃ごみ処理施設といったような、２３区の中でまだ各区に整備されていないようなもの。","voiceIndex":7,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"仕組みはわかりましたし、中身もわかりました。今までどうなっていたのか、そしてどうなるのか。具体的に一次処理、二次処理のコンポスト化等は、どこのだれが、どういう形で行うのか、市場に通すと言っても、どういう形で市場に流せるのか、品川ブランドで出てくるのかというようなことがわかりましたら、教えてください。","respondent":"中山清掃リサイクル課長","answer":"逆にそうなってくると、そこの部分のものを区が買い取って、売れるかどうか責任を取るという部分も出てまいりますので、基本的には、市場で販売するということで、ブランドで持ってくることはございませんが、今、考えてありますのは、やはり学校等からのリサイクル物ですので。","voiceIndex":15,"id":"exchange-002"},{"speaker":"土井委員","kind":"意見","question":"わかりました。これに係わる処理費用、処理コストの負担分担はどういう形になっているのかということ。生ごみ処理機のある小中学校ですと、そこで一次処理ぐらいまで行われて、それが回収される。そこでもコストがかかっているんだろうと思いますけども、ここではどういうコストの関係になりますか。","respondent":"中山清掃リサイクル課長","answer":"実際にどういう額になってくるかですが、実は、今いわゆる過渡期にございまして、食品リサイクル法がこの４月から施行されました。","voiceIndex":17,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"具体的に、例えば、どこ以降、どれだけの分量があるのかわかりませんけども、それぞれ集めて処理をしていく、それに一体お幾らかかるんですかということになりますよね。したがって、回収運搬等の費用等を積算されていったんだとなるんでしょうから、具体的にこの事業においてかかるお金は、区は幾ら払うんですかということなんです。払わなくていいんですか。","respondent":"中山清掃リサイクル課長","answer":"最終的に払う料金は、実は単価契約になってまいります。先ほど申し上げました条例の料金というのが、具体的に言いますと、１kg当たり２８円５０銭ということで、品川区の廃棄物処理の条例で上限を定めております。","voiceIndex":19,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"今まではごみでぽんぽん捨てられていたものですから、まだ具体的に分量がどのぐらいあるのかというのはわからないのかもしれませんけど、大きく予測を立てて、大体何ｔぐらい出るということになると、仮に上限を適用すれば何円になるとか、初年度は期間が短いですけど、平年化するとこれぐらいかかるというのがわからないのかなと思って聞いたんですけど。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません、予算額の資料をお持ちするべきだったんですけども、ちょっと手元にございませんので、これにつきましては、また、予算書をもとに別途総額で組まれている予算については、ご説明申し上げます。","voiceIndex":21,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"去年は、まちの中で集合住宅で、今年は、これから夏場で、生ごみのモデル実施をやりますよね。今回の公の施設のところでは、一次処理までは品川区がかかわり、二次処理以降は業者がという説明に聞いたんですけども、回収と処理のところが、今までとどこまでどういうふうに同じなのか、ちょっと改めてもう１回確認したい。ですから、今までのところの質問を教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"説明の仕方が不十分であったかと思います。申し訳ございません。基本的な処理の仕方は、昨年度、あるいは、今年度行う生ごみ際資源化のモデル事業と同様です。","voiceIndex":23,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"わかりました。ですから、モデル実施という枠を超えて、もっと積極的にいろいろな分野で、一般品川区がやっているリサイクル事業として、生ごみもほんとうに本格的に指導していってもらいたいという思いの中で質問しているんです。そういうところで見たときに、このやり方というのはどのぐらいの可能性と考えていらっしゃるのか、その辺の見解を伺いたいんです。","respondent":"中山清掃リサイクル課長、野本環境清掃事業部長","answer":"ご質問の部分は、この次の報告事項としてご説明申し上げる生ごみ再資源モデル事業のほうとの絡みになっていようかと思うんですが、学校、保育園の生ごみ再資源化事業につきましては、昨年度やっているモデル事業の中でも。ちょっと補足しますと、食品リサイクルの場合で何が難しいかというと、出口の場合、コンポストで回すというのは、例えば、今帝国ホテルなんかはやりましたよね。","voiceIndex":25,"id":"exchange-007"},{"speaker":"北野委員","kind":"質問","question":"１校で１基だったのが、２基にしたりとかいうような形で増えたりはありますけれども。それともなければ、ほんとうに小中学校とか保育園で、コンポストを置いていくことが難しい環境というんですか、コンポストを置いたりすると、結構悪臭があったりして近隣に迷惑がかってしまうというような状況もあるので、そういうこととの兼ね合いなのか、それをちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"少なくとも、明らかに成分の問題がない学校については、リサイクルが図れるわけですけども、冒頭、申し上げたように、すべてを品川ブランドとして買い取って、例えば販売していくということについては、やはりいろいろな意味でのリスク、負担もあるということで、基本は。","voiceIndex":28,"id":"exchange-008"},{"speaker":"北野委員","kind":"質問・要望","question":"生ごみは、モデル化と同じような形ということですけれども、集めるのが週２回ですよね。そうすると、どういう状況でポリバケツの中に入れて置いておくんでしょうか。ポリバケツは、校舎の外に置き放しにしてしまうのか。生ごみというのは水切りが重要ですよね。そういうところでは、どういうふうに考えていらっしゃるのか、お聞きしたい。","respondent":"中山清掃リサイクル課長","answer":"学校については、９月以降ということですので、これから具体的な設置の場所だとか、業者にどこに取りに来るように指示をするかということの詰めをやってまいりますけど、保育園については、できるだけ、成分、あるいはそういう臭気の上でも問題ない場所を。","voiceIndex":30,"id":"exchange-009"},{"speaker":"北野委員","kind":"意見","question":"７月２日から保育園は始まっているということなので、次回、清掃・リサイクル特別委員会があるのが１カ月後ぐらいになるわけですので、短い経過ですけれども、どういうところに工夫されたかというような意見などがもしあったら、聞いていただいて、報告いただければありがたいと思います。すみません、委員長、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"教育委員会の判断に任せるという表現でいいのかどうかがちょっと疑問なんで、その辺。学校だって大きな学校と小さな学校とあると思うんですよね。そうすると、週３回行かなきゃいけない学校もあるだろうし、１回で済むような学校もあるだろう。その辺のところが、今、北野委員が言ったように、腐敗したり何かというものを、もう少し見ていくという考え方はできないんでしょうかね。","respondent":"中山清掃リサイクル課長","answer":"今回の実施についても、いろいろ現行の生ごみ処理機の状況というものを踏まえながら、当面、食品のリサイクルを進めていくという中では、設置してない場所について、まずこの方法を取っていって、全校をカバーするということでやっていく。","voiceIndex":33,"id":"exchange-011"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"というのは、例えば、この部分だけ新たに学校の中に取りに行かなければいけないとか、それがちょっと疑問だったんです。もし学校の中に入るのだと、９月だから、その時点で学校が施錠しているかどうかわからないけど、そういう問題とか、車を中に入れるとすると、安全性という問題がちょっと気になったんですが、その点には影響がなく、今までどおりかどうかの点だけを確認します。","respondent":"中山清掃リサイクル課長","answer":"生ごみと申しますけども、例えば、魚の骨については生ごみリサイクルができますけども、肉の骨については、実は処理機のほうに投入できないということがありますので、入れられるものとそうでないものを、現場のほうにそれぞれペーパーで説明しています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"北野委員","kind":"質問","question":"実施世帯が約５割の１５０％の見込みというのは、要するにやってもいいよという自発的な協力者を５割を見ていらっしゃるんですか。そこのところをちょっとお伺いします。","respondent":"中山清掃リサイクル課長","answer":"そういった意味では、持ちかけをして、協力をいただけるという意思表示をいただける世帯を約５割と見込んでいるです。","voiceIndex":42,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"ですから、収集自体も大変苦労があるところかなと思うので、もう１カ月切れているところで、今、整理されているというお話なんですが、大変かなと想像しながらなんですけれども、ここに、５から１０戸に１カ所ポリバケツを用意するということですが、大体どんなような状況になるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、そういうことで、場所については、支障のない場所としか申し上げられませんけれども、いわゆる燃えるごみを出す同じ日に回収に回りますので、このバケツの中に、いわゆる生ごみ以外のものが入れられることがないようにということを主眼に。","voiceIndex":44,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、５から１０戸に対して一つですから、まちの方々が、あそこの家の範囲までここにしましょうとか決めて区と調整をするわけですよね。その辺の話が、どこまで今進んでいるのかというところを、もしわかれば教えていただきたいんですが。","respondent":"中山清掃リサイクル課長","answer":"該当エリアだけでなく、そういう何らかの影響といいますか、目につくようなところにつきましては、該当世帯への説明とあわせてやっていかなければいけないとは認識しております。","voiceIndex":46,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"最後に。さっきも言いましたけど、１カ月を切った中での準備と、周知徹底と、体制をつくっていく、また回収ルートを決めていくわけですから、事務作業だけでも大変だなと思うんですけど、大変な中でも、やっぱりこれをやっていくことが、ごみの問題、自覚につながっていくんだと思うので、ぜひ頑張ってやっていただきたいということを、大いに期待して見ていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"旗の台で一つつくっていただきまして、ありがとうあります。さっきあったように、魚の骨はいいけど、肉の骨はだめだとか、何がいいとか、悪いとか。これはこれで拠点回収でいろいろ出てきているんですけども、先ほどの生ごみのモデル回収をやるについても、その地域の人には勉強してもらうけども、あらかじめ知っておけば、また取り組みやすいと思うんで、そんな努力もまた機会があったらお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"拠点回収の場所が増えてよかったなと思うのと、あとエコボックスがあったり、週の資源回収とか、選択肢がいろいろあることはすごくいいことだなと思うんですが、いま一つ、リサイクルをしていこうという意識を持っていただくに当たって、回収されたものがどうなっていくのかというのが、いま一つわからない。古着が、ここの回収の後に、どういうふうに利用されているのか、ちょっと教えていただきたい。","respondent":"中山清掃リサイクル課長","answer":"確かに、先ほどの生ごみ等でもお話しがあったわけですけども、回収にご協力いただいた方に、それがどのように生かされていくのかというのをきちんとお伝え、フィードバックしていくということについては、今後の広報のあり様等の中でも。","voiceIndex":55,"id":"exchange-018"},{"speaker":"北野委員","kind":"質問","question":"廃棄物減量推進審議会の委員の公募が終わりましたよね。もし、今の現状を教えていただけたらと思うんです。","respondent":"中山清掃リサイクル課長","answer":"廃棄物減量推進審議会の公募委員ですけども、募集を、６月１５日までということで行いました。公募委員２名ということで、広報「しながわ」で募集させていただきましたけども、４名の応募がございました。","voiceIndex":62,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"その区は、もうつくりませんと明らかに言っているわけなんで、これを待っていたら、いつまでたっても一部事務組合云々というのが解散できないだろうと思うんで、そういったことを、うちの品川区議会としては、どういうふうに方向性をつくっていくんだというようなことを、皆さんでお考えを整理して、組合のほうで議長が出ていますので、そっちへいろいろ要望を持っていきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5642#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":23148,"voices":67}},{"id":"h13-20010705-16","meetingId":"h13-cm07","date":"2001年7月5日","dateIso":"2001-07-05","committee":"街づくり特別委員会","time":"午前１０時１４分～午後 ３時５１分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"意見","question":"これがまた４年も延びるとなると、これまでのことはどうするのか。それの対応としてアンダーパスという話なんだから、それまでの４年間の対応策って多分そんなにあるはずがない。地元の人は、多分ここら辺の事情はみんな知っている話をまたされて、ただ４年だというのは、受け入れるのに非常に難しい話じゃないのかなと思うんですが、ここら辺のことをどうお考えになっているかというのを４点目。","respondent":"南雲都市開発課長","answer":"ということで、これについてもっと早くわかっていたんじゃないかというお話もあるとは思いますが、これもいろいろ事業を行っていく中で、こういう実施に伴って何度か工程を見直すといういきさつの中で、今回はっきり延期されるというか。","voiceIndex":6,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"みんな我慢していたわけですよね。これは警察も含んでいる話ですよ。そのわかっている段階で本当に遅れないんですか、工期が遅れなくて大丈夫なんですかと、働きかけはしてほしい。それなのに、何でこの後に及んでこういう理由で４年も遅れるというところが、それで本年度になったから言うんですというのは、最初の設定のときの意識づけがどこから来ているんですかという話ですよね。","respondent":"岩田管理工事課長","answer":"ただ、実際ふたをあけてみますと４年ということで、ここにいろいろもろもろ公式理由は述べられておりますけれども、実際のところは、あそこに掘ったところ、東京電力等の高圧ケーブルがかなりでかいのがありまして。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"これで最後にしますけれども、今のお話は大切な話で、もう本当に今後のこと、地元の方は具体的な対策がなくて、アンダーパスが抜けるまで我慢してください、これはもちろん警察まで含んだ話でそういう話になっているわけですから、今後の対策を、この委員会が終わったらすぐ地元に話してくださるという話だけれども、その話し方も、町会長だけでいいのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003","title":"町会・自治会支援"},{"speaker":"本田委員","kind":"質問","question":"今現在でもこの商店街の旧東海道、大変車の問題はみんな頭を抱えているわけですから、それで、１５年度にはこの東口の開発が一応竣工するということで、５５％減るとはいえ、何千台という車が、多分増えるんだろうと思うんですが、ここもどうも通り抜けに来るということになると、これは大変なことになりますね。その辺はいかがでしょうか。","respondent":"南雲都市開発課長","answer":"今後の区画整理事業の事業時期の延期の都市計画の手続を鉄建公団のほうでするということで、それに伴って、この遅れるということについて近隣の皆さんにお知らせするということですが、それとは別個にどんな対策があるかについては、早急に具体的な案を鉄建公団と。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"そうすると、今の地域の方に説明するというのは、都市計画上延期手続をするというふうなことを言っているんですか。こういう具体的に４年間延期することによって、通り抜けの対策についてはいろいろとしなくちゃならないというのは、それはもっと後の話に分けて考えているんですか。地元への説明というのは、契約上のことで手続上必要だという意味でのことですか。ちょっとそこのところ。","respondent":"南雲都市開発課長","answer":"本日これが終わりました後、速やかな時期にこの鉄建公団のほうでこの延長の話についてはそれぞれ町会長を通じてご説明を行うということで、さらにこの旧東海道の通り抜けの対策については、具体的な案をまとめるのになかなか時間がかかりまして。","voiceIndex":13,"id":"exchange-005"},{"speaker":"本田委員","kind":"質問・要望","question":"当委員会にも対策案については速やかに、今日はできないことですが、速やかに報告をしていただきたい。住民の皆さんから当然我々も説明を求められますので、これまでもいろいろ起きているわけですから、それが今の話だけでは全然もう話にならないですよね。ですから、当委員会に対策案、どういう案を検討しているのか、されたのか、速やかに報告していただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田委員","kind":"確認","question":"ちょっと１点だけ。地元の説明なんですが、鉄建公団が行うと。私が質問したときに、もちろん行政側も一緒に行って、警察も含めて、ちゃんと説明会を行うという理解をしていたんだけれども、今のお話だと、鉄建公団と関係者で、区は入っていないの。地元の説明には入っているんでしょう。そこの確認だけ。","respondent":"南雲都市開発課長","answer":"この事業が延期されるということについては、この区画整理事業者であります鉄建公団のほうで戸別にまずお伺いして、その後説明会等の集会でも行うということになります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田委員","kind":"確認","question":"そうすると、そのままちょっと確認だけれども、それは区も警察も、変な話、鉄建公団も含めて、説明会のときは必ず参加をするという理解でよろしいかだけ確認を。遅れるというのは鉄建公団が話をするのはいいと思う。それは３者でちゃんと打ち合わせをして、その案が出た場合には、住民への説明をちゃんと行うということで理解をしていいのかどうか。","respondent":"南雲都市開発課長","answer":"今後につきましては、関係者、事業者、品川区と警察、それから鉄建公団、３者で特に区と鉄建公団で責任を持って、地元の方にもご協力いただいて、ご理解をいただきたいというふうに考えてあります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"鉄建公団も品川区も。品川区もかかわっているところでありますから、品川区の場合のかかる部分も含めて、それから鉄建公団に対する対応も含めて、４年をできるだけ短くする方法とか、それから、住民の皆さんに説明会をやるとおっしゃったけれども、必ずしも町会長に対して説明するということではなくて、もっと情報を公開してきたらどうでしょうか。","respondent":"南雲都市開発課長","answer":"説明の仕方ですが、これは町会長に話して終わりということではなくて、町会長を含めて、どのような説明の仕方を言ったらいいのかということを協議させていただいて、それで具体的にどうやって説明するか、決めていきたいです。","voiceIndex":20,"id":"exchange-009","title":"町会・自治会支援"},{"speaker":"伊藤副委員長","kind":"確認","question":"石田委員も先ほど言っていましたけれども、やっぱり品川区民の皆さん、近隣に住んでいる皆さんは、４年間少なくともそういう状況があるわけですから、もうちょっと踏み込んで、その４年間を短くするのはもちろんですけれども、例えばこちらのほうから鉄建公団に向かって物を言っていくとか、設計変更の仕方とか、技術的な部分いろいろあるでしょう。そういうふうな気持ちがあるんですか。","respondent":"中谷まちづくり事業部長","answer":"ただ、先ほどお話ししました今回の工事が、これは１５万ボルトのケーブルですとか光ケーブルとか、それを何か少しずつ１本１本移設しなきゃいけないというような工事ですので、これは停電を長時間させることもできないということで。","voiceIndex":22,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"そういうのというのは何かの約束事というのはあるんでしょうか。今回はどういう、鉄建公団のほうの好意で報告があったのか、そういう約束事というのはどういうふうになっているんでしょうか。","respondent":"南雲都市開発課長","answer":"この事業が初期の事業区間の中で完成しないということは、事業者のほうではっきりしてきたということで、その区画整理事業を行っております品川区とか港区の人たちに対しても、事業者の方から都市計画の変更についての手続を行うからという申し入れがあったですので。","voiceIndex":24,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"でも、これを見れば、事業期間というのは、このアンダーパスについては平成９年からなんだと。当初の計画では。それが変更した後も平成１１年ですよね。だから、私の感覚からいけば、去年は平成１２年ですから、もう既に鉄建公団のところではわかっていた話だと思うんですよね。そういうことではないんでしょうか。そのときは、まだ平成１５年にはアンダーパスはできるという見通しが立っていたでしょうか。","respondent":"岩田管理工事課長","answer":"したがって、彼らは法に基づく事業を行うに当たって、我々品川区とか東京都に対しては、都市計画上の許認可権者としての相手として我々に手続を持ってまいります。一方、道路管理者である品川区に対しては、道路を使用する道路占有者としての立場でも調整にまいります。","voiceIndex":26,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"地域住民の方は非常に注目されているということですから、やっぱり計画変更したらどうするかというのは、もし可能であれば、どういう法律もあろうかと思うんですけれども、ちゃんと約束してもらった、変更というのはやっぱりいろんな意味であり得ますからね。そこのところは、ぜひ鉄建公団のほうとも話をしてもらって、うまくやっていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"沢田委員長","kind":"質問・要望","question":"４年も延びてしまうと、そのペナルティーの痛みを受けるのは地域住民であり商店街の人たちだ。いいものがあればぜひやってほしいと思うんだけれども、やっぱり副委員長が言ったように、工事の短縮の方向での努力を、ぜひ皆さんからそれぞれ出ましたので、区としても強く言っていただきたいなと、このことだけ言って、とりあえずこの報告は終えてよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"},{"speaker":"石田委員","kind":"質問","question":"じゃあ、私が。変なことを伺うようですが、今の話の中で、この不燃化促進、密集市街地も含めて、今おっしゃったような中で、一つは対症療法的に出てきたものがあるんではないのかなという気がある。そうすると、おのずと、例えば職住接近がいいのかという話の問題の中で、例えば千代田区なんかは昼間人口が３３０万人もいるんだと。そのとき、これを使えない。それじゃ、これが本当のまちづくりなの。","respondent":"浜脇住環境整備課長","answer":"それが今、検討委員会でやっているから言いますけれども、そこまでではなくて、どっちかというと、街の中でやはりご協力いただける地区において、そういった検討を普段やって、これからはそういうことで対症療法をすみませんけれども。","voiceIndex":37,"id":"exchange-015"},{"speaker":"石田委員","kind":"意見","question":"そこら辺のことを、これはこういう委員会の中で、それがいい悪いという判断の中でも、勉強するなり、そういう形のものを、どういう形で、先ほど言った用途地域まで含めるのかどうかは別としても、赤くすれば済む話なのか、そういうところまで含んだものを、大変な勉強量になる可能性もあるけれども、そういうものの中で当委員会として、さっき言った研究会みたいなものがないというお話だったけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問","question":"ちょっと聞きたいんですけれども、これは見開きの密集住宅市街地整備促進事業のご案内という中で、７ページ、荏原北地区、これは地元だから見てすぐわかるんでけれども、この部分でちょっとお尋ねしたいんですけれども、真ん中に確かに放射２号線という計画路線がずっと走っていますね。それで、それの先端のほうに荏原第一中学校、このところの右端の生活圏道路６ｍ、これはこの前完成していますよね。","respondent":"浜脇住環境整備課長","answer":"ですから、これは私が入って、平成６年、７年に２年間かけて、地元の方、１０回ぐらいでしょうか、協議会をやりましたし、説明会も３回ほどやりました。","voiceIndex":40,"id":"exchange-017"},{"speaker":"横山委員","kind":"意見","question":"今、私が言ったように、星薬科大学のほうの横なんていうのは、大学ができて、あの周辺に農道の整備や何かで、この上は多少広がる部分はあるんだけれども、とても６ｍなんてとれないし、星薬科大学の縦に走っている線なんていうのは、今、道路すらないようなところだよね、これ。大体、地区の整備とか、そういった考え方で進められているということがわかりましたので、結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"ですから、そのことについては、品川区ではどういうふうに考えていく必要があるかということをお聞かせいただきたい。それから、こういうふうな事業をいつも見ていて思うのは、行政評価ですよ。だけれど、実際例えばこの表の５ページに、平成元年度から平成１４年度に旗の台・中延地区の整備計画がありますけれども、本当に１７年間にそれができると思っているんですか。","respondent":"浜脇住環境整備課長","answer":"そういったのを足しますと、現実的には形として上がりませんから、行政評価上での成果を問われることは、もう悪い意味で問われるのかなというふうに考えておりまして、この辺は、やっぱりこの事業の性格といいますか、性質といいますか、吟味して洗っていってやるというのが。","voiceIndex":43,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"実際に、こういうふうに計画があるわけですから、このうち、大体一つ、二つぐらい重点を絞って、例えば３年間ぐらいである程度の基礎を固めていくとか、これは例えば旗の台・中延地区だと１７年の計画があるわけですから、これの中で、例えば区切って３年ごとにはお願いしていこうとか、６年にこうしていこう、平成１７年のときにはできるだけ事業を完成していこうというふうに、何と言ったらいいんですか。","respondent":"浜脇住環境整備課長、山室住宅指導担当部長、沢田委員長","answer":"私ごときが政策の話をするのはちょっとおこがましいですけれども、この密集事業のことで言えば、職員がある程度いまして、この旗の台・中延地区には。ですから、今副委員長もご指摘のとおり、我が区ではもう３地区にわたって密集事業を展開しているわけですが、その３地区の中で。午前中からかなり長時間になっているんですが、一応午後２時間たちましたので、ここで１０分ほど休憩をして。","voiceIndex":45,"id":"exchange-020"},{"speaker":"藤田副委員長","kind":"質問","question":"その前に、私ちょっといいですか。質問だけちょっと。これは課長はよくわかっていらっしゃるはずと思うんですけれども、このパンフレットの５番目の旗の台・中延地区ですね。この中に私は住んでいるわけで、非常によくわかっているつもりなんですが、この旗台小学校南側のこの地区ですね。その辺だけちょっとお考えを伺っておきたいと思います。","respondent":"浜脇住環境整備課長","answer":"中にはちょっと経費が小さい方がいらっしゃるそうなので、その方も今後の生活再建等も検討しながら入らないと、やはり失礼かなと思いますので、若干のそういった生活再建策も含めた形で今後入ってまいりたいと、実現するかしないかはちょっとお約束できませんけれども、しかし。","voiceIndex":49,"id":"exchange-021"},{"speaker":"藤田委員","kind":"質問・要望","question":"１年前に、この旗台小学校の小の下の南側で火事がありましたね。ですから、今おっしゃるように、１軒１軒、皆さんやっぱり考え方が違いますから、よく区のほうで丁寧に誘導策といいますか、ぜひやってもらいたいと思いますね。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"ですから、今後、今日はこの程度なんでしょうけれども、抱えている問題、事業と地区の中で抱えている問題を勉強させていただきながら、どういう格好でどうしていくのか、別の改善手法がないのか、また、新しい手法をつくっていくためには、どういう問題提起を議会サイドからはしていけばいいのか、またいろいろ構造改革という国の動きの中で。","respondent":"浜脇住環境整備課長","answer":"今日は４事業の差といいますか、こんなふうな使い方をしているんですということだけをお知らせした感じですので、もし委員がおっしゃるとおり、密集住宅市街地整備促進事業について、委員のご理解されているところを言ってもらえば、この事業におけるところの問題点等は。","voiceIndex":52,"id":"exchange-023"},{"speaker":"本田委員","kind":"意見","question":"国や都からの補助金もつぎ込んだということで、到達点はここまで来ているというようなこともやっぱり一つの行政評価になってくるわけですけれども、そういう点も明らかにしながら、さらに進めていくためにはどうすればいいのかということを、私としては論議できればなお結構だなというふうに思っておりますので、今後の進め方の一つ参考にしていただければというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"この事務事業概要で見ると、これは平成１２年度までですけれども、戸越１・２丁目地区では５棟竣工、１棟事業中ということなんですけれども、先ほど不燃化領域率という言葉が出てきたんですけれども、実際に例えばこの戸越１・２丁目地区のところで言うと、当初どういう目標があって、それでどのぐらいの到達なのか、どんな感じなんですか。ちょっと具体性のあることなんですけれども。","respondent":"浜脇住環境整備課長","answer":"戸越のほうですけれども、戸越が最初が２９.５％で、現在が３８.８％。荏原北地区ですけれども、導入時が４２％で、現在が４２.８％。実は荏原北地区は若干多少導入時が早かったものですから、不燃領域率の目標は４５％にしています。","voiceIndex":56,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"戸越１・２丁目地区のは、スタート地点が２９.５％で、現在が３０.８１％で、目標としては４０％ですか。もう一つ、ちょっと気になったんですけれども、例えば戸越１・２丁目地区のところですと、都市計画道路補助２１号線というのがありますよね。この都市計画道路と今の整備計画というのはどういうふうな位置関係にあるのか。","respondent":"浜脇住環境整備課長、沢田委員長","answer":"ですから、これは例えばこの都市計画道路事業内で、例えば土地を買うとか、建て替えがあったときは、それは事業区域内だったわけです。というふうに都市計画道路はこの事業では整理ができないことになってあります。今後の進め方、それぞれ今質疑の中にも幾つか意見が出たんですが、２日前に正副委員長と、それから担当部長、課長に集まっていただいて、説明を受け、今後どうするかということを論議したんですが、正副で決めるというよりは。","voiceIndex":58,"id":"exchange-026"},{"speaker":"石田委員","kind":"質問・要望","question":"今、ここに四つのものを出していただいた。今のこの密集市街地の現状、当初例えば旗の台で２４.７％、現在で２５.５％だと、この数字も普通に建て替えている人もいて、建て替えている人は、今度は防災でこの中に含まれているもので、この事業を打ったために、この２５.５％はどれだけ活躍しているかというのは、中が見えないわけね。そういうものを整理することが、課題に対してできるのかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-027"},{"speaker":"石田委員","kind":"意見","question":"そのぶつかるとされる、今までこれがだから１００％容積率が使えないとか、いろんな原因があるはずなんですね、道路でセットバックで家がなくなっちゃうとか、いろんな問題の中で、ここをこうやったらこれがどういうふうにクリアできる、自分が建てるときに、１００％を例えばお金を全部出さなくていいということはないけれども、ある程度の生活設計ができるような絵がかけるところまで話が持っていければ。","respondent":"浜脇住環境整備課長","answer":"できれば、密集事業のほうと生活圏のほうで、そういう例を出していったらいいのかなと思っていますけれども、都市防災と都心共同とはちょっと若干法律という意味では違ってくるのかなと思っているんですけれども、要するに。","voiceIndex":65,"id":"exchange-028"},{"speaker":"石田委員","kind":"意見","question":"今のね、私もわかっていて言っているんですけれども、どうしてそれを言ったかというと、密集市街地はこの３カ所に限られてくるわけですよ。今言っているようなこと。面でとらえていくとなると。この三つにとらえていけば面なんです。だから、それも出していただければ、また面から点の問題も品川区としてあらわれるのではないのかなと思って言っていることでありますので、そういう意味です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどの課長のほうからいろいろ話を進めていると、最後にちょっとそれじゃだめだということで、とりやめになるケースもかなり多いのだということであれば、ちょっとそういう事例みたいなのも、典型的な事例なんかがわかれば、紹介していただければいいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-030"},{"speaker":"築舘委員","kind":"質問・要望","question":"だから、それはもちろん３カ所というのは大切なことなんですけれども、やはりそこで都心共同住宅供給事業というのは、それではそこだけではなくて、やっぱり全体の大井とか北品川とか、ほかの地域でも同じような老朽化していますような状況に対し、共同化して、建て替えまでできますよみたいなところの事業ですから、その入り方としては、委員長が言われるように、そこをしっかりやってよと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"},{"speaker":"横山委員","kind":"意見","question":"視察ってどういう形でやるの。現場に行って、ここはそういう家だと見てくるの。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-032"},{"speaker":"横山委員","kind":"意見","question":"細かい本当に……。だからね、ここは危ないんだよどうのこうのなんて言うと、とても何か、その辺の人を傷つけるようなことになるような。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-033"},{"speaker":"川西委員","kind":"質問","question":"視察については、今横山委員がおっしゃるように、やっぱりいろいろ難しさがある。大体、地域の人は割合感じている。それから、先ほどから意見が出ているように、今後のせっかく指定されたんだから、促進をしていくということの問題点を明らかにしていく必要があるという、それは２点出されていますよね。ですから、委員会運営で今後そのようなことを取り上げてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-034"},{"speaker":"藤田委員","kind":"質問","question":"先ほど横山委員がおっしゃったように、やはり先ほども言いましたけれども、一人通るのがやっとの通路なんですよね。そこにもうびっしり住んでいらっしゃる。ですから、やり方として、その辺をちょっと。公道であればいいんでしょうけれども、やはりそういうところに入っていきますと。","respondent":"浜脇住環境整備課長","answer":"でも、写真を撮ったりするのも、何か人をはばかってやっているようなところもありますので。でも、一応様子がわかるような資料が一通りありますれば、それをちょっと使って、何々地区はこんなところでと。","voiceIndex":77,"id":"exchange-035"},{"speaker":"横山委員","kind":"意見","question":"その態度を言うよりも、実際にそうしたら災害に強いまちづくりという部分を含んでやっていいと思うのね。要するに、ここに協力してあげようと言ったって、区のほうが、じゃあ、それ全部買い取ってあげましょうという、そういう制度にもなっていないし、そして、調べれば調べるほど難しくなっちゃって、促進ができない部分が逆にだんだんわかってきちゃうと思うのね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-036"},{"speaker":"石田委員","kind":"質問","question":"それをだから、さっき川西委員も言ったけれども、その中にお金なのか、考え方なのか、そこまで入れて、ちょっと教えてよという話があったけれども、そういうところまで含んだものを資料づくりをまずしていただいて、それで、先ほど言ったように見るのも一つで、とっかかりとしては、そこから入っていくのが一番いい方法でしょうけれども、そこまで考えて物事をやっていっても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-037"},{"speaker":"本田委員","kind":"質問","question":"というお話があって、１８０haぐらいの事業区域面積ですよね。２３区もずらっと各区も入っておりますね。案外抱えている問題が似たような形で促進が、抵抗を受けたようなところもあったんですけれども、そういう意味では、区のレベルで取り組むのと、都が掌握しているんじゃないですか、これは。そういう何か生活圏の促進のところでないんですか、都のほうとの連携の中で。","respondent":"浜脇住環境整備課長、田平建築課長、山室住宅指導担当部長","answer":"なかなかそういう資料というのは、各年でどのくらいお金が補助金が行って、あったかぐらいのことは掌握できますけれども、それをまとめて管理して。すみません、私、建築基準法の立場として、先ほど来いろいろな委員方のご意見をちょうだいいたしまして、２項道路だとか建築基準法の斜線制限だとか。重ね重ねの補足で申しわけありませんが、今日は委員の方々のご意見をお伺いして、都のほうとも調整して、どういった資料がとりあえずできるのか。","voiceIndex":88,"id":"exchange-038"},{"speaker":"横山委員","kind":"意見","question":"問題としても持ち方なんだけれども、密集市街地というお題目があって、これを促進していこうということで、そういった勉強をしていくのか、要するに促進がままならない、とどまっているから、そこら辺の現状と、それを踏まえてもっとこれを進めていくんだというとらえ方もあるし、ちょっと持ち方というのは難しいんだなと思うんだけれども。","respondent":"沢田委員長、南雲都市開発課長","answer":"今日、いろんな貴重な意見が出されたので、密集住宅市街地の整備に関することということですので。もう一つありますので。報告事項の(2)の密集市街地の整備については、これをもって終了といたします。どうもありがとうございました。大きな２項目のその他に移りたいと思います。その他の(1)の西大井駅前南地区の再開発事業事故繰越しについて、説明を願います。この西大井南地区につきましては、平成１２年度に予定しておりました事業について、平成１２年度中に完了しなかったです。","voiceIndex":92,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6210#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":53121,"voices":102}},{"id":"h13-20010706-14","meetingId":"h13-cm07","date":"2001年7月6日","dateIso":"2001-07-06","committee":"行財政改革特別委員会","time":"午前１０時１２分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"二つありまして、一つは、２０２本の本数の項目というか、事業名をぜひお願いしたいと思うんですけれども、それは３月の公表前に議会にいただきたいと思うんですけれども、それはいかがでしょうか。それから、もう一つは、公表の関係ですけれども、公表というのは、どういうふうなイメージというんでしょうか。二つお尋ねします。","respondent":"榎本行財政改革担当課長","answer":"３月の公表というのは、区民への公表ということで、今のところ、前回の資料８の冊子の中で説明責任と公表というところで設けているとおり、分かりやすく公表するということで、広報紙ですとか、インターネットですとか、多様なメディアを用いて公表する。","voiceIndex":6,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"大枠がまとまった段階というのは、いつ頃になるんでしょうか。だから、当然公表の前になるんでしょうけれども、どのくらいの時期に、少なくとも項目がいただけるかどうか、それを知りたいところなんです。","respondent":"榎本行財政改革担当課長","answer":"公表につきましては、最終的に事業部経営会議に第二次評価をかけるという形を予定しておりますので、その後なるべく早い段階で当委員会のほうへ報告をしたいと思います。","voiceIndex":8,"id":"exchange-002"},{"speaker":"辻副委員長","kind":"意見","question":"２０２本、あるいは事業の総数で７０６本あるんですが、ちなみに、区議会事務局で予算事務事業数で６事業あるわけですが、この６事業というのは具体的にどんなものか。イメージとして出していただければと思います。","respondent":"榎本行財政改革担当課長","answer":"６本の事業名ですが、議員報酬等、議会運営費、委員会活動費、図書室運営費、区議会だより発行費、事務経費という６本の事務事業になっております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"辻副委員長","kind":"質問","question":"事務事業というのは大体そういうイメージですか。我々が捉えている予算で取っている部分について、今後どのようにして評価シートをつくっていくのかというのは、実際具体的には事務局長を初め皆さんでやる。我々も今回の２０２本の事業の中でやっていく。委員会の運営を深めていったときに、なるほど、そういう切り口、そういう評価の観点だというのがいろいろ出てくるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"どういう指定の仕方か。というのは、評価を出しやすい事業を選別されているのか、もしくは、例えば区民のほうから知りたい部分というんでしょうか、何をしたかというようなものではなくて、結果重視というんでしょうか、成果重視という部分の、区民から見て、見たいもの、聞きたいもの、そういった選定になっているのかどうか、どのような仕組みになっているのかお聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"今年度選定しなかったものについては、来年やるという形になっておりますので、今年か、来年かで必ずやるような形での進め方をしております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"辻副委員長","kind":"質問","question":"先ほど６事業をご説明いただいたんだけれども、今回２つの事業をやるんですね。それはどれになるんですか。","respondent":"榎本行財政改革担当課長","answer":"区議会事務局につきましては、区議会だより発行費と、事務経費の２件を実施いたします。","voiceIndex":15,"id":"exchange-006"},{"speaker":"辻副委員長","kind":"質問","question":"区議会だよりの発行は、例えば広報のほうで、広報しながわの発行というところに入っていますか。今回は試行的な部分があると思うんです。それから、広報しながわも同じような一つの事業ですね。区から見れば。その辺はどうですか。今回の試行的な部分であっても、非常に特徴的に出てくるような事業かなという感じがしますけれども、それはいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"広報とかにつきましては、区政資料等発行費ということで、そういう事務事業がありまして、それを対象に選んでおりますので、広報は入っているはずなんですけれども、合わせるような形で、なるべく進めております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"今年度の対象事業数を２０２本に絞り込んだというのは、どういう基準ですか。何か問題点がありそうだというような予測のもとに、あるいは各セクションごとに今年度の対象事業というものを挙げてもらって、集約したということなのか。あるいはそうではなくて、企画部あたりから、これとこれとこれですよという、そういうことになったんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"ただ、事業部につきましては、各事業部の判断がありますので、各事業部の中で問題がありそうな事業も入っていますし、ある程度評価をしてもらいたい事業ですとか、これからどういう方向に進んでいったらいいのか迷っているような事業とか、そういうものも入っておりますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"この結果がどういうものになるかということが一番注目に値して、その結果に基づいてどういうふうな見直しだとか、あるいは改善が行われるのかということがとても大事なことだというふうに思うんです。事業部の選定した、あるいは企画部が選定した、そういう面から見ると、各事業は、やや再検討の余地ありというか、そういうふうな期待感を持っているんですか。","respondent":"榎本行財政改革担当課長","answer":"ある程度事業の中身の部分で、実施計画的な事業につきましては、企画部のほうでかなり進行管理ですとか事業の中身をつかんでいることになるんですが、経常事業につきましては、１０年とか、５年とか長い間かけてきた事業については。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鶴委員","kind":"確認","question":"確認ですけれども、特定事件の調査として、行財政改革特別委員会は行政評価に関することということを明確にうたったわけですが、特別委員会と、行政サイドの今回の一連の見直しというか、特別委員会との兼ね合いはどういうふうに考えていらっしゃるわけですか。私たちの意見を尊重するということなのか、積極的に聞くということなのか、ただ報告だけに終わるということなのか。","respondent":"榎本行財政改革担当課長、中尾根企画部長","answer":"事務事業評価につきましては、区のほうの部長、課長、執行部側の自己点検という形で今進めておりますので、あくまでも自己点検結果という形でのご報告という形になると思われます。したがいまして、常任委員会、特別委員会との関係は、従来どおり行革の取り組みの関係というのが基本でやってまいりますので、第一義的にはここの委員会にすべてを報告させていただいて。","voiceIndex":23,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"大きく２点お伺いしたいんですが、先ほど来少し出ておりますが、まず１点目は、企画部選定のものと事業部選定の違いというところですが、最初に企画部が選定した事業８５本を各事業部に提示して、それ以外のものとして各事業部が選定をしたのか、２０２本ということで合計されておりますから、それぞれ選んだものがダブってはいないということだろうと思うんですけれども、細かいことなんですが。","respondent":"榎本行財政改革担当課長","answer":"１点目の企画部選定と事業部選定のやり方ですけれども、最初に実施通知を出す段階で企画部の選定したものを各事業部長にお知らせしてあります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"佐藤委員","kind":"質問・要望","question":"行政評価を左右するのは、結局トップの意向だということをを、三重県や宮城県の知事からいろいろ聞いているんですが、２０２本の評価対象の中に、区長のどうしてもこういったものをやりなさいという強い指示によって取り入れられたものがあるのかどうなのか。区長の意思はどういう形でこれに反映しようとしているのか、それを教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"今回の選定につきましては、特にそのような指示は入っておりません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"金高委員","kind":"質問・要望","question":"来年の３月に公表がされるわけですけれども、その後の状態として、これは広く一般の方々に出ていくわけですけれども、それを実際に区民の方々はどういうふうに評価するかという、追跡調査といいますか、比較、対象等はこれから出てくると思うんですけれども、そういうアンケート調査というものも今後実施するという、先の問題になりますけれども、それが表に出てくるということは。","respondent":"榎本行財政改革担当課長","answer":"その辺につきましては、アンケート調査をとるかというところまではまだ実際の予定としては組んでおりませんけれども、そういう形でなるべく意見が取り入れられるような形で検討を進めていきたいと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"金高委員","kind":"質問","question":"そうすると、出てきた意見に左右されるということも時としてあるわけですから、その辺も含めて、先のこともしっかりと、一般区民の方々の行政サービスに対する評価、行政がここまでやっているという、逆にいい評価を区民の方からもらえるような、そういう調査結果を踏まえて、また次年度、あるいはその先々まで、そういうような体制をぜひとり得る体制というようなものをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"予算事務事業７０６本のうちから平成１３年度はもうしているということで２０２ということですけれども、最終的には予算事務事業すべてについて評価をするということを考えているんですか。","respondent":"榎本行財政改革担当課長","answer":"平成１３年度、平成１４年度で一応すべて網羅する予定です。","voiceIndex":33,"id":"exchange-015"},{"speaker":"桜井委員","kind":"質問","question":"この行政評価は、区としては実際どういうふうに見て、どういうイメージで考えていくということなのか。第２次評価というのが、今度事業部経営会議ということだから、今までの首脳部会議というんですか、そこでやるわけですよね。そうすると、今の東京都で言えば、第１次評価と第２次評価というのが出ていますけれども、イメージとしては、こういうのがありますよというのをお聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"イメージとしてはそのような形になっております。要は、事業所管の第１次評価というのは事業部長の評価で、総務局の評価というのが事業部経営会議の評価という形になります。","voiceIndex":47,"id":"exchange-016"},{"speaker":"桜井委員","kind":"質問・要望","question":"これを全部見ていないんですけれども、実際に都民への公表というのは、都のおしらせとか何か、どういうふうな形で出ているんでしょうか。もしあれば、どこに出ているというのを。インターネットで全部というのも何ですけれども、ダイジェスト版というのか、分かりやすいものがあるんでしょうか。もしあれば教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"私もホームページ全部を見ていないんですけれども、ホームページの中で概略版の部分の説明というのがあったかどうかは、ちょっと記憶が定かでないんですけれども、平成１１年度、平成１２年度もまとめて全部ホームページのほうに掲載されております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"ＰＤＣＡというんでしょうか、評価した結果を次の年度の事業に生かしていかないと意味がないわけですが、例えば２２ページのところで言えば、これは初年度、スタートの年度だからないかもしれないんですけれども、前年度の評価がこうでという、前年度との対比の資料というんでしょうか、見当たらないんですけれども、その辺をどういうふうに、前年度の評価が今年度の評価にどのように反映されて、その結果。","respondent":"榎本行財政改革担当課長","answer":"前年度の評価というものですが、東京都の政策評価、事務事業につきましては、平成１１年度から試行が始まっておりまして、まだ平成１１年度にやった事業の中に平成１２年度が入っているというものがありません。","voiceIndex":51,"id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"確認なんですが、区の経常事務事業などのように、継続して実施する事業に関しては、前年度の評価をまた今年度も検討していくという、そういう関係はないんですか。","respondent":"榎本行財政改革担当課長","answer":"経常事務等につきましては、まず今年度ある程度評価をいたしまして、問題点等があれば改善していくという形になりますし、問題点がなくて、もう少し維持していくというか、様子を見るという形であれば、引き続き実施してデータをとってという形で。","voiceIndex":53,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"先ほど、都の場合、現場サイドの評価と、総合的な２次評価が不一致の場合が多いんですけれども、もちろんそれにおいては、２次評価は事業部経営会議という評価のできる部所ですから、違いが評価からつかめようかと思うんですけれども、区の場合は最終評価というところにあたる２次評価が事業部経営会議ですから、その評価がある意味最終評価として捉え、それを決定していくというイメージになるのか。","respondent":"榎本行財政改革担当課長","answer":"最終評価が、区の場合につきましては、事業部経営会議というところで評価しますので、それに基づいて変わっていくです。","voiceIndex":55,"id":"exchange-020"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味で、各課で、廃止又は休止が必要という実績が出てくる場合があるのかなと思いますが、そういうときに、私たちが、これはこういうふうにもっとという意見を、先ほど報告をしていただけるということがあるので、そういうことはないと思いますが、区としては、そういうときにはどのような形でなさるんですか。事務手続きはよく分かっているんですけれども、廃止又は休止と。","respondent":"市岡企画財政課長","answer":"おっしゃられるとおり、そういうものを実績がゼロだということで、マイナス評価だけをしてしまうと、今度は行政評価で、車の両輪である事業部からすると、その制度の趣旨が十分ご理解いただけない、こういうことがありますので。","voiceIndex":57,"id":"exchange-021"},{"speaker":"本多委員","kind":"質問","question":"東京都の公表の出し方ですけれども、１次評価、２次評価というような形で、それぞれ目標数値、それと成果という、指標で、これは見やすいんですけれども、ただ、品川区の取り組みの中では、組織の競い合いですとか、職員の意識の改革ですとか、品川区の取り組み方に、出し方というんですか、期待している部分がありますよね。","respondent":"榎本行財政改革担当課長","answer":"数値で見ていかないと、結果はつかめないというような形なので、事業の中身にもよりますけれども、やはり直接執行型の部分と、間接執行型の部分の違いが出てこようかなというふうに認識しております。","voiceIndex":59,"id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"都と区の器の大きさの違いというので、当然出し方は違うと思うんですけれども、品川区の出し方について、その辺の組織改革、組織の競い合い、職員の意識の部分について、都はこういう出し方しかできないと思うんですけれども、区でのその辺の期待というんですか、その辺の取り組み方について、もう一度お聞かせいただきたいんです。","respondent":"榎本行財政改革担当課長","answer":"まだ取り組みが途中なもので、なかなか難しいとは思うんですけれども、実際には挑戦加点評価ですとか、どういう工夫をしてきたかという部分がありますので。","voiceIndex":61,"id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"この辺をどのように判断しているのかということ。品川区では平成１２年度モデル実施ということで、同じように、形は違うでしょうけれども、実施したということで、このブレみたいなものは品川区の中ではなかったのかどうか、その辺のところをお聞きしたいと思います。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"２段階ぐらいかなりブレがあるですけれども、この間農水省のほうで１次評価をした結果、外部評価委員会のほうからは、達成度とか、目標数値の取り方等が問題がかなりあるのではないかというような意見も出されておりまして。しかし、その手法と今度の行政評価の仕組みとで大きな違いがあるのは、例えば予算を査定する側、あるいは予算を編成する事務の側が、規制的に見直しを強制的にかけていくのに対して、今度は事業部が自分で評価をして。","voiceIndex":63,"id":"exchange-024"},{"speaker":"佐藤委員","kind":"質問","question":"一つだけお伺いしたいんですが、事務事業評価で、私自身興味を持っているのは、学校の関係の評価というのは、どういう形で評価されてくるのか。ただ一般で終わってしまうのか、４０校、１８校、各学校別に詳しい評価とか、すべての面を洗い出して公表するのかどうなのか。それはどういうふうな受け止め方をしているのか。","respondent":"榎本行財政改革担当課長","answer":"ただし、今後そういう形での学校間での個別評価をしようとすれば、それはまたちょっと手法を考えて、そのような形もとれるかと思うんですけれども、そのときにはかなり校数とか、事務作業が増えますので、その辺のバランスも考えながら、全部の学校をやるのではなくて。","voiceIndex":68,"id":"exchange-025"},{"speaker":"菊地副委員長","kind":"質問","question":"１点お聞きします。３１ページに、都心共同住宅供給事業とあるんですけれども、これも２次評価で、総合評価Ｃにまで下がっていますよね。ここでの東京都の総合評価がぐっと下がっている状況が、区の評価の中で反映していかないのかどうかというのが、その辺がちょっとよくわからないんですけれども、その辺がありましたら。","respondent":"市岡企画財政課長","answer":"そういう意味では、都心共同住宅の建設事業は区にとっては都の補助事業ですけれども、そういう影響は若干あろうかと思いますが、これも試行で、この結果が具体的に予算に反映されているわけではありませんで、これを見て我々も。","voiceIndex":70,"id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"１点だけ確認したいんですけれども、東京都の場合も、東京プロセスの中で、都議会の係わりがあるのかないのか、その点を確認したいと思います。","respondent":"榎本行財政改革担当課長、中尾根企画部長","answer":"その辺につきましては、報告書が送られてきただけなので、その辺はちょっと私どものほうではつかんでいない状況です。この報告書を見る限りでは関与しておりません。報告を受けて、それについてどういう議論をされるかというレベルだと思います。この中に直接、例えば外部評価の存在として介在しているとか、そういうことはないです。","voiceIndex":78,"id":"exchange-027"},{"speaker":"桜井委員","kind":"質問・要望","question":"アメリカのベンチマーキング方式というのと、戦略計画方式という、この文章だけの説明で見ると、この方の最後のまとめで、日本流にどうやっていくのか、教訓をどう学んでいくかということですけれども、率直な感想でもいいんですけれども、今説明をされたというのは、ある程度区のほうも行政評価システムをやるに当たって、アメリカ流なのか、イギリス流なのか、あるいは日本流なのかという。","respondent":"榎本行財政改革担当課長","answer":"ベンチマーキング方式とか、戦略計画方式というのは、中身がはっきりわからない部分で、先ほどの東京都の政策評価というのは、どちらかというとベンチマーキング方式をとっているのかなとは思われるんですが、実際上は、この方式をとって、じゃ、どうするかという部分は。","voiceIndex":84,"id":"exchange-028"},{"speaker":"桜井委員","kind":"質問","question":"だから、私は、アメリカの成果方式というのが、自主的に日本の中で地方自治体がちょっと取り上げたにしても、企業までは随分先行して取り入れたという、そこの歪みが、アメリカもそうだし、日本もきているというふうに私自身は認識しているんですけれども、あえて、例えばアメリカのこういう方式も一つの方式だという紹介なんですけれども、その辺の問題点とか、そういう点というのは。","respondent":"榎本行財政改革担当課長","answer":"いろんなそういう海外の方式もありますけれども、日本は日本でいろんな先行自治体、東京都を初め三重県ですとか、静岡県ですとか、いろんな手法がもう大分入ってきておりますので、その中でもどのレベルに、どういう形でやっていくかという部分の目的とか。","voiceIndex":86,"id":"exchange-029"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう点で、今とっている成果主義というのが、日本の企業にとってはどうなのかという、そういう検証的なものがあったものですから、だから、併せて両面を見ていく必要があるのかなというのが、私の意見です。もう一つ質問ですけれども、今、国のほうで行政評価法が可決されていますね。なければ、次回でも参考にいただければと思います。","respondent":"榎本行財政改革担当課長","answer":"新聞で、農水省のほうが１年前倒しで独自に自己評価をしたという形で、Ａが全体の半数を越えるものについて、第三者委員会から、目標の改善点を含めて多くの注文がでたとのことですので。","voiceIndex":88,"id":"exchange-030"},{"speaker":"鶴委員","kind":"質問","question":"アメリカがどうだ、イギリスがどうだ、だから、先ほど品川区方式という話がありましたけれども、そういう私たちが独自な日本流の変更を変えて導入するかという点が今後の焦点になってこようと、こういう指摘もここになさっておりますけれども、私たちは外国の手法に左右されることなく、品川区なら品川区が考えた手法でもいいのではないかというふうに思ったんですが、この点はいかがでしょうか。","respondent":"中尾根企画部長","answer":"そういう意味では、品川区は品川区の方式できちんとやっていきたい、そういう考え方でやってありますので、今後ともよろしくと願いしたいと思います。","voiceIndex":90,"id":"exchange-031"},{"speaker":"松澤委員","kind":"意見","question":"今回、先行自治体事例ということで、東京都からのということで、資料２をいただきました。できましたらば、視察が可能ならば行って、実際にお話をしてみたいかなと。東京都の考え方、わけても第２次評価をした総務局の考え方を聞いてみたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-032"},{"speaker":"桜井委員","kind":"提案","question":"都のほうの視察は私も賛成です。併せて、この間ちょっとお話し申し上げた、川崎市もかなり先行して事業評価実施要綱があります。要望として、こっちも。それから、再評価をやったりしているので、私どももおととし行ったんですけれども、その後どういうふうに実績があるのか、参考にしたいなというのがありますので、提案をしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-033"},{"speaker":"桜井委員","kind":"確認","question":"１点だけ。実は今環境ＩＳＯをやっています。実際に相談の方が見えていて、時間外であったにしても、そういう事情というのを確認しないで、たまたまそれは福祉課だったんですけれども、ほかの部所でも多分相談の方が若干ずれることもあると思うんです。そういう場合というのも容赦なく１５分で消灯しちゃうというのもありますでしょうか。そこは私は大変心配しているんです。","respondent":"太川総務課長","answer":"ＩＳＯの関係で、１０月の取得に向けていろいろと準備を進めているんですけれども、まず、電気の使用量について、一定目標値がございまして、私ども総務もそうなんですけれども、基本的にお昼につきましては、ある程度お客さんを見計らいながらですけれども。","voiceIndex":103,"id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"でも、やっぱりそれは何のための環境ＩＳＯかと思うんですよ。しばらくそのままの状態だったんです。それで係の方に、「いつもこうなんですか」と言ったら、「こうです」と言うんです。環境ＩＳＯの、一旦消灯というのがあるにしても、そこは改善すべきだと思うんです。さっき言ったように、何よりも第一に住民サービスのための環境ＩＳＯですから、私はぜひ再検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5688#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":37101,"voices":106}},{"id":"h13-20010724-5","meetingId":"h13-cm07","date":"2001年7月24日","dateIso":"2001-07-24","committee":"総務委員会","time":"午後 ３時０２分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の(1)、中央防波堤埋立地の帰属","agenda":"１の(1)、中央防波堤埋立地の帰属","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"まだ全部読んでないんで、もしかしたら書いてあるのかもしれないんですけども、１３号地のときの議論で、昭和５１年１０月、都が１３号地の帰属について関係５区に意見聴取して、そのときに、意見一致せずとなっているんですけども、このときに品川区はどういう主張をしていましたか。","respondent":"桑村政策担当課長","answer":"そのときの品川区の主張は五つございまして、一つは、区境の延長線、いわゆる港区と品川区の延長、大田区と品川区の延長線をそのまま延ばせば、１３号地全部を品川区が帰属すべきだという主張をしています。もう一つは、トンネルでつながっていて地続きであるという主張。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"参考でお伺いしておきたいんですけども、先ほど、品川区の主張の３番のところで、今後の保留地的観点ということなんですけど、私も勉強不足なんで、ここら辺の動きというのは、今、どんな感じなのか。東京都がどういう考えなのか、もうちょっとわかればと思うんですけど。","respondent":"桑村政策担当課長","answer":"ただ、これからさまざまなニーズが出てくるので、今後の社会的な状況の変化に備えて保留地的観点から検討すべきではないかというのが全体になっております。そういう意味で、はっきりした土地利用についての考え方はまだ持っていないというのが現状です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"三上委員","kind":"意見","question":"派遣で実務を体験してきているわけですよね。それについての意見のまとめだとか、全職員に、こういうことだったということを知らせていくとかいうことについて、ちょっとそこら辺をもう少しご報告いただけませんか。","respondent":"山田広報広聴課長","answer":"そういうような形でまとめてまいりました。","voiceIndex":14,"id":"exchange-003"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、「役に立った」というのは、自分なりにこう書いておいたほうがいいかなと思う人もいるかもわかりませんし、実際問題、よかったと思っていると受けとめたとして、そういう意識がだんだん高まっていくということは大事だと思います。ですから改めて、今回、研修した人の個人的な意見にしても、何にしても、早急に取りまとめた報告というものを当委員会にしていただきたいとお願いしておきたいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"行った３０人に、もちろんいろいろなことを勉強してきてもらって、リーダーになってもらうんだと、その人たちが、区の職員を指導していく、あるいは教育していくという、そういう目的なんでしょ。それとも、この研修を受けたことによって、この３０人の窓口業務が直接的によくなるということじゃないんでしょ。その辺をちょっと、どっちだか説明してくれますか。","respondent":"山田広報広聴課長","answer":"必ずしも全部この人１人、リーダーだけではなかなか展開はできませんので、積み重なっている人員という形で層を広げていきたい。職場全体で一人の体験に終わらせないというところで、私どものほうはとらえているということです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"相手のあることだからなかなか難しいだろうけど、極論から言って、もう２回もやってきて、どうしようもない職員もいるわけだ。その人の訓練のために行くわけじゃないんでしょ。「この研修に派遣されるあなたの意味は、リーダーとしてこれからやってもらうには、その能力が必要だから行ってもらうんだよ」というのを言っておかないと、目的があやふやになると思うんですけど、その辺は言ってあるんですか。","respondent":"山田広報広聴課長","answer":"研修の実施に伴う研修生の推薦のお願いという文章を、庶務担課長を通じて、各所管にお出しをしております。","voiceIndex":20,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"最後にします。そういう話と違って、行く本人がわかっていなきゃだめだということ。推薦理由なんかどうでもいいんですよ。本人が行くときに、行く目的がはっきりわかっていなければむだというわけです。決意がありますか。","respondent":"山田広報広聴課長","answer":"私のほうも、説明する中で、これについては、そういう個店の中でそれぞれ納税者としていかにご苦労なさっているかということを理解して、皆さん方が、そうした中からの接遇向上をやっていくんだという自覚を持ってこの２日間を過ごしてくださいということは。","voiceIndex":22,"id":"exchange-007"},{"speaker":"北野委員","kind":"質問・要望","question":"この目的の中に、区民との信頼関係というのがありますよね。そういうときに、全体としての接客態度というんですか、それをどういうふうに考えるのか。そうしたときの全体の接客というのはどうなんでしょうか。そういうときの信頼関係とかというのも、やはりあると思うんですよ。こういう接客に対しては、これを生かしていく上でどうしていくのか、ちょっとお伺いしたいんですけど。","respondent":"山田広報広聴課長","answer":"役所というのは、嫌でも、そこでしか住民票が取れないから行くという大きな違いがあると、いつも区長は申しておりますけれども、そういった意味では、窓口へいらしたお客様に対して、どんなことであっても、何がわからないかを含めて一たんお話を伺って。","voiceIndex":25,"id":"exchange-008"},{"speaker":"北野委員","kind":"質問・要望","question":"わかりました。区民の方によっては、行ったときに、すごく疑われた目で見られると。お話を伺うときや何かも、自分ははっきり疑問を持って行っても、疑われた目で見られるというのは、やはり、接客の中では、すごく失礼ですよね。ですから、そういうところは、こういう研修を通しながら、全体の中でぜひ広げていただきたいと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"目的のところで、「区民の窓口サービスを円滑に進め、区民との信頼関係をより高めていくことを目的」と書いてあるんですけども、これはこれで特に異論はないんです。これは、民間のお店に行って研修するというやり方なんですけど、そもそもこれは、窓口サービスを円滑に進め、信頼関係を高めていくための一つの手段だと思うんですよ。基本的にそういう研修というのはほかにどういうものがあるんですか。","respondent":"本間総務部長","answer":"研修の所管は私のほうですので、お答えします。ほんとうに接遇は一番基本です。研修も、接遇に始まり接遇に終わるというぐらいに、私ども、人事課の研修でも、接遇を非常に重視した体系をとってあります。","voiceIndex":28,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、いわゆる区でやる接遇だとかいうところでは、特にこれでは不十分だということで、こういうやり方をやっているということでもないということなんですか。","respondent":"本間総務部長","answer":"ですから、そういう中で、接遇の研修もいろいろな工夫をしながらやっている。それの一環が、先ほど来、説明している研修というふうにご理解をいただきたいと思います。","voiceIndex":30,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"入ったばかりはぴしっとしているけど、ちょっと時間が経ってくると慣れも出てくるということで、いろいろ節目でやるんだと、そういうことでわかりました。今の説明ですと、今回は一般職員を対象にした、その前は係長級とか、主任主事もやっていたというんですけど、今の説明ですと、もうちょっと幹部になった課長とか、そういうところはあまり対象にならないんですか。","respondent":"本間総務部長","answer":"先ほど来、申していますとおり、例えば主任主事試験、係長試験、管理職試験にそれぞれ受かった段階での研修等でも、それぞれの立場にふさわしい内容で、接遇研修も必ず取り入れているとご理解いただきたいと思います。","voiceIndex":32,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱりそこら辺をところを強化していただきたい。特に、さっき商店の方がいろいろ苦労しているということで、そういうことも理解してもらうというのがいつも目的にあったみたいな質問があったんで、それだったら、管理職の方にも大いに行ってもらったほうがいいかなと思っています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"土井副委員長","kind":"質問・要望","question":"主任は主任としてのやり方、考え方、見方。ただ、何とか社がおやりになれば、そこでビデオを撮っちゃったら困りますということが起こるかもしれませんけども、そこはうまく交渉していただいて、一定のものが、そういう形であまねくやれるような仕組みも含めてやっていただいて、これからのさまざまなときにも応用が効くという形にしていただきたいという要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"できれば、例えばホテルですとかいう場所、あるいは、民間の中で非常に競争の激しい場所で、逆にそういうところは受け入れてもらえないのかもしれないんですが、そういう接客そのものが、ある意味、その会社、店の売り上げに大きく影響を及ぼすような業種の会社、あるいは店舗に派遣して研修を受けていただくと非常に効果があるだろうなとは思うんですが。","respondent":"山田広報広聴課長","answer":"今後の方向性なんですけれども、３年間、商店街のご協力をいただいてやってきておりますので、一たんここできちんと総括をして、来年度に向けて、同じように商店街でやっていくのか、または、違った職種に拡大をしていくのかについては。","voiceIndex":36,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"おそらくそうだろうなという思いも持ちつつ伺ったんですが、ホテルですとか、競争の激しいスーパー等の業態は、逆に言うと、研修にものすごく力を入れて、長い期間をかけていらっしゃると思うので、直接、そういう店頭に出る研修はすぐには難しいかと思いますが、研修手法というものは、そういうところからも学ぶところがたくさんあろうかと思いますので、そういうことも含めて、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"}]},{"id":"topic-02","title":"２、その他、(1)の特別区総務財政委員長会の要望事項","agenda":"２、その他、(1)の特別区総務財政委員長会の要望事項","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"手順、時間的なことなんですが、きょうは限られた時間の中で進めるとなると大変なことです。それから、全体のことですから、これはタイムリミットがあると思うんですけど、その辺のことをちょっと教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"ということは、次の私たちの予定は８月２３日で、持ち帰って、この意見で議論しながら進めるということが大変困難だということですか、全体の関係で。全くそれはできないということですか。","respondent":"本多委員長","answer":"委員長会の事務局の事務の進め方といたしましては、できれば８月中旬までには各区の意見を収集したいということです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"それは大変なことになりますね。そうしますと、一番のネックは、人事厚生制度が今のままでいいのかということに対して、見直しの機運をつくり出すことが必要なのではないかという課題意識を持っておりますので、この点について、区で提議いただきという要望を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"必要なものはやっぱりきちっと要求を出すというのは、私は必要じゃないかと思っています。私も、去年の要望とそれ以前と比べて見ているわけじゃないんですけれども、もしほんとうにこういう立場で、最初から削るなんていうことがあったとしたら、ちょっとそこのところはよく研究していただいて、やっぱり必要なものは、５年過ぎていてもきちっと要求するという立場でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"それはそれで、ぜひその立場でお願いします。私が、以前、別な委員長会に行ったときには、実際に、役員がかわって、そのときに、事務局のほうからもう既にこの文章が用意されていたんですよね。ほとんど委員長会として検討しないうちに、この文章が入ってきている。ずっとなっているものですから、機会あるときに、指摘をしていただければなと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":20238,"voices":54}},{"id":"h13-20010730-6","meetingId":"h13-cm07","date":"2001年7月30日","dateIso":"2001-07-30","committee":"区民委員会","time":"午後 １時０６分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"毎年恒例のような形で行われているわけなんですけれども、これの方法といっては何ですけれども、学校が避難所になっていますよね。それで、学校でやっているところはそんなに数多くないんですよね。だから、その辺のところで、なぜ学校のところに１回集合しないのかなと思うんだけど、その辺の状況はどうなんですか。それぞれ学校としてはやっていないところもいまだにあります。それを含めて、ちょっと１点。","respondent":"辻田防災課長","answer":"そういう中で、避難所であるなら、そこにまず寄って、それから来ようかとか、それから訓練が終わってから、そちらのほうの学校の状況を見に行こうかという形で避難所に対して非常に興味を持ってやっていらっしゃる町会と、まだまだそこまでいっていない町会。","voiceIndex":7,"id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"現状の中では、かなりばらばらな感じですよね。例えば、うちなんかの場合は、１０月２８日に西大井広場に集合するわけ。その前に集まるところが、今言った学校でない場所が結構多いんですよ。まだ徹底されていない。その辺をもうちょっとうまく徹底ができて、本来はこういうルートで、こういうふうに行ってくださいよと徹底すべきじゃないかなと思うんですが、このことなんですけど、どうなんでしょうか。","respondent":"辻田防災課長","answer":"それにつきましては、私どものほうも、地域の自主性とか、それから、自分たちで考えて行動するという自主防災力向上のために、それはそれなりにいいことだと、進めるべきだというぐあいに考えていますので、全体の予定を乱さない限り。","voiceIndex":9,"id":"exchange-002"},{"speaker":"堺委員","kind":"質問・要望","question":"校長先生や教頭先生がお見えになってる学校もあり、我々から見ているといいなという印象を受けるわけですよね。今回は、第一日野小学校と大崎中学校、平塚中学校、第二延山小学校、荏原第四中学校、源氏前小学校と、そこが使われておりますけれども、それぞれ今申し上げたような形で協力するというんですか、一緒になってやれる体制になっているのかどうか、この辺をちょっと教えていただきたい。","respondent":"辻田防災課長","answer":"そのほかにも、学校でやらなくても地域の方がそういう形で出る場合、大井第２・第３でございましたけど、校長先生も地域の方々と一緒になって参加しているというのがこの一、二年あります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"堺委員","kind":"意見","question":"間違ったらごめんなさい。たしか、最近、荏原第５地区の荏原第四中学校であった話をしますと、その時に学校の生徒さんが一緒に行ったような気がしたんですが、ジャージに着替えて何名かの人が一緒になってやった。違いましたか。できることならば、そういう方向で地域に呼びかけて一緒になってやっていくという方向の体制をつくっていただいたらいいなと思っていますが、わかりますか。","respondent":"辻田防災課長","answer":"地区の総合防災訓練、いろんなことをやっていただきますけど、基本はやはり地域の方々のコミュニティを育てていくということかなということで実施しております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"金高委員","kind":"確認","question":"実は、ラジオ体操を今やっているわけなんですけども、朝の段階においても、終わった後７時に校長先生からかぎを借りて、それを締めて帰るという形になっておりますけど、通常それでも構わないんですけども、災害の場合には万が一ということですから、その場合に、門が締めてありますけども、例えばだれもいないわけですから、万が一のときは、その施錠を壊して。","respondent":"辻田防災課長","answer":"これは、いわゆる地域の町会、自治会、いわゆる防災の関係者の方々にかぎを必ず渡してほしいということで、今後それをきちっと進めていただきたいということで、私のほうも要望を出して、教育委員会のほうも十分それについては検討するということで、お話しいただいております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"金高委員","kind":"質問","question":"私も、町会の役員をやっているものですので、そういう話が出たものですから、たまたま今青少年部のほうでもってラジオ体操をやっているわけなんですけども、そこで聞いたら、かぎは借りているということなんですが、町会全体の役員さんがまずそこまで認識を持っていないということがちょっとあったものですから、それで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田副委員長","kind":"質問","question":"すみません、私から一つ。これは品川のイメージだったのかどうかわかりませんが、今１２項目を見させていただいて、炊き出しというのは、品川の場合はやらなかったと思うんですが、これはここに書いてあるということは全部やる、まず最初に全部やるということで考えてきたのかどうか、それを教えてください。","respondent":"辻田防災課長","answer":"ですから、品川第１地区につきましては、従来やっていなかった。ですけど、今後やる場合につきましては、私どもも十分それに対応していきたいと考えていますけど、ぜひ入れていただきたいと思います。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田副委員長","kind":"意見","question":"今のお話だと、１カ所か２カ所、今までやっていらっしゃる、継続的にやっていらっしゃるという。例えば、炊き出し訓練の中でカレーを何百食無料配付しますみたいな、だから、訓練に参加してくださいみたいな回覧板を配付すれば、間違いなく人は来る。もちろん予算が絡んでくるんだけれども、そういう回覧板まで含めた話も含めて、どう考えていらっしゃるのか。","respondent":"辻田防災課長","answer":"ただ、それを工夫をするという部分で皆さんに食べていただくという形でやっておりますので、そういう形でそれ自体が集客につながるかどうか、それは今のところ、ちょっと今までの例を見ますと、なかなかつながらないなという感じなんですけど、ただ。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"ということは、せっかくのこういう防災訓練のときに、炊き出しということは、そういうセットを行政側がしてあげるのも、私は一つかなと思うので、これは予算の話もあるから要望にしておきますけど、そういうのも観点に入れて、せっかく課長もいらっしゃるから取り組んで、１万幾つ回覧板を全部刷って出すぐらいはこっちの予算でやってよとかやることは可能だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"膨大な計画で、前からそれなりに聞いてはいたんですけども、品川区に正式にこういう形で来たのは、今回初めてですか。","respondent":"金井環境課長","answer":"私どもに、事前に１回この説明会を開催したいということで、情報提供があったのが、５月の中旬過ぎでございました。このときには、説明会を開催するに当たってということで、情報提供という形です。そのときが初めてです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"環境に関連しての審議が当委員会での付託ですから、決定されちゃうことですが、今具体的に中央環状品川線の平成２５年以降完成まで出して、この２年間で法の手続に基づいていろいろやって、２年後には着手しようと、こういう計画でありますけれども、昨日の選挙ではありませんが、こういう道路建設計画が、前からいろいろ言われていたわけですけれども、目黒川の下を通すとか、上を通すとか。","respondent":"金井環境課長","answer":"大変難しいお話ですが、私どもが知っているのは、先ほども若干ご説明をいたしましたけども、要するに慢性的な渋滞が、これは首都高速だけじゃなくて、環状線だけじゃなくて、周辺に環状６号線も環状７号線もですが、これはそうした慢性化の渋滞を解消するというのは。","voiceIndex":30,"id":"exchange-011"},{"speaker":"本田委員","kind":"質問・要望","question":"今６万台ですから、かなり増えてくるので、新たな問題が発生するなという感じもするんですが、いずれにしましても、環境調査の項目をこれから策定していくということであり、また、どのぐらい金がかかるのかもわからないということですから、今日ここで、あまり質問もできないと思いますが、これ以上のことは控えますけれども、いま少し当委員会にアウトラインが。","respondent":"金井環境課長","answer":"都市計画線は、基本的にはこれは大変難しいんですが、建設委員会になりますので、私どもは、この路線についての意見がどうのこうのというのは、環境課の立場としてはなかなか難しい。","voiceIndex":32,"id":"exchange-012"},{"speaker":"本田委員","kind":"意見","question":"品川区にとりましては、東西の道路としては都道補助２６号線の建設等につきましても、かなりの年月をかけていろんな議論があり、そして、工事に入っておりますけれども、あわせて、この中央環状品川線の道路建設は地下をくぐって直接この民地等買収とか、いろんな問題が起きないので、割とすっといくような印象を受けるんですけれども、これは大変大きな、都民にとりましては建設だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"もう一つは、これは平成１５年から工事を始めて１０年間かかるんですよね、完成まで。ほかの道路行政もそうですけど、大変時間がかかるので、果たして１０年後に、これがどのぐらいの有効手段なのか、有効的に使えるのかどうか、そういう考え方はどうなんですかね。ちょっと、もし、おわかりになったら教えていただきたい。","respondent":"金井環境課長","answer":"そのほか、いろいろ細かい内容もありますけれども、これらについて、さらに工事の実施状況、あるいはその後、将来的にどうなのかも含めて、これから事業主側と構想が上がってまいりますので、その内容について、今年どうなのかというのをチェックして。","voiceIndex":35,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"この中央環状品川線に関してね。それはさておいて、先ほどの説明の中で、内容を詰めるということで、その報告書なり、あるいは方法書ですか、それが平成１３年度の４月以降に上がってくるんですか、説明の内容だと。要するに、詳しい内容のものが、環境課のほうに提出されるというか、報告されるのは、いつごろの時点になるわけですか。","respondent":"金井環境課長","answer":"一番最後の手続の予定表を見ていただきたいと思いますが、方法書というこんな方法で、こんな項目を持って環境影響評価をやりたいんですがという方法書が８月１７日までに出てまいります、事前にですね。","voiceIndex":39,"id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"大変いろんなことが見えてきたんですけど、そうすると、向こうから来る項目について、８月１７日に方法書が作成された時点で、区は項目のチェックをすると。そうすると、その時点で住民のほうの説明は、要するに８月１７日から９月１７日の間に説明会を開くと、そういう形になるんですか。","respondent":"金井環境課長","answer":"８月１７日から９月１７日に公告を縦覧いたします。それは東京都が行うわけですが、品川区の環境課にもこれは置きます。地域センターにも閲覧できるようにいたします。直接意見は東京都のほうにお願いするわけです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"原委員","kind":"確認","question":"これで終わりにしますが、ちょっと確認なんだけど、そうすると、住民が公告・縦覧の上に立って、東京都へ意見書を出すわけですよね。そうすると、それはある一つの形式をとらなきゃならない。要するに、ファックスとか電話ではだめという話ですから、一つの形を整えて東京都へ提出してください。そうすると、その住民はその形式について、どこでどういう形をとったらいいかというのが提示されるわけですか。","respondent":"金井環境課長","answer":"基本的に、住民説明会とか、公聴会とかというのは、方法書の前の段階ですので、それは第２段階で、平成１４年度の準備書の作成のときの案のときには、ここで一定の方法書の、意見をいただいたものの項目をいろいろやって、その結果がこうでしたよというのを公表した、その中で。","voiceIndex":47,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"今、原委員のお話の中で、言われたのかもしれないけど、よくわからなかった。方法書の作成があって、これそのものが報告されると。じゃあ、区民委員会として、この方法書をここで意見を交わす場というのは、つくらせないということなんですか。","respondent":"金井環境課長","answer":"基本的にはそういう流れになろうかと思います。これはあくまでも、行政に対する意見と区民の皆さんの意見という形になります。議会の意見というのは、これまた別の問題です。","voiceIndex":49,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"別の問題というか、区民委員会で審議ができるということですか。","respondent":"金井環境課長","answer":"ただ、例えば、区としてはこういう意見を出しますよという、その中では審議といいますか、お話はご報告できるかと思いますけれども、審議というのはなかなか難しい。","voiceIndex":51,"id":"exchange-019"},{"speaker":"南委員長","kind":"質問・要望","question":"よろしくお願いします。ほかにご質問ないでしょうか。──いいですか。では、この報告については、以上で今日のところは終わりにいたします。さて、予定表では３番目の行政視察でありますが、これはちょっと後回しにさせていただいて、４番のその他を繰り上げて先に取り上げます。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"南委員長","kind":"提案","question":"ですから、今年もこの区民委員会といたしましては、特別区区民委員長会に依頼が来ておりますので、資料の１ページから３ページということで出ていますよね。ですから、これにつきましては、今年度は取り上げられない可能性もありますので、新たな要望事項、または昨年度の要望事項のうち、特に強く要望したい事項に絞って、品川区のこの当区民委員会の案として提案していきたいというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-021"},{"speaker":"本田委員","kind":"質問・要望","question":"次回の委員会で結構ですから、東京国際空港北側進入に関する現況について、再度ちょっと環境問題がありますし、騒音問題が関連しておりますので、ご報告をいただきたいと思います。今日はいいですから、次回の委員会でご報告していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"場所は、今一応この前もこの委員会の中で正副にお任せしますということなんで、その中で適切なところをとっていただいたと思うので、ほかにあればまた別ですけど、これでいいと思います。ただ、この視察、たしか２泊３日でしたよね。その中で、どういう視察の割り振りですよね。そうすると、大体ルートもここだと大体行けるような範囲の形にはしてありますけれども、少しきついかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-023"},{"speaker":"石田副委員長","kind":"質問・要望","question":"ここに資料をお出しした東大阪市ですが、これも大田区でも同じようなことをしておりますが、大田区が東大阪市というと、非常に皆さんもご存じのように規模が大きいものですから、大田区よりも規模が大きくて、大田区もこれを目指しているというような街でありまして、大田区でもある一定のラインの結論が出ておりまして、ただ、東大阪市がどこまでこれを取り組んで。","respondent":"南委員長","answer":"副委員長から補足説明をしていただきました。何カ所ぐらいまず見るかと、こういうことを原委員のほうからありましたけれども、今のあれでいきますと７カ所ですよね。彦根市も入れると８カ所、一緒にすると８カ所ですけど。","voiceIndex":69,"id":"exchange-024"},{"speaker":"原委員","kind":"意見","question":"トータルで８カ所になると思うんですよね。こういうルートでこういうふうに行くと、これだけ見られますよ。そのかわり、昼はお弁当になりますよとか、あるいはちゃんとお昼を食べたら、こういうルートで、これだけの視察になるという二つか三つ出していただいて、その中で、じゃあ９時半はきついけれど、こっちへ行きましょうとかという形になるんじゃないかと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"副委員長が説明をしてくださって、せっかくの３日間ですから、できるだけ見てみたいなという思いもありますし、確かに去年の建設委員会３日目に、午後もたしか向こうにいたような思いがあるんですけどもね。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"だから、相手さんのあることだから、結局うちが勝手に時間どおりに行きたいと言っても、何時から何時までに来てくれとか、あるいはこの時間にという指定が必ずあるはずなんで、それを無視して行くというわけにも行きませんから、その辺までの日程も含めて正副で前つくっていただいたような資料をつくってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-027"},{"speaker":"石田副委員長","kind":"質問","question":"そうしたら岸和田市で、基地だの、その前に調査をしておりまして、そうしましたら、岸和田市の方が今日は午前中で終わりだというお話を岸和田市の方が伺ったら、それなら終わりなら、有志の方でだんじり会館をどうぞ見ていったらどうですかというお話があって、すべてご案内をしてくれたという、好意でやっていただいたものがありました。その話ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":32750,"voices":83}},{"id":"h13-20010730-7","meetingId":"h13-cm07","date":"2001年7月30日","dateIso":"2001-07-30","committee":"厚生委員会","time":"午後 １時０９分～午後 ３時０７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"平成１２年度と１３年度に既に開設しているって書いてありますけど、ここでは、特に職業や住宅についての相談・指導ということですが、どういうことが行われているのか、もうちょっと詳しくお伺いしたいと思います。既に開設されて、運営されているということで、そういった事業をしてどんな成果が生まれているのかとか、そういうことをちょっとお伺いしたいと思います。","respondent":"黒田生活福祉課長","answer":"台東寮と新宿寮が開設されてまして、６月現在で、入所が４７３名。数がいろいろダブっておりますので、ちょっと読み取れないものがあるんですが、その中で、やはり３６.４％近い方が就労しているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"じゃあ、残りの人はどうなっているのかということや、あるいは、３６.４％の仕事を見つけられた人たちも、その後、継続できているかどうか、再び路上生活者に戻っていないかどうかということも気になるんです。アフターケアというか、その後どうなっているかということについての調査や、また再び問題を抱えた場合の支援とか、そういうことも行われているんでしょうか。","respondent":"黒田生活福祉課長","answer":"退所の理由としましては、就労自立による方が、先ほどのパーセンテージということです。やはり長期入院になったり、寮の規則に違反して出る方、集団生活ができない方が出ていくということがありましたり、そのほかの事情で出ていくということです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"船波委員","kind":"意見","question":"そのほかの理由があって、仕事につかないでほかのところに出て行ってしまうのはしようがないにしても、さっきご説明にあったような職業に１回ついて、出て行っても、その後ほんとうに自立し続けられているのかどうかというところが気にかかるところなので、その辺がまだ時間が短くて、よくわかっていないというのであれば、今後、これだけの数が開設されて、こういった事業が行われていくのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"二つお伺いいたします。それから、緊急一時保護センターですから、当然緊急であり、一時的なことでしょうから、いつまでいられるのかということ。それから、当然、時期が終わった後は自立支援センターにつないでいくでしょうけれども、その間の調整はどういうふうにとっているのかということ。それを教えてください。","respondent":"黒田生活福祉課長","answer":"長期で医療が必要な方は入院の保護をかけながら、体を直していただいて、また就労が可能なら自立支援センター、それがだめな場合には入院等、いろいろな段階に応じて対応していくということで考えてあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"今、「連携をとって」とおっしゃいましたけど、今、東京都ではそうやっているということでしたけど、できればもう一歩踏み込んで、品川区でもそういうふうな横断的なシステムをつくって、残念だけど、平成１２年８月の時点では人数が第３番目になったということですから、そういう方々に対しての新しい区として事業の方向性を研究していくことが必要だと思うんですが。","respondent":"小沼福祉事業部長、黒田生活福祉課長","answer":"私どもも、その辺の情報を収集すると同時に、ご指摘のような点につきまして、また法改正等が２年後、３年後に予定されてありますので、そういう動きも兼ねていろいろ情報収集に努めて、今後、この辺を含めて。ただ、厚生施設というのを特別区人事・厚生事務組合に持ってございまして、厚生施設を出た後アパートを借りるのが難しい方に対して、やはり社会生活になじむようなものということで、一部始めているものがあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"緊急一時保護の対象者というのは、どういう形で対象になるのかを教えていただきたい。新たに豊島区も増えているんで、それが若干増えてくるんだと思うんですけれども、その残りの９割の方には、これからどういう対策がされるのかということを教えていただきたいと思います。ここに入ったところで、就労を希望するという方は、全員職につけているんでしょうか。","respondent":"黒田生活福祉課長","answer":"大田区が３００人で、あと４カ所で４００人ということで、今のところ７００人程度を予定しています。自立支援センターが５カ所全部できますと、４００人程度ということですので、両方で１,１００人ぐらい。現在、若い方も含めて自立支援センターに入っているんです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどお聞きした中で、自立支援センターの中で、就労を希望すれば全員つけているのかどうかということと、品川区では、就労に結びついた方の実績がどのぐらいあるのかということについて、教えていただきたいと思います。","respondent":"黒田生活福祉課長","answer":"そういうところから、就職に結びつかない方は半福祉半就労ということで、フルタイムで働くのではなくて、軽作業とかそういう少ない時間働いて、少しでも収入を得た上で、福祉的な保護を受けながら、半福祉半就労の形で生活していただくことも考えていくということで。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"自立支援センターに入られて、その後、なかなか職につけないということですが、そうすると、また路上生活に戻るということではなくて、ほとんど生活保護という形で対応されるということになるということでいいんでしょうか。","respondent":"黒田生活福祉課長","answer":"どういう生活をしていくかというご本人自体の生活設計を、必ず入所する際に話し合って決めていくというのが前提ですので、ご本人の意欲と目標に向けて、福祉事務所と東京都が支援していくです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もこれを読んで、８割の方が仕事につきたいということは、ちょっと驚いたんです。そういうところでは、どう対応するかによって、どんどん少なくしていけるということなんだろうなと思ったんです。そういう点では、就職を希望する人が、今、普通でもなかなか就職できないという状況ですから、自治体としても仕事をつくり出すというか、そこら辺のところでは、ぜひ、今後検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"今、こういう事業をやられているということを聞いて、大変すばらしいことだと思います。こんなに暑いですから、先ほども図書館等を利用しているということなので、ああ、そういうところに昼間はいるのかなと思いました。区に相談する方だけなのか。大体でいいんですか、８３名の中に女性が何人ぐらいいらっしゃるか、もしわかりましたら、教えていただきたいと思います。","respondent":"黒田生活福祉課長","answer":"意欲のある方ですと、声かけはさせていただいていますが、たびたび伊藤委員からもお話がありました水神公園の方ですと、声をかけると怒るということで、先日も、気になりましたので見てまいりましたけれど、トイレの裏側に物を干しながら、日陰で３人で寝そべっていた。","voiceIndex":22,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"そのときにぽんとその話が来たんですけど、今のところ見えている図で結構ですから、こういう形で法改正がされそうだという情報とか、法改正が２年後ということですけども、そのことについての全国の動きがもしわかりましたら、教えていただければありがたいんですが。","respondent":"黒田生活福祉課長","answer":"東京都としては、国のほうから声がかからなくても何かを考えていきたいということで、今、検討会というのを設けたかのように聞いてはありますが、内容については、まだこちらのほうには伝わってこないです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、慎重にすることも必要でしょう、というものも、こういう新しい問題もでてきているわけですから、ぜひ、品川区のほうも、国とか東京都に強く働きかけをしてくださいますようにお願いいたします。順次報告をしていただければと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"職を失ったときに、スムーズに生活保護が受けられれば、路上生活者にならなくて済むという方もいらっしゃるんじゃないかと思うんです。住民票がない場合だとか、働ける能力があっても、職がないために働けないとかいうところでも、生活保護というのは受けられることになっているんでしょうか。","respondent":"黒田生活福祉課長","answer":"お元気の方が、職がないから、即生活保護というのは、どう考えてもちょっと、やはり区民の方も納得できないんではないかと思いますので、できるだけ自分ができることをやっていただいてからご相談ということになろうかと思います。","voiceIndex":28,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません、この経過がよくわからなかったんですけど、旗の台分室が統合されるという理由は何なんでしょうか。","respondent":"高橋総務部副参事","answer":"ふれあい作業所につきましては、過去、４カ所で行っていたところ、職員の配置、連絡の状況で、やはり効率的な運営ができないということで、ふれあい作業所の西品川分室が空いていましたので、そこに移転することによって、全体的な運営を効率的に行っているところです。","voiceIndex":35,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"資料が全然ないので、ちょっと何が何だかよくわからないという感じがするんですけど、職員の配置とか、効率的な運営ということですが、じゃあ、今まで旗の台分室にはどれぐらいの方がいらして、職員はどれぐらいいたのが、今度の西品川分室はどれぐらいいて、職員がどうなったのかというあたりを教えていただけますでしょうか。","respondent":"高橋総務部副参事","answer":"区の職員ではございませんで、これは社会福祉協議会のふれあい作業所ということで、社会福祉協議会が運営しているものの職員の配置です。このところについては、ふれあい作業所の状況について報告させていただいたということですので、直接区の職員とは関係なく行っております。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もそれまでのところがよくわからなかった部分もあって、全体像がよくわからないんですが、じゃあ、４園で４１名ということなんでしょうか。旗の台に何名ぐらい通っていたのが、西品川では何名から何名になったとか、そこら辺のところをちょっと教えていただきたい。それから、旗の台だったら通いやすかったのが、遠くなっちゃって通いにくいとか、そういう問題はないんでしょうか。","respondent":"高橋総務部副参事、小沼福祉事業部長","answer":"作業生につきましては、通勤しにくいということは特にありませんで、通勤に当たりましては、一応訓練日ということで、自宅から新しい作業所に通勤のための練習ということもありますので、その辺につきましては、１回練習すれば。実は、ふれあい作業所というのは、品川区社会福祉協議会のほうで独自に興している事業ということで、お考えいただければと思います。主に、知的障害者の一つの就労する場ということです。この中で、幾つか分室があります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"鶴副委員長","kind":"意見","question":"説明というのは、とっても大事だと思うんです。統合と聞いただけで、何か整理縮小でもするような印象で、それを疑ってかかる人も中にはいると思うんです。今までの作業環境がよくないということで、今回の措置については、歓迎すべきことはあっても、非難に値するのではないと思うんですよ。今後、意を払っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"いろいろ資料をまだ十分に読んでないんですけども、品川区の制度がある程度ベースになって、任意後見制度というのが法律的につくられてきたというふうに聞いているんです。それからもう一つは、区長の申立てということが、後見人のあれとして出るんだけども、単純にそういうシステムでいっちゃっていいのかなという気もちょっとしているんですけど、そのあたりはどうでしょうか。","respondent":"中川原介護保険担当課長","answer":"財産管理から、身上監護、その他のサービスにつきまして、どういった層の方々にサービスを提供していくのが適切であろうかというのを、大変難しい問題でありますので、今年度、モデルケースを想定しまして、そこら辺の整理をしつつ。","voiceIndex":50,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区としては、早くからこういう制度をやってきて、今度は障害者についても入ってくる。いろいろなことを踏まえていきながら、頑張っていただいて、いいものをつくっていただければと思います。ここまでの話が中間のまとめとして報告されたので、我々ももう少し勉強させていただいて、またいろいろ意見がありましたら、出させていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"船波委員","kind":"確認","question":"品川区の社会福祉協議会でやるところと、任意後見制度の役割が分担しているというところが、ちょっとよくわからないので、確認のためにお伺いしたいんです。そうしますと、品川区社会福祉協議会の新サービスということで、１９ページの四角の中にあるようなサービスは、今既に利用しているほんの数名の人たちが対象になるんでしょうか。その辺がちょっとよくわからないので、もう１回、ご説明願います。","respondent":"中川原介護保険担当課長","answer":"ここら辺の切りかえにつきましては、今、社会福祉協議会のほうでも検討中ですので、考え方としては、そういうことになります。全部、今までやっているお客様がリセットされるということではないんです。","voiceIndex":53,"id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"それについては、私もよく読んだり、考えたりしてみます。そこのところで、減免とか、猶予とかいうことをこれから検討するということで、基金の設置というようなご説明もありましたけど、基金を設置して、今までより高い利用料を払わなくてはならなくなったときに、そこから借りることができるようにするとか、そういうことなんでしょうか。","respondent":"中川原介護保険担当課長","answer":"後見制度は、弁護士さんとか専門家が必要な場合、やはりお値段が高くなりますので、高齢者の方は亡くなってから財産が残る場合もありますので、日々のお金はいただかないにしても、そういったリバースモーゲージみたいなことができないかとか、そういった意味で。","voiceIndex":57,"id":"exchange-021"},{"speaker":"嶋委員","kind":"確認","question":"今、リバースモーゲージが出ましたが、品川区も一番最初にリバースモーゲージをやって、その流れがあって、今、またこういうすばらしい内容になってきたということは、ほんとうにいいことだと思います。私どものほうにいっぱい相談がある方は、さわやかサービスのほうに直接相談をしてくださいという形でよろしいのでしょうか。ちょっと確認をいたします。","respondent":"高橋総務部副参事","answer":"今までどおり、権利擁護、または財産保全・管理サービス等につきましては、私どもで相談をすべて受けつけますので、こちらのほうに来ていただければと思います。よろしくお願いしたいと思います。","voiceIndex":59,"id":"exchange-022"},{"speaker":"船波委員","kind":"質問・要望","question":"去年の資料の１０ページで、障害者福祉のところなんですが、「心身障害者の入所施設の増設等を図られたい」というところで、黒印がついているのでどうかと思いますが、他方、要望事項の基準というところでは、抽象的なことや、一般的な表現は具体化して要望項目とするとなっているので、この点について、もうちょっとやはり具体的なことを、ぜひ盛り込んでほしいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者福祉の問題で、国に対しての要望というところでは、昨年、介護保険の問題で、２４ページの(4)で、ちょっと抽象的な言葉で、「実情を踏まえ必要な対策の実施と財政措置を講じられたい」ということで、説明のところに、低所得者の保険料とか利用料の減免という中身が書いてあるんですけれども、介護保険がちょうど１年経って、こういう切実な問題がさらに現実になっているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認なんですけれども、これは品川区の厚生委員会として意見のとりまとめをして、林委員長の名前で提出するわけですよね。確認するのは、今、鈴木委員からお話があったことについて、私もまた別な見解を持っているわけですよ。ですから、ここで各委員が話した内容をそのまま載せるんですか。ですから、できれば時間をいただきたいという気がするんですが、どうしても今日まとめなければいけないんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-025"},{"speaker":"須藤委員","kind":"質問・要望","question":"さっき、要望と回答で、黒丸をついたものは、もう５年間やっているから今回はなしだという話で、今、お二方から出たのは、みんな黒丸がついていることなんです。そうすると、それの出し方というのは、そのまま出したんじゃ意味がないと思うんです。最終的には正副委員長にお任せしますけれど、時間ぎりぎりまで我々も整理をして、文章にまとめて、会派としては出していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-026"},{"speaker":"鶴副委員長","kind":"提案","question":"１６ページの乳幼児の医療費事業について、ここに書いてある、所得制限の撤廃のことを入れてほしいということですけども、先般の品川区の議会の意思としては、要するに共産党が提案したことについて、共産党を除いて、それは認定しなかったわけですよ。それは、共産党の主張であるかもしれないけれども、あまりにも理論的じゃないんじゃないですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"乳幼児医療費助成に関しては、この間の条例提案というのは、品川区に対してということですから、これは東京都に対しての要望ですから、高橋区長も、ぜひ東京都がそういう方向を出せばやりたいということを言われていますし、そういう点では、東京都がそういう施策をとるということに対して反対だということをはっきりされているところはない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"内容としては、対象年齢引き上げというのはもう実施されましたので、それは除いてということなので、全く同じにはならないと思いますので、ちょっとご検討いただけないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-029"},{"speaker":"須藤委員","kind":"意見","question":"先ほど言ったように、皆さん、きょう見て、整理ってできないと思うんです。今、委員長からお話があったように、黒丸をしたのは、何度も何年もやってきて、回答も出てきているんだから、違ったご意見をまた各区で出して、それを特別区福祉委員長会でまた整理しましょうという話です。ここで全部の合意を取るまでといったら、相当時間がかっちゃうと思うので、委員長、そういう方向性でひとつお願いします。","respondent":"林（和）委員長","answer":"ただいま、須藤委員からの提案ですけれども、きょうここで決定するということはなかなか困難であるから、時間をちょっと置いていただいて、各委員からそういう要望事項がありましたら、委員長のほうに提出をしていただいて。","voiceIndex":75,"id":"exchange-030"}]},{"id":"topic-02","title":"改めて、行政視察","agenda":"改めて、行政視察","exchanges":[{"speaker":"船波委員","kind":"質問","question":"ここに１から５に挙げられているような、既にでき上がっている施設であるとか、サービスを見るだけではなくて、それをつくり上げるまでのプロセスについても学ぶために、せっかくですから、ワーキンググループに対して町民として参加した人や、町の職員として担当してきた人の話なども、ぜひ聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"須藤委員","kind":"質問","question":"鷹巣町に拘泥しちゃうと、向こうでノーと言われた場合に動きがとれなくなっちゃうだろうと思うんですけど、その辺はどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-032"},{"speaker":"須藤委員","kind":"質問","question":"鷹巣町で、１、２、３、４、５、それからワーキンググループの人だとか、いっぱい項目を挙げちゃうと、向こうも、そんなにはちょっと無理だという話になってきちゃうと思うんです。ですからむしろ、先ほど船波委員が言ったように、スタートの時点がどういう形で、住民参加というか、声が届いてきたかといったところが見られるようにある程度絞ってなら、先方もいいという話もあろうかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ、このコースでお願いしたいのですが、一つは、鷹巣町のほうでどうしてもやっていただきたい気持ちはあるんですが、当然、ここでも介護保険をやっているわけですから、要は全国の地方自治体で同じ法律のもとで制度がありながら、いろいろな特徴を出してやっているはずですから、宮古市の介護保険のサービス向上委員会のような、そのこともできれば鷹巣町で見ていきたいという気持ちもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-034"},{"speaker":"須藤委員","kind":"意見","question":"どっちでも構わないですけど、さっきありましたように、むしろ逆に、鷹巣町のほうの日程に合わせる。先方が、「うちのほうとしてはこういう準備がある」と、「こっちがいい」と言ったら、そこで行かせてもらうようにして、その辺の柔軟性は、あとは正副委員長にお任せします。ここじゃなきゃいけないというと、向こうも動きが取れないと思うので、お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":33369,"voices":94}},{"id":"h13-20010730-8","meetingId":"h13-cm07","date":"2001年7月30日","dateIso":"2001-07-30","committee":"建設委員会","time":"午後１時０９分～午後３時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１０月１日から、有料化するのは大井町駅と大崎駅と言いましたっけ。これは、前にもちょっと報告があったんですけど、どれぐらいの台数と、それの整理に係わる人は何人ぐらいか、もしわかったら。というのは、料金が、自転車で２,３００円とか、２,５００円で、その設定がどういうあれでなされたかという全体像をちょっと知りたいと思うんで、教えてもらえればと思うんです。","respondent":"中村交通安全担当課長","answer":"管理運営の費用は、それぞれ大体どちらも、１０月から３月分ですけども、１,０００万円ちょっとぐらいの費用を予定をしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"１,３５９台全部入れたとしての計算ですけど、それぞれバイクとかいろいろばらつきがあるから、なかなか出しづらいと思うんですけど、現状としては、どんな計算をなさっているのかということ。それから、今、管理運営費として１,０００万円ちょっとということでしたが、これは３カ月と言いましたか、ちょっと聞き取れなくて。","respondent":"中村交通安全担当課長","answer":"６カ月です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"利用料の算出の根拠を聞きたいんで、そこらにまつわるデータがあれば教えてほしいんです。","respondent":"中村交通安全担当課長","answer":"他区の料金等も勘案させていただきました。上限が、荒川区が５,０００円、それから、中野区、渋谷区、豊島区あたりがそれぞれ３,０００円という料金できているということもありますので、そういうものを合わせまして決めしています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"ちょっとくどいようで申しわけないんですけれども、一つは、２３区で見て、２,５００円、３,０００円というのは平均的なものだということですよね。それと、撤去費じゃなくて、撤去というのは、不法に放置されたものを撤去するお金で、この料金を決めるのは、委託費だとかをベースにして出てきているわけでしょ。その根拠がわかったら、教えてほしい。","respondent":"中村交通安全担当課長、岩田管理工事課長","answer":"使用料の関係につきましては、現在、整備センターの自転車駐車場が２,３００円、それから、大井町駅の東口の民間でやっています自転車駐車場が２,４００円ということで、あと東急等の駐輪場の値段もありますので。現在では、定期利用についてはほぼ９５％、一時利用については８割、これらが一般的には目いっぱいと言うらしいんですが、フル回転でご利用いただいた場合に、収支がとんとんにいくだろうと。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"今、地球温暖化の京都議定書が問題になっていますけど、自転車というのは、ＣＯ2も窒素酸化物も出さない平和な、環境に優しい乗り物で、本来的には奨励しなきゃならない乗り物だと思うんです。６カ月だと１,８００万円ぐらいで、利用率によっていろいろ変動するんですけど、ちょっと高いんじゃないかなという感じがしたもので、質問させてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"横山副委員長","kind":"質問・要望","question":"ちょっと置いた間に持って行かれちゃったという話も聞くんで、そこら辺の撤収に係る状況をちょっと教えていただきたい。罰則ですから、そこまでしなくてもいいと思うんですけど、やはり相手は区民ですから、そういった苦情のないような撤収をやっぱり心がけてほしいなということで、荏原地域にそういったものが欲しいという声を聞くんだけど、そこのところをちょっと教えてください。","respondent":"中村交通安全担当課長","answer":"保管期間の関係ですけど、これにつきましては、先ほどもご報告申し上げましたとおり、撤去をしまして、それからいろいろ告示手続等を行いますので、その間に若干期間がかかりますし、告示が２週間ということを合わせますと、大体それでほぼ最短でも１カ月ぐらいかかっております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"横山副委員長","kind":"確認","question":"そこら辺のところを、先ほどお聞きした。ですから、間違いなく、警告札をつけて３０分なら３０分、１時間なら１時間置いたものに限って持って行っているんだったらまだよくわかるんだけども、置いた途端に持って行かれちゃったという話を聞くので、そういうことをしてないのか、必ず札をつけたものしか持って行っていないのか、ちょっとそこのところを、確認の意味でいま一度。","respondent":"中村交通安全担当課長","answer":"撤去の回数の関係ですけども、これにつきましては、月に１６回ということで、各地域はランダム的にそれぞれ予定して、実施するようにしております。撤去関係の車両４台で、午前、午後と区割りをして、それぞれの地域について実施しているということです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"横山副委員長","kind":"確認","question":"では確認。そうすると、警告札をつけた車両しか撤去していない、原則的にはそうなんですね。それはそれでいいです。もう一つ確認ですけれども、雇上で使っている車は、１日１台使うと、午前と午後で１カ所ずつというか、そういう撤収のサイクルで仕事をしているということなのかな。","respondent":"中村交通安全担当課長","answer":"１カ所といいますか、それぞれ午前中に何カ所か指定しますので、大井町駅だとか広い地域でしたら、１カ所ぐらいという形になろうかと思いますけど、小さい地域であれば、近くを何カ所か組み合わせてという形になるです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"横山副委員長","kind":"質問","question":"荏原地区の保管場所を、ぜひお願いしておきます。持って行かれたほうは頭に来ちゃっていて、我々につらく当たってくるものですから、ぜひ、早期にできるようにお願いしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"警察でも、何分置いたら駐車違反にするかということですが、駐車違反も、運転できない状態は駐車になりますから、即時撤去できるんですが、警察の場合、各県警によって違うと聞いておりますけど、通常１０分とか、１５分とか、そういう基準を設けてやっている。","voiceIndex":21,"id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"一つ使用料について、前に聞いたことがあるんですが、今回も大崎駅、大井町駅があるわけですが、通学に使っている割合というのはどのぐらいあるものなんですかね。それからもう一つは、やるんだったら、撤去というよりも、むしろ逆にこちらから鎖をかけちゃったらどうなんですか。要するに駐車違反をやっているのと同じような形の考えというのがあってもいいんじゃないかと思うんですけど、いかがでしょうか。","respondent":"岩田管理工事課長","answer":"一応、沢田委員のご指摘もございましたし、多くの議員方も指摘されていますけれども、自転車はほんとうに健康のためにもよろしいですし、環境にも優しいものですから、当然、推奨されるべき乗り物だと、区のほうも考えておりますけれども、放置自転車。","voiceIndex":23,"id":"exchange-010"},{"speaker":"辻委員","kind":"意見","question":"前段のほうはわかります。ただ、今後、全区的に広がっていくときに、ただ生活的に大変だとか、障害者はどうだとかというんじゃなくて、いろいろな形で学生が使うという、そういう面からの学割という考え方での減免措置のあり方というものが、何らかの形であってもいいんじゃないかということです。だから、安くしろと言っているわけじゃないわけです。これは今すぐどうのということじゃない。","respondent":"中村交通安全担当課長","answer":"駐車のほうも、確かに車輪どめだとかいろいろあるんですが、車のほうはそう簡単に動かせない、レッカー業者の手配ができないとなかなか移動もできないということと等があって、警察の方は、鍵ステッカーだとか、いろいろな形でやっているという部分があると思うんです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"築舘委員","kind":"意見","question":"自転車はある程度安いとはいっても、かなりのものだし、愛着があると思うんですが、その人たちはどうして取りに来ないんだろうかということがいつも疑問なんです。それについて調べられたことがあるかどうか。直接電話でなんていうのは何本かはもちろんわかっていらっしゃるかと思いますけど、取りに行くときに文句を言われていると思うんですけど、その辺の実態はどういうふうにとらえていらっしゃるか。","respondent":"中村交通安全担当課長","answer":"リサイクルの関係ですけど、我々のほうでは、自転車については、できるだけ乗れるものについてはリサイクルということで、海外供与だとか、ツールド沖縄のほうにそれぞれ寄付したり、それから、うちのほうのふれあい作業所のほうで。","voiceIndex":27,"id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"ちょっと１点だけ。二度にわたってすみません。去年、大井町駅で、本人は買い物に行くのにだらしなくそこらに置いて、３０分ぐらいで帰ってきたらなくなっちゃったとべそかいて、じゃあ、きっと放置自転車で持って行かれたんだからというんで、聞いたら、やっぱりあるというんで、取りに行ったんですよ。８時半ぐらいに取りに行ったのかな。あそこに行く場所がまずわからない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"上山委員","kind":"意見","question":"そういうこともあるんですけれども、区に申し込む見本みたいなものもこちらに出ているんですけれども、例えば申請の仕方なんかも、具体的に地域で言えばどこになるのか、地元でしたら、区の地域センターとか便利なところだと思うんですけど、そういうことについて、利用者への周知というか、そこら辺の考え方を含めて、ちょっと２点になっちゃうかもしれませんが、お尋ねしたいんです。","respondent":"中村交通安全担当課長、佐藤委員長、伊佐都市計画課長","answer":"最初に、今後の考え方については、一応、今年度は大井町駅と大崎駅ですけども、平成１４年度、１５年度とそれぞれ有料化を進める予定があります。ほかにないようですので、質疑を終了いたします。こちらにはございませんが、その後、２３日、２４日には目黒区内の２カ所で、引き続き説明会が開催される予定です。","voiceIndex":32,"id":"exchange-014"},{"speaker":"横山副委員長","kind":"質問","question":"皆さん、考えている間に１点だけ。川の上をずっと走らせちゃうと、かつていろいろと問題があって、反対か何かがあって地下に潜らざるを得ないという経過というか、私はそういうものをちょっと聞いていたものですから、それにかわって、そういった状況を緩和するために、地下に入れてこういった計画が出されたのか。そこら辺の、もとのところを教えてください。","respondent":"伊佐都市計画課長","answer":"品川線の経緯ですが、東京都都市計画交通道路調査特別委員会で、昭和４１年に延伸計画の検討に入ったという経緯があります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"築舘委員","kind":"質問","question":"出入口のところなんですけど、新たに大井北の出入口と、五反田出入口と、中目黒の出入口をつけるということで、既存の高速道路がありますけど、それの出入口との関係で、特に大井北のあたりと五反田の辺はどういうふうに計画されているのか、ちょっと教えてください。","respondent":"伊佐都市計画課長","answer":"ちょっと先ほどのご説明で抜けた部分ですが、今回の品川線は、湾岸線と３号線では接続します。１号線と２号線との接続はございません。１号線というのは羽田浜崎橋の路線で、あれとは接続しない。２号線は目黒線で、そちらは接続させない。","voiceIndex":40,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"確かに、Ｃ１というのはものすごく混むんですよね。みんな都心を抜けてほかの放射高速道路に乗ろうとするので集中するというのを実感するんです。直接今度の路線の問題じゃないんですけども、今、事業中のものの開始時期が、ここで平成１４年と１８年と冒頭に書いてあるんですけども、青葉台までの区間が、実際に利用できるようになるのはいつからなんでしょうか。","respondent":"伊佐都市計画課長","answer":"首都高速道路公団の予定では、平成１８年度中に完成予定ですので、供用開始も平成１８年度となります。","voiceIndex":46,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"これは、相当かかっていますよね。わかりました。これからなんでしょうか。というのは、トンネルだから相当工費もかかるでしょうし、出入口のところはかなり土地を買収しないとだめで、もう市街化されちゃっているところを買収するというので、相当お金がかかるんじゃないかなと思うんで、ちょっと事業費と、その財源構成について、わかったら教えてほしいんですけど。","respondent":"伊佐都市計画課長","answer":"そういう制約もあって、そう何カ所も出入口ができない。目黒川の地下につきましてはアクセスができませんので、出入口を設けられませんので、山手通りの都市計画道路の幅員の中で出入口については配置する。","voiceIndex":50,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"わかりました。それから、問題になるのは、換気所が区内では３カ所ですか、例えば五反田界隈ですと、１４階建てのものがぼんぼん建っていますよね。ある程度ろ過するんですか。そこら辺も教えてほしいんですが、かなり高いものを建てないと、風向きによっては、マンションにもろに入るという苦情が出ていることを考慮すると、相当高くなるんじゃないかと思うんですが、その辺はどうなんでしょうか。","respondent":"伊佐都市計画課長","answer":"換気塔の部分の問題ですが、これについては、例えばＳＰＭ、浮遊粒子状物質とか、粉塵、ＮＯＸ等の処理の問題ですが、今、聞いているところでは、新宿線の換気塔について、ＳＰＭの電気集塵機の設置について実験等を行い、検討しているということです。","voiceIndex":52,"id":"exchange-019"},{"speaker":"辻委員","kind":"質問・要望","question":"実は、これは同じつながりですから、いいものを使っていくということになろかと思うんですけど、その辺の換気塔の形状とか、状況とか、あるいは、今現在の新宿線で進められている考え方なんか、その辺の資料を、今度、ぜひお知らせいただきたい。この説明会にしたって、そんなに十分な形じゃないでしょうし、我々も研究してみたいし、お願いします。この辺が一つあります。その辺はどうなんですか。","respondent":"伊佐都市計画課長","answer":"第１点目の、換気所設置に対する報告ですが、今回、説明会等の経緯を踏まえて、また機会を設けて報告させていただきたいと思います。もちろん、新宿線でいろいろな経過がございまして、それを反映して、いろいろなノウハウをここに配慮していくという説明は受けてあります。","voiceIndex":54,"id":"exchange-020"},{"speaker":"辻委員","kind":"質問・要望","question":"これは、きょう初めてこういう形で報告を受けたということですので、五反田の換気所についてというのは、非常に我々も関心が強い。ちょうどあの辺の周辺に出ちゃうわけですから、今回の換気所は。ですから、その構造がどうだとか、もし先行き機会があれば、我々もぜひ見学とか、勉強に現地を見させてもらいたいなというぐらいの関心がありますので、ご配慮をお願いしたい。それは要望で終わってきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-021"},{"speaker":"辻委員","kind":"質問","question":"素朴な質問なんですけど、資料３を開くと、このカラーがついているところが、要するに正確な幅員道路ということですか。それでいくと、ずっと下にいくと、その道路に引っかかっている家があるじゃないですか。こういうときに、ほんとうはこの道はすっとできていくわけだけど、勝手口が削られていったりしてでこぼこになってこざるを得ない部分があるので、対象になっていくというのはどこなんですか。","respondent":"中島街路事業担当課長","answer":"そういった中では、残った部分で、区のほうに売りたいという申し出があれば、そういうところは積極的に買収をしていきたいと考えています。","voiceIndex":66,"id":"exchange-022"},{"speaker":"辻委員","kind":"質問","question":"補助２６号線のところをやってきているのを見ているわけですから、大体、できてきたところは、ああできるんだなとわかる。こうやって改めて見てみると、削られた家が残った場合はどうするんだろうと考えた。実質的に現場においてはどういう交渉の仕方をしていくのかなと、大変ですね、これ。","respondent":"中島街路事業担当課長","answer":"私ども、実際に交渉する段階では、地権者の方の意向等を十分に考慮しながら、交渉を進めていきたいと考えています。","voiceIndex":68,"id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"それは、ベテランなんですから、よろしくお願いします。もう一つ、最初の取っつきの部分で、一本橋通りを生かしていくのか、それとも、つけかえちゃうのか。今まで、入口は補助２６号線からそのまま来て、ここは三角みたいに変な土地になって残っちゃう。旧一本橋通り、新一本橋通りと出てくる。こういうケースだったら、振っちゃって、代替えにしてというか。","respondent":"中島街路事業担当課長","answer":"今度、新しく線を引いたところが補助１６３号線になる。ですから、入口のところでいきますと、細いほうが今度の補助１６３号線になります。ただ、現道の一本橋通りといいますか、旧１６３号線は区道としてそのまま残ります。","voiceIndex":70,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"ほんとうにこれは、５０年経ってもできないんじゃないかと思うぐらいすごい買収になると思うんですけど、対象は、少しでもかかっている世帯も含めて、どれぐらいなんでしょうか。","respondent":"中島街路事業担当課長","answer":"実際には借地の方もいらっしゃいますし、借家の方もいらっしゃいますし、それから、地権者が今こちらに住んでいないという方も、当然いらっしゃいますので、そういう方につきましても、登記簿等の調査、あるいは一店舗ずつ個別に訪問して調査をしながら。","voiceIndex":72,"id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"もう一つ、補助２６号線がそこまで開通するのと、相当タイムラグがありますよね。補助２６号線が全線開通するのがいつなのかというのと、今出ているのが完成するのは、さっき言われたんだっけ、〔「平成１７年度」と呼ぶ者あり〕１７年度完成予定と言いましたね。その間は、補助２６号線との関係で、何か対策は持っているのかどうなのかということなんですけど。","respondent":"中島街路事業担当課長","answer":"今現在、補助２６号線が、区役所前の交差点のところまで一部開通しているんですけれども、その先の大崎高校以降がまだ整備がされておりませんので、実際に、今整備されている区役所の入口のところの補助２６号線に入ってくる車というのは、ほとんどないという状況ですので。","voiceIndex":74,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"私は、これはおそらく、説明して、商店街を上げての反対運動になっちゃうんじゃないか、わからないですけど。だって、商店街がなくなっちゃうみたいな計画を、そんなに簡単に受け入れられるのかなという思いがあるんです。今まで、こういう説明なんかをやって、感触は得ているんでしょうか。基本的な了解だとか、一期事業で進めたいけど、どうかというような。そこらがあったら、ちょっと。","respondent":"中島街路事業担当課長","answer":"こちらの、これから整備を予定しています補助２６号線から補助２０５号線までの区間につきましては、今回、事業認可をするですので、事業認可という形の説明会はしてございません。","voiceIndex":79,"id":"exchange-027"},{"speaker":"上山委員","kind":"質問","question":"私、聞き漏らしたのなら恐縮なんですけど、補助１６３号線の関係なんですけれども、大崎の環状６号線、山の手通りから百反坂のところまで整備されていて、その後、こちらの、今、区役所があるあたりを整備するということだと思うんですが、ちょっと聞き漏らして申しわけないんですけど、どういうイメージになるんでしょうか。何をどういうふうにイメージをされているのか。","respondent":"中島街路事業担当課長","answer":"黄色いところですか。","voiceIndex":82,"id":"exchange-028"},{"speaker":"上山委員","kind":"質問・要望","question":"それは、ちょっと私が勘違いしましたので。これが連続してうまくいくかどうか別にしましても、最近は、この補助２６号線も含めて、ここら辺の信号のところなんか、最近ものすごく混み始めているんですよね。ぜひ、今後の計画なども含めて、何かありましたら、ご報告を早めにいただればと考えています。私の勘違いでしたので、そこら辺の要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-029"},{"speaker":"横山副委員長","kind":"質問","question":"大変な事業ですよね。今、委員長も時間を急いでいるようですから。そうすると、今は歯が抜けたようになっているわけですから、その辺を区が手当てして、こちらに移って商売をされたらどうですかと言って、買収に当たったりしていかなかったら、とてもじゃないけど、さっき、沢田委員が言われたように、５０年の話になっちゃう。ちょっと、特別委員会との係わりだけちょっと。","respondent":"中谷まちづくり事業部長","answer":"事例を引き出して甘いと言われる見通しかもしれませんが、平成４年当時ですか、補助２０５号線の整備を行ったときに、第１期路線の事業化に向けて説明会を行いまして、このときも、商店街が壊滅するんではないかということで。","voiceIndex":87,"id":"exchange-030"},{"speaker":"横山副委員長","kind":"質問・要望","question":"この事業を進めるには、代替地というか、そういった手立てというのはすごく協力していかなくちゃいけないのと、一つには、やっぱり皆さんがこういった事業に協力していくには、何かメリットがないと。そして、これは大きな問題ですので、今後もやはり委員会として携わっていかなくちゃいけないと思いますので、以後の報告等もしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":44870,"voices":103}},{"id":"h13-20010730-9","meetingId":"h13-cm07","date":"2001年7月30日","dateIso":"2001-07-30","committee":"文教委員会","time":"午後 １時０７分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"それからもう一つは、５月１５日の校医および病院での血液検査の希望者なんですけれども、保護者説明会は１３名ということなんですか、１クラスが１３名ということで、全員を対象にして保護者会ということをやったんでしょうか。どなたか特定されないだけに、不安なような状態が残るように思うんですけれども、何で４名なのかというのが解せないんですけれども、その辺はどうなんでしょうか。","respondent":"久保田学務課長","answer":"ただ、その３人のいずれか、どなたにミスしたのかというのは記憶が曖昧なところもあるんですが、おそらく考えられるのは残りの３人だということがあったんですけれども、それでも希望があれば全員血液検査は受けられますということで。","voiceIndex":6,"id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"再発防止の関係ですけれども、これで見ますと手順等を検証し、改善するよう指示するという話ですね。これは手順上の単なるミスだという形なのか、それとも当日の状況はわかりませんけれども、大体１３人の子どもたちに対して担任とか養護教諭とか看護婦、医師、大体そのメンバーがいるのか、そのあたりの単なる手順等ということだけでいいのかどうか、その辺はどうなんでしょうか。","respondent":"久保田学務課長","answer":"事故が起きたときの状況を若干お話ししますと、ＢＣＧ接種するときにはまず問診と接種と大きく二つの実施状況があります。問診のときには医師１名と看護婦１名、これは理科室で行いました。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山路委員","kind":"質問・要望","question":"二度と起こらないようにというのは、もちろん大事なんですけれども、ちょっと状況を聞かせていただきますと、１３名の児童というのは女生徒ばかりというか、クラスでやったわけですね。その辺の理由があるのかどうなのか。それと、５月１４日の保護者説明会を開催して、今後の対応についてと質疑応答をやったわけですけれども、どういう意見が出たか教えていただきたいと思います。","respondent":"久保田学務課長","answer":"この点については医師会のほうが、医師の立場からいろんな可能性ということからお話ししながら、血液検査を現在やって、幸いにして異常がなかったということから、感染の心配はないというようなことで説明しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"質疑応答の中で、保護者の方は納得されたんですか、納得されなかったんですか。","respondent":"久保田学務課長","answer":"もちろんこういう事故というか、あってはならないミスで生じたものですので、保護者のお気持ちは非常に大きなものもあったかとは思いますけれども、医師会が一つ一つ保護者の方の心配なり、あるいは質問に答えた結果なんですけれども。","voiceIndex":12,"id":"exchange-004"},{"speaker":"川西委員","kind":"質問","question":"重複しているところもありますが、注射針を取り替える責任といいますか、医学的には責任は医師にあるのかどうか。それから、校医および病院にて検査と書いてありますね。それから、社会的に医療ミスみたいなことが昨今、昔はなかったものが話題になって、マスコミに取り上げられるようになったわけですが、ここを聞いておきたいので、答えられたらでいいですから担当された医師は何歳ぐらいなのか、それだけ。","respondent":"久保田学務課長","answer":"したがいまして、それは遵守する義務がありますので、そういう点では医師会で責任を持ってやってもらうということになってあります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"今回は大きなあれはなかったということなんですけれども、たまたま報道されて文教委員会に報告となったのか、もともと今日の文教委員会に報告するつもりではあったんだけれども、その前にマスコミが報道したというのか、その辺をお聞きしたいと思います。","respondent":"久保田学務課長","answer":"これは学校のほうに報告があったということなので、学校からまとめて教育委員会に最終報告が出てきたのが７月１１日ですので、そういう点では、それ以降しかるべき委員会には報告したいというふうに考えていたところです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松澤委員","kind":"確認","question":"この種の報告はこういう形で、先ほどプライバシー云々という話がありましたけれども、大体すべてこの委員会にはちゃんと報告をするということですね、確認をお願いします。","respondent":"久保田学務課長","answer":"そういうことで臨んでいきたいというふうに思っております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"高星委員","kind":"意見","question":"先ほどの次長の話にもあったけれども、結果として実質的な被害がなかったという話。物事は考えようだけれども、相当な批判が出たということも理解しないといけないと思うんです。その辺の危機管理だと思うんです。ケースによって、対応の仕方というのは変わらざるを得ないというふうに思うんだけれども、その辺の危機管理をどういうに考えていくべきなのかということが一つ。","respondent":"指田教育次長","answer":"今後の対応になりますけれども、やはり場合によってはそういうようなところを勘案しながら、できる限り委員会にご報告申し上げてまいりたいと思ってあります。プライバシー保護に十分配慮しつつ、議会のほうにも報告していきたいと、このように基本的には考えてあります。","voiceIndex":22,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"意見","question":"検査の内容、多分プライバシーの問題と引っかかると思うんですけれども、実際にどのようなチェックがされたのかということ。それから、１５日に血液検査を実施して、６月３０日に異常なしという連絡ということで、結果が出る期間の問題と、その後の追跡調査が必要ないのかどうかについてお願いします。","respondent":"久保田学務課長","answer":"ただ、医師会としてもご心配だったら今後いつでも相談窓口は開けておきますし、担当の医師もちゃんと名前をお知らせしてありますので、そういう形でケアを今後もやっていきたいということで説明しております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"川西委員","kind":"確認","question":"モデル実施ということで、大変に期待しているところです。それから、指導員、専任指導員、アルバイトということですが、９月からのモデル実施の際、短期の人件費分の予算、これは施設費でなくていいですから教えてください。それからもう一つ、１０６名の参加申し込みがありということですが、第二延山小学校の児童数はどのぐらいの中ということを伺いたいと思います。","respondent":"富田教育改革担当課長","answer":"初めに、区内の適正配置についてですが、差し当たって今回は校舎の関係で大変ゆとりのあるスペースがありました第二延山小学校で、また学校側のご協力もあってということでモデル実施を行うわけですが、モデル実施の動向等を踏まえながら、今後の全区的な配置について。","voiceIndex":30,"id":"exchange-010"},{"speaker":"川西委員","kind":"質問・要望","question":"たまたま幼稚園が空いたからやるというのは結構なんだけれども、もう少し区内全域的に、そういう要望だとか必要性があるという今の状況の中での判断は把握をきちんと９月から実施しながら、予算の時期でもあるし考えていただきたいと要望しておきます。大変にいいモデル実施の基盤ですからということで、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"桜井委員","kind":"質問・要望","question":"３点ほど質問します。しかし、あえてさらに放課後延長というんでしょうか、学校だけでなくプラスアルファ的なフリーでもあるし、あるいは教室もあるから、それにプラスアルファ的な要素も備えてということなんでしょうけれども、このあたりをどういうふうに親の希望というのか、思いというのか、ちょっと真剣に考える必要が、別の角度であるような気がしています。４時から４時４５分も６年生の勉強会ですね。","respondent":"富田教育改革担当課長","answer":"実は、６月下旬にアンケートを取りました際には、４４０名中２３５名という、やったら参加したいというアンケート調査がございましたが、安全確保の都合上、事前の月間の予定を出してほしいということで募集したものですから、若干数字的には少なくなっているです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"今のお話ですと、実際蓋を開けてみて、希望する子どもたちがどういうふうな割り振りで曜日に来るかということを見て体制を取るということなんですけれども、イメージとして、９月５日に子どもたちが来たところで、指導員がこれだけでは少なすぎるとか、アルバイトがもうちょっと多いとか、そんな計画なんですか。３７人というと、かなり高い出席希望をされていますよね。","respondent":"富田教育改革担当課長","answer":"３ページに載っておりますレイアウトの中で、１階にグループ学習室４０人というのがありますが、ここにまず免許のある指導員を配置しまして、学年ごとの勉強会は、この中で納まる人数であればここを中心に行っていきたいと考えておりまして。","voiceIndex":35,"id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、延べ人数であったにしても１０６名と、各学年でこうなっていると。実際にグループ学習や個別学習を希望する子どもがどういう曜日になるかは別としても、専任指導員１名、指導員１名、アルバイトは何名ですか、支援ボランティアは何名を予定しているのか。だから、はっきり何名、何名というふうに教えてください。","respondent":"富田教育改革担当課長","answer":"専任指導員１名のほか、指導員については３名、アルバイトについては２名、合計６名ということで、現在準備を進めております。","voiceIndex":37,"id":"exchange-014"},{"speaker":"桜井委員","kind":"質問・要望","question":"先に言ったように、１０６名の希望者がいるということは、今の学校の教育だけでは、もうちょっと丁寧に見てほしいとか、あるいは個別に教えてほしいとかという親の希望というのが一方であると思うんです。あえて申し上げたいんですけれども、専任指導員以外に指導員が３名で、指導員は非常勤ですから毎日ではないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"実質的に１０６名の希望に下がっているということで、実施は当該校の教育計画という基本はありますけれども、原則は第二延山小学校になるわけですけれども、近隣の小学校から希望があった場合にどう対応していくのか。本来の教員と指導員の関係の、連絡を密に取るとか出ていますけれども、実際に授業に先走って支障が出てこないかどうか、その点をまず教えてください。","respondent":"富田教育改革担当課長","answer":"これにつきましては、やはりモデル実施をする中で、第二延山小学校の児童の中でどれぐらいあるのか、ただ第二延山小学校しか受け入れないという姿勢でいくつもりでは全くございませんで、できるだけ受け入れられる方向で。","voiceIndex":40,"id":"exchange-016"},{"speaker":"高星委員","kind":"意見","question":"僕らはモデル実施でも何しようと、大事なことだというふうに思います。もう一つ、あそこを改修費は２,０００万円だったか民生費に載っていますね。要するに、子どもたちを遊ばせるといっても、一番先のモデルだからと言っておきながらちょっと聞くのも変な話なんだけれども、５００万円はどんなふうに初度調弁というのは大方使っちゃうのかどうなのか、その辺を大枠で聞きたいと思います。","respondent":"富田教育改革担当課長、指田教育次長","answer":"施設改修費は別にしまして、やはり初度調弁というのは備品と当面の遊具等の購入も若干出てまいります。いろいろご心配の向きもあるかと思います。ただ、今いただきましたように、モデル実施ですので、冒頭申し上げましたように、これからやるのは９月から３カ月毎に検証しながらいろんなことを考えていきたい。","voiceIndex":42,"id":"exchange-017"},{"speaker":"高星委員","kind":"質問","question":"私がいろいろ考えているのは何かと、チャータースクールに移行する、そんなことは全くないかね、それはいいですけれども。それぞれの遊び、それからグループ学習室、そういったところについての担当者がいるだろうというような話があったんですが、すまいるスクールの最高責任者、何かあったときにこうするという判断能力を持っている方がどなたということ、そのことをお聞きしたい。","respondent":"指田教育次長、青木指導課長","answer":"それは、あくまでも専任指導員が基本的には見るという形になります。私のほうからも専任指導員をはじめ、指導員、アルバイトに対しても指導していきたいというふうに考えておりますので、ご理解をいただきたいと思います。","voiceIndex":45,"id":"exchange-018"},{"speaker":"藤田委員長","kind":"質問・要望","question":"特別区文教委員長会の要望事項につきまして、ご協議をお願いしたいと思います。先の文教委員長会で、来年度の２３区の特別区の文教委員長会として、都ないし国に要望事項を提出しようです。したがいまして、今日、各委員からこういう項目を品川区として要望していったらどうかと。事前に皆さんのお手元に要望書をお渡ししていますが、何かございましたらご発言をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"桜井委員","kind":"質問・要望","question":"平成１３年度を参考にして要望していいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"},{"speaker":"桜井委員","kind":"質問","question":"私のほうから三つしたいんですけれども、文言は考えていないんですけれども趣旨でいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"桜井委員","kind":"質問・要望","question":"資料２の１ページ、義務教育の充実とありますね。品川区は３０人学級を求めていきたいというふうに思うんですけれども、これは私どもの意見です。ですから、そういう点ではきちっと都も措置をいただきたいというふうに思うんです。ですから、その点では図書室を充実というところを、文言は委員長にお願いしたいんですけれども希望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"川西委員","kind":"提案","question":"塾が好きで行ける子どももいるし、本当に好きで行っている子どもはそれでいいと。そのためには１名ぐらいの専任指導員の人件費は、やはり今の学校教育の予算の仕組みからすると、都で持つというふうに思いますので、ぜひ２３区の文教委員長会で取り上げられるかどうか別として、品川区からの提案に加えていただきたいと思いますので、担当課長のご意見を、議会の問題ではあるけれども、知事に出すのかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-023"},{"speaker":"高星委員","kind":"質問・要望","question":"何回かいろんな委員会で述べてきたんですけれども、やはり学校の国有地の地代ね、取るなというふうに言えないのかね。要望は毎年出しているの、出しているならいい。これには載ってないの。文教委員会ということで、こちらのほうから出すことが可能じゃないわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、それに見合って結構区独自の予算も計上されていますので、ぜひこれは当区議会としても積極的に改定をいただきたいというのと、増額をお願いしたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-025"},{"speaker":"川西委員","kind":"質問・要望","question":"私もスローガンとしては３０人学級になりますけれども、具体的な要望としては実現可能なところで賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"桜井委員","kind":"提案","question":"この前、私どものほうで少人数学習というか、規模が大きくてもいいんですけれども、そういうところも希望したんですけれども、函館市はそのあたりはないんでしょうか。私は希望としては長野県の小海町、ちょっと小さいんですけれども、結構実績がある町なので、できれば長野県の小海町あたりを提案したいと思うんです。８６年から実施して、常勤で配置をして少人数学級で実績を上げているところなんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"函館市のテーマというのでしょうか、それは生涯学習なんですか、何がテーマなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"川西委員","kind":"提案","question":"私は先ほども発言しましたけれども、学校開放事業、ですから放課後事業ですね。スポーツ開放、それと今たまたま提案された北海道函館市の学校評議員制度、これは品川区でもいろんな意味で取り組みをされているけれども、大変難しい。こういうことが将来真剣に考えていくべきことだと。もちろんインターネットも海外派遣事業も──私はこの案に賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-029"},{"speaker":"桜井委員","kind":"質問","question":"今日、場所を決めるんですか、早いほどいいでしょうけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-030"},{"speaker":"山路委員","kind":"質問","question":"函館は先進事例がしっかりしているわけですから、いいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今日出していただいて、北海道函館市というのはわかったんですけれども、北海道の中でどこか近くであれば、行程的に無理ないところで、札幌なども何かあるのかどうか、そこまで調べていなかったんですが、函館市のほうはわかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"弘前に着いて、帰りはどうするんですか、飛行機ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"桜井委員","kind":"質問・要望","question":"もうちょっと弘前市にしても、函館市にしても、学校インターネットというのがあるんですけれども、さっき申し上げた対応ですね、少人数学級の対応を含めて、できればもう少し希望を入れていただきたいと、視察市をそういう形で決めるとすれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-034"},{"speaker":"松澤委員","kind":"意見","question":"私は２３日はどうしてもだめなので、できれば２４日、２５日、２６日ぐらいで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2001-01-01&TermEnd=2001-12-31"}],"sourceMeta":{"pages":0,"characters":26937,"voices":101}}]);
